  return {glassSizeText: value, dailyGoalText: state.dailyGoalText, entries: state.entries, draft_category: state.draft_category, draft_amount: state.draft_amount, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



