  return {draft_amount: value, dailyGoalText: state.dailyGoalText, glassSizeText: state.glassSizeText, entries: state.entries, draft_category: state.draft_category, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_category) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {category: strings.trim(state.draft_category), amount: strings.toNumber(state.draft_amount, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_category: "", draft_amount: "", dailyGoalText: state.dailyGoalText, glassSizeText: state.glassSizeText, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
