}

function set_restingRate(state: AppState, value: number): AppState {
  return {restingRate: value, age: state.age, heartRateText: state.heartRateText, settingsOpen: state.settingsOpen};
}







function c_zoneOf(percent: number): number {
  let z: number = math.ceil(percent / 20);
  if (z < 1) { z = 1; }
  if (z > 5) { z = 5; }
  return z;
}

