      let restingRate: number = state.restingRate;
      let maxRateFactor: number = 220;
      let maxHeartRate: number = (maxRateFactor - age);
      let heartRateReserve: number = (maxHeartRate - restingRate);
      let intensityPercent: number = math.round((share((heartRate - restingRate), heartRateReserve) * 100));
