import * as ui from "std/ui"

@jsonable
class AppState {
  age: number;
  heartRateText: string;
  restingRate: number;
  settingsOpen: boolean;
}

function init(): AppState {
  return {age: 30, heartRateText: "140", restingRate: 60, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_age(state: AppState, value: number): AppState {
  return {age: value, heartRateText: state.heartRateText, restingRate: state.restingRate, settingsOpen: state.settingsOpen};
}

function set_heartRate(state: AppState, value: string): AppState {
  return {heartRateText: value, age: state.age, restingRate: state.restingRate, settingsOpen: state.settingsOpen};
}

function set_restingRate(state: AppState, value: number): AppState {
  return {restingRate: value, age: state.age, heartRateText: state.heartRateText, settingsOpen: state.settingsOpen};
}







function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, age: state.age, heartRateText: state.heartRateText, restingRate: state.restingRate};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Intensity Checker", "HEART RATE", "See which training zone your heart rate falls in", ""));
  {
      let age: number = state.age;
      let heartRate: number = strings.toNumber(state.heartRateText, 0);
      let restingRate: number = state.restingRate;
      let maxRateFactor: number = 220;
      let maxHeartRate: number = (maxRateFactor - age);
      let heartRateReserve: number = (maxHeartRate - restingRate);
      let intensityPercent: number = math.round((share((heartRate - restingRate), heartRateReserve) * 100));
    sections.push(ui.Section("content", "", "", [ui.NumberField("default", "Your age (years)", state.age, 10, 100, "set_age"), ui.TextField("default", "Heart rate now (bpm)", state.heartRateText, "set_heartRate", "number")]));
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 1, [ui.NumberStat("default", "Intensity", intensityPercent, "", "%", 1, "", "chart", 1)])]));
  }
  {
    let settingsWord: string = "Show";
    if (state.settingsOpen) { settingsWord = "Hide"; }
    sections.push(ui.Section("supporting", "", "", [
      ui.ListItem("default", "Settings", "1 setting", settingsWord, "toggleSettings", 0, true, ""),
      ui.When(state.settingsOpen, ui.Column("default", [ui.NumberField("default", "Resting heart rate (bpm)", state.restingRate, 30, 120, "set_restingRate")]))
    ]));
  }
  return ui.AppTheme("technical", "", sections);
}

