  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {dailyLimit: 120, entries: emptyEntries, draft_category: "", draft_minutes: "", removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}

function whether(holds: boolean): number {
  if (holds) { return 1; }
  return 0;
}



function set_dailyLimit(state: AppState, value: number): AppState {
  return {dailyLimit: value, entries: state.entries, draft_category: state.draft_category, draft_minutes: state.draft_minutes, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_category(state: AppState, value: string): AppState {
  return {draft_category: value, dailyLimit: state.dailyLimit, entries: state.entries, draft_minutes: state.draft_minutes, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_minutes(state: AppState, value: string): AppState {
  return {draft_minutes: value, dailyLimit: state.dailyLimit, entries: state.entries, draft_category: state.draft_category, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_category) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {category: strings.trim(state.draft_category), minutes: strings.toNumber(state.draft_minutes, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_category: "", draft_minutes: "", dailyLimit: state.dailyLimit, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, dailyLimit: state.dailyLimit, draft_category: state.draft_category, draft_minutes: state.draft_minutes, settingsOpen: state.settingsOpen};
