    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, dailyLimit: state.dailyLimit, draft_category: state.draft_category, draft_minutes: state.draft_minutes, settingsOpen: state.settingsOpen};
}

