import * as ui from "std/ui"

@jsonable
class LogEntry {
  amount: number;
  minute: number;
}

@jsonable
class AppState {
  dailyGoal: number;
  entries: LogEntry[];
  draft_amount: string;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {dailyGoal: 8, entries: emptyEntries, draft_amount: "", removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_dailyGoal(state: AppState, value: number): AppState {
  return {dailyGoal: value, entries: state.entries, draft_amount: state.draft_amount, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_amount(state: AppState, value: string): AppState {
  return {draft_amount: value, dailyGoal: state.dailyGoal, entries: state.entries, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_amount) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {amount: strings.toNumber(state.draft_amount, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_amount: "", dailyGoal: state.dailyGoal, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, dailyGoal: state.dailyGoal, draft_amount: state.draft_amount, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, dailyGoal: state.dailyGoal, draft_amount: state.draft_amount, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, dailyGoal: state.dailyGoal, entries: state.entries, draft_amount: state.draft_amount, settingsOpen: state.settingsOpen};
}





function c_daysLeft(state: AppState): number {
  let challengeDays: number = 30;
  let entryCount: number = state.entries.length();
  let left: number = challengeDays - entryCount;
  if (left < 0) { left = 0; }
  return left;
}

function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, dailyGoal: state.dailyGoal, entries: state.entries, draft_amount: state.draft_amount, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "30-Day Water Challenge", "WATER TRACKER", "Log every glass and keep your 30-day streak going", ""));
  {
      let dailyGoal: number = state.dailyGoal;
      let challengeDays: number = 30;
      let entryCount: number = state.entries.length();
      let entryTotal: number = 0;
      for (let e: LogEntry of state.entries) { entryTotal = entryTotal + e.amount; }
      let glassesToday: number = entryTotal;
      let goalProgress: number = math.min(1, share(glassesToday, dailyGoal));
    sections.push(ui.Section("content", "", "", [ui.Progress("accent", "Goal progress", math.round(math.min(math.max(goalProgress, 0), 1) * 1000), 1000)]));
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 1, [ui.NumberStat("default", "Glasses today", glassesToday, "", " glasses", 1, "", "chart", 0)])]));
    let rows: ui.View[] = [];
    let i: number = entryCount - 1;
    while (i >= 0 && i > entryCount - 21) {
      let e: LogEntry = state.entries[i];
      let sub: string = "Added " + ui.clockToString(e.minute);
      rows.push(ui.ListItem("default", ui.formatNumber(e.amount, 0), sub, "", "", 0, false, ""));
      rows.push(ui.ActionBar("end", [ui.Button("secondary", "Remove", "removeEntry", i, true)]));
      i = i - 1;
    }
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Glasses", state.draft_amount, "set_draft_amount", "number"), ui.ActionBar("end", [ui.Button("primary", "Add", "addEntry", 0, strings.trim(state.draft_amount) !== "")])]));
    sections.push(ui.Section("content", "", "", [ui.SectionHeader("default", "Glasses of water", "Newest first", ui.numberToString(entryCount)), ui.When(entryCount === 0, ui.EmptyState("default", "Nothing added yet", "Fill in the fields above and tap Add.", "", "", "list")), ui.When(entryCount > 0, ui.ListGroup("default", "", rows)), ui.When(state.removedEntries.length() > 0, ui.Snackbar("default", "Removed", "Undo", "undoRemove")), ui.Ticker("default", "undoClock", 6000 + state.entries.length() % 7, state.removedEntries.length() > 0, "expireUndo")]));
  }
  {
  {
    let c_challengeDays: number = 30;
    let c_entryCount: number = state.entries.length();
    let c_left: number = c_challengeDays - c_entryCount;
    if (c_left < 0) { c_left = 0; }
    let c_done: number = c_entryCount;
    if (c_done > c_challengeDays) { c_done = c_challengeDays; }
    if (c_entryCount === 0) {
