        ui.MetricGroup("default", 2, [
          ui.NumberStat("accent", "Days left", c_left, "", " of 30", 1, "", "calendar", 0),
          ui.NumberStat("default", "Days logged", c_done, "", "", 1, "", "check", 0)
        ])
      ]));
    }
  }
  }
  {
    let settingsWord: string = "Show";
    if (state.settingsOpen) { settingsWord = "Hide"; }
