import * as ui from "std/ui"

@jsonable
class LogEntry {
  steps: number;
  walkDate: number;
  minute: number;
}

@jsonable
class AppState {
  dailyGoalText: string;
  entries: LogEntry[];
  draft_steps: string;
  draft_walkDate: number;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {dailyGoalText: "8000", entries: emptyEntries, draft_steps: "", draft_walkDate: time.daysSinceEpoch(), removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_dailyGoal(state: AppState, value: string): AppState {
  return {dailyGoalText: value, entries: state.entries, draft_steps: state.draft_steps, draft_walkDate: state.draft_walkDate, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_steps(state: AppState, value: string): AppState {
  return {draft_steps: value, dailyGoalText: state.dailyGoalText, entries: state.entries, draft_walkDate: state.draft_walkDate, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_walkDate(state: AppState, value: number): AppState {
  return {draft_walkDate: value, dailyGoalText: state.dailyGoalText, entries: state.entries, draft_steps: state.draft_steps, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_steps) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {steps: strings.toNumber(state.draft_steps, 0), walkDate: state.draft_walkDate, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_steps: "", dailyGoalText: state.dailyGoalText, draft_walkDate: state.draft_walkDate, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, dailyGoalText: state.dailyGoalText, draft_steps: state.draft_steps, draft_walkDate: state.draft_walkDate, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, dailyGoalText: state.dailyGoalText, draft_steps: state.draft_steps, draft_walkDate: state.draft_walkDate, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, dailyGoalText: state.dailyGoalText, entries: state.entries, draft_steps: state.draft_steps, draft_walkDate: state.draft_walkDate, settingsOpen: state.settingsOpen};
}





