  let emptyEntries: LogEntry[] = [];
  return {goalDaysText: "100", entries: emptyEntries, draft_dayNumber: "", draft_bookTitle: "", draft_minutesRead: "", removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_goalDays(state: AppState, value: string): AppState {
  return {goalDaysText: value, entries: state.entries, draft_dayNumber: state.draft_dayNumber, draft_bookTitle: state.draft_bookTitle, draft_minutesRead: state.draft_minutesRead, removedEntries: state.removedEntries, removedAt: state.removedAt};
}



function set_draft_dayNumber(state: AppState, value: string): AppState {
  return {draft_dayNumber: value, goalDaysText: state.goalDaysText, entries: state.entries, draft_bookTitle: state.draft_bookTitle, draft_minutesRead: state.draft_minutesRead, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_bookTitle(state: AppState, value: string): AppState {
  return {draft_bookTitle: value, goalDaysText: state.goalDaysText, entries: state.entries, draft_dayNumber: state.draft_dayNumber, draft_minutesRead: state.draft_minutesRead, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_minutesRead(state: AppState, value: string): AppState {
  return {draft_minutesRead: value, goalDaysText: state.goalDaysText, entries: state.entries, draft_dayNumber: state.draft_dayNumber, draft_bookTitle: state.draft_bookTitle, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_bookTitle) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {dayNumber: strings.toNumber(state.draft_dayNumber, 0), bookTitle: strings.trim(state.draft_bookTitle), minutesRead: strings.toNumber(state.draft_minutesRead, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_dayNumber: "", draft_bookTitle: "", draft_minutesRead: "", goalDaysText: state.goalDaysText, removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, goalDaysText: state.goalDaysText, draft_dayNumber: state.draft_dayNumber, draft_bookTitle: state.draft_bookTitle, draft_minutesRead: state.draft_minutesRead};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, goalDaysText: state.goalDaysText, draft_dayNumber: state.draft_dayNumber, draft_bookTitle: state.draft_bookTitle, draft_minutesRead: state.draft_minutesRead};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
