  draft_minutes: string;
  draft_noteItem: string;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {goalDaysText: "30", dailyMinutesText: "10", entries: emptyEntries, draft_minutes: "", draft_noteItem: "", removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



