  return {goalDaysText: value, dailyMinutesText: state.dailyMinutesText, entries: state.entries, draft_minutes: state.draft_minutes, draft_noteItem: state.draft_noteItem, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_dailyMinutes(state: AppState, value: string): AppState {
  return {dailyMinutesText: value, goalDaysText: state.goalDaysText, entries: state.entries, draft_minutes: state.draft_minutes, draft_noteItem: state.draft_noteItem, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_minutes(state: AppState, value: string): AppState {
