  return {draft_noteItem: value, goalDaysText: state.goalDaysText, dailyMinutesText: state.dailyMinutesText, entries: state.entries, draft_minutes: state.draft_minutes, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_noteItem) === "") { return state; }
  let none: LogEntry[] = [];
