  return {doses7: withDose7(state.doses7, at, changed), pending7: -1, doseNote7: note, streak7: state.streak7, streakDay7: state.streakDay7, draftName7: state.draftName7, draftMinute7: state.draftMinute7};
}

function removeDose7(state: AppState, index: number): AppState {
