function c_isVowel(ch: string): boolean {
  let lower: string = strings.toLowerCase(ch);
  return lower === "a" || lower === "e" || lower === "i" || lower === "o" || lower === "u";
}

function c_toPigLatin(word: string): string {
  let w: string = strings.trim(word);
  if (strings.length(w) === 0) { return ""; }
  let lower: string = strings.toLowerCase(w);
  let first: string = strings.substring(lower, 0, 1);
  if (c_isVowel(first)) {
    return lower + "way";
  }
  let i: number = 0;
  let n: number = strings.length(lower);
  while (i < n && !c_isVowel(strings.substring(lower, i, i + 1))) {
    i = i + 1;
  }
  if (i >= n) {
    return lower + "ay";
  }
  let cluster: string = strings.substring(lower, 0, i);
  let rest: string = strings.substring(lower, i, n);
  return rest + cluster + "ay";
}

