        "Type some text above and it appears here backwards.", "", "", "list")),
    ui.When(strings.length(state.sourceText) > 0,
      ui.Card("surface", [
        ui.Text("title", c_reversed)
      ]))
  ]));
  }
  return ui.AppTheme("technical", "", sections);
}

