import * as ui from "std/ui"

@jsonable
class AppState {
  shift: number;
  directionIndex: number;
  message: string;
}

function init(): AppState {
  return {shift: 3, directionIndex: 0, message: ""};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_shift(state: AppState, value: number): AppState {
  return {shift: value, directionIndex: state.directionIndex, message: state.message};
}

function set_direction(state: AppState, value: number): AppState {
  return {directionIndex: value, shift: state.shift, message: state.message};
}

function set_message(state: AppState, value: string): AppState {
  return {message: value, shift: state.shift, directionIndex: state.directionIndex};
}







function c_effectiveShift(state: AppState): number {
  if (state.directionIndex === 0) { return state.shift; }
  return 26 - state.shift;
}

function c_shiftChar(ch: string, shift: number): string {
  let code: number = 0;
  let base: number = 0;
  let upper: string = strings.toUpperCase(ch);
  if (upper === ch && ch !== strings.toLowerCase(ch)) {
    base = 65;
  } else if (ch === strings.toLowerCase(ch) && upper !== ch) {
    base = 97;
  } else {
    return ch;
  }
  let letters: string = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  let idx: number = -1;
  let i: number = 0;
  while (i < 26) {
    if (strings.substring(letters, i, i + 1) === upper) { idx = i; }
    i = i + 1;
  }
  if (idx < 0) { return ch; }
  let moved: number = (idx + shift) % 26;
  if (moved < 0) { moved = moved + 26; }
  let out: string = strings.substring(letters, moved, moved + 1);
  if (base === 97) { return strings.toLowerCase(out); }
  return out;
}

function c_cipher(state: AppState): string {
  let shift: number = c_effectiveShift(state);
  let result: string = "";
  for (let ch: string of state.message) {
    result = result + c_shiftChar(ch, shift);
  }
  return result;
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Caesar Cipher", "CIPHER", "Shift letters to encode or decode a message", ""));
  {
      let shift: number = state.shift;
      let directionValues: number[] = [0, 1];
      let direction: number = directionValues[state.directionIndex];
    sections.push(ui.Section("content", "", "", [ui.NumberField("default", "Shift (letters)", state.shift, 1, 25, "set_shift"), ui.Select("default", "Direction", ["Encode", "Decode"], state.directionIndex, "set_direction"), ui.TextField("default", "Message", state.message, "set_message")]));
  }
  {
  {
    let c_shift: number = state.shift;
    let c_eff: number = c_effectiveShift(state);
    let c_out: string = c_cipher(state);
    let c_rows: ui.View[] = [];
    c_rows.push(ui.NumberStat("accent", "Effective shift", c_eff, "", "", 1, "letters moved forward", ""));
    c_rows.push(ui.KeyValueItem("default", "Direction", "Encode", ""));
    if (state.directionIndex === 1) {
      c_rows.pop();
      c_rows.push(ui.KeyValueItem("default", "Direction", "Decode", ""));
    }
    sections.push(ui.Section("summary", "Result", "", [
      ui.MetricGroup("default", 2, c_rows),
      ui.When(state.message.length() === 0,
        ui.EmptyState("default", "No message yet", "Type a message above to see it shifted.", "", "", "")),
      ui.When(state.message.length() > 0,
        ui.Card("surface", [
          ui.SectionHeader("default", "Shifted message", "", ""),
          ui.Text("body", c_out)
        ]))
    ]));
  }
  }
  return ui.AppTheme("technical", "", sections);
}

