function c_charCode(ch: string): number {
  let codes: string = " !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~";
  let i: number = 0;
  while (i < codes.length()) {
    if (strings.substring(codes, i, i + 1) === ch) { return i + 32; }
    i = i + 1;
  }
  return -1;
}

function c_codeChar(code: number): string {
  let codes: string = " !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~";
  if (code < 32 || code > 126) { return ""; }
  return strings.substring(codes, code - 32, code - 31);
}

function c_toAscii(text: string): string {
  let out: string = "";
  let i: number = 0;
  while (i < text.length()) {
    let code: number = c_charCode(strings.substring(text, i, i + 1));
    if (code >= 0) {
      if (out.length() > 0) { out = out + " "; }
      out = out + ui.numberToString(code);
    }
    i = i + 1;
  }
  return out;
}

function c_toText(codes: string): string {
  let out: string = "";
  let token: string = "";
  let i: number = 0;
  while (i <= codes.length()) {
    let ch: string = "";
    if (i < codes.length()) { ch = strings.substring(codes, i, i + 1); }
    if (ch === " " || ch === "," || i === codes.length()) {
      if (token.length() > 0) {
        let n: number = strings.toNumber(token, -1);
        if (n >= 0) { out = out + c_codeChar(n); }
        token = "";
      }
    } else {
      token = token + ch;
    }
    i = i + 1;
  }
  return out;
}

