import * as ui from "std/ui"

@jsonable
class AppState {
  message: string;
}

function init(): AppState {
  return {message: ""};
}

function setMessage(state: AppState, value: string): AppState {
  return {message: value};
}

function rot13(text: string): string {
  let out: string = "";
  for (let ch: string of text) {
    let code: number = 0;
    let upper: string = strings.toUpperCase(ch);
    let lower: string = strings.toLowerCase(ch);
    if (upper === ch && ch !== lower) {
      code = (ch.charCodeAt(0) - 65 + 13) % 26 + 65;
      out = out + strings.substring("ABCDEFGHIJKLMNOPQRSTUVWXYZ", code - 65, code - 64);
    } else if (lower === ch && ch !== upper) {
      code = (ch.charCodeAt(0) - 97 + 13) % 26 + 97;
      out = out + strings.substring("abcdefghijklmnopqrstuvwxyz", code - 97, code - 96);
    } else {
      out = out + ch;
    }
  }
  return out;
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}











function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "ROT13 Encoder", "TEXT CIPHER", "Shift every letter 13 places", ""));
  {
      let shift: number = 13;
      let encodedText: string = rot13(state.message);
    sections.push(ui.Section("content", "", "", [ui.TextField("multiline", "Message", state.message, "setMessage")]));
    sections.push(ui.Section("hero", "", "", [ui.Hero("accent", "Encoded", encodedText, "", [])]));
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 1, [ui.NumberStat("default", "Letter shift", shift, "", "", 1, "", "chart", 0)])]));
  }
  return ui.AppTheme("technical", "", sections);
}

