  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {maxMissing: 2, entries: emptyEntries, draft_ingredient: "", removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_maxMissing(state: AppState, value: number): AppState {
  return {maxMissing: value, entries: state.entries, draft_ingredient: state.draft_ingredient, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_ingredient(state: AppState, value: string): AppState {
  return {draft_ingredient: value, maxMissing: state.maxMissing, entries: state.entries, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_ingredient) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {ingredient: strings.trim(state.draft_ingredient), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_ingredient: "", maxMissing: state.maxMissing, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, maxMissing: state.maxMissing, draft_ingredient: state.draft_ingredient, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
