  if (b === 0) { return 0; }
  return a / b;
}



function set_wateringFrequency(state: AppState, value: number): AppState {
  return {wateringFrequencyIndex: value};
}







function c_intervalFor(index: number): number {
  if (index === 0) { return 1; }
  if (index === 1) { return 3; }
  if (index === 2) { return 7; }
  return 14;
}

function c_matches(interval: number, target: number): boolean {
  let diff: number = interval - target;
  if (diff < 0) { diff = -diff; }
  if (target <= 3) { return diff <= 2; }
  if (target <= 7) { return diff <= 3; }
  return diff <= 5;
}

function view(state: AppState): ui.View {
