    let c_intervals: number[] = [14, 14, 7, 7, 3, 14, 14, 3, 3, 7, 7, 14, 7, 7];
    let c_notes: string[] = [
      "Low light is fine; let soil dry out fully.",
      "Tolerates dim corners; water only when bone dry.",
      "Bright indirect light; water when top soil is dry.",
