      "Medium indirect light; droops when thirsty.",
      "Full sun; gritty soil, soak then dry out.",
      "Bright sun; water sparingly, never soggy.",
      "Shade to indirect light; loves humidity.",
      "Indirect light; keep evenly moist, no direct sun.",
      "Bright indirect light; wipe leaves, let dry between.",
      "Medium indirect light; water when top inch is dry.",
      "Full sun; soak rarely and let dry completely.",
      "Bright indirect light; soak weekly, drain well.",
      "Low to medium light; water when top soil dries."
    ];
    let c_rows: ui.View[] = [];
    let c_count: number = 0;
    let c_i: number = 0;
    while (c_i < c_names.length()) {
      if (c_matches(c_intervals[c_i], c_target)) {
        c_count = c_count + 1;
        c_rows.push(ui.ListItem("default", c_names[c_i], c_notes[c_i], "every " + ui.numberToString(c_intervals[c_i]) + " days", "", 0, true, ""));
      }
      c_i = c_i + 1;
    }
    sections.push(ui.Section("content", "Plants for your routine", "About every " + ui.numberToString(c_target) + " days", [
      ui.When(c_count === 0, ui.EmptyState("default", "No plants match", "Try a different watering frequency above.", "", "", "")),
      ui.When(c_count > 0, ui.ListGroup("default", "", c_rows))
    ]));
