  let currency7: string = "$";
  return {filterCategoryIndex: 0, labels7: labels7, records7: records7, draftWho7: 0, draftAmount7: "", draftNote7: "", currency7: currency7};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_filterCategory(state: AppState, value: number): AppState {
