@jsonable
class AppState {
  elapsedMs: number;
  running: boolean;
  finished: boolean;
  vacationDate: number;
  vacationSeconds: number;
  settingsOpen: boolean;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, vacationDate: 540, vacationSeconds: 32400, settingsOpen: false};
}

function countdownSeconds(state: AppState): number {
  let vacationDate: number = state.vacationDate;
  let vacationSeconds: number = state.vacationSeconds;
  let secondsPerDay: number = 86400;
  return vacationSeconds;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, vacationDate: state.vacationDate, vacationSeconds: state.vacationSeconds, settingsOpen: state.settingsOpen}; }
  return {elapsedMs: total, running: false, finished: true, vacationDate: state.vacationDate, vacationSeconds: state.vacationSeconds, settingsOpen: state.settingsOpen};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, vacationDate: state.vacationDate, vacationSeconds: state.vacationSeconds, settingsOpen: state.settingsOpen};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, vacationDate: state.vacationDate, vacationSeconds: state.vacationSeconds, settingsOpen: state.settingsOpen};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, vacationDate: state.vacationDate, vacationSeconds: state.vacationSeconds, settingsOpen: state.settingsOpen};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_vacationDate(state: AppState, value: number): AppState {
  return {vacationDate: value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, vacationSeconds: state.vacationSeconds, settingsOpen: state.settingsOpen};
}

function set_vacationSeconds(state: AppState, value: number): AppState {
  return {vacationSeconds: value, elapsedMs: 0, running: false, finished: false, vacationDate: state.vacationDate, settingsOpen: state.settingsOpen};
}







function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, vacationDate: state.vacationDate, vacationSeconds: state.vacationSeconds};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Vacation Countdown", "TRIP TIMER", "Count down the days until your vacation starts.", "clock"));
  {
    sections.push(ui.Ticker("default", "clock", 200, state.running, "onTick"));
      let vacationDate: number = state.vacationDate;
      let vacationSeconds: number = state.vacationSeconds;
      let secondsPerDay: number = 86400;
