      let remaining: number = duration - elapsed;
    sections.push(ui.Section("hero", "", "", [ui.Hero("accent", "Time until vacation", ui.durationToString(math.ceil(remaining)), "", [ui.ActionBar("spread", [ui.Button("primary", "Start", "onStart", 0, !state.running), ui.Button("secondary", "Stop", "onStop", 0, state.running), ui.Button("secondary", "Reset", "onReset", 0, true)])])]));
    sections.push(ui.Section("content", "", "", [ui.NumberField("default", "Seconds until vacation", state.vacationSeconds, 1, 129600, "set_vacationSeconds")]));
