import * as ui from "std/ui"

@jsonable
class AppState {
  tripDate: string;
  sleepsPerNight: number;
  settingsOpen: boolean;
}

function init(): AppState {
  return {tripDate: "", sleepsPerNight: 1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_tripDate(state: AppState, value: string): AppState {
  return {tripDate: value, sleepsPerNight: state.sleepsPerNight, settingsOpen: state.settingsOpen};
}

function set_sleepsPerNight(state: AppState, value: number): AppState {
  return {sleepsPerNight: value, tripDate: state.tripDate, settingsOpen: state.settingsOpen};
}







function c_daysUntil(state: AppState): number {
  let tripMs: number = strings.toNumber(state.tripDate, 0);
  if (tripMs <= 0) { return 0; }
  let nowMs: number = time.nowMillis();
  let diff: number = tripMs - nowMs;
  if (diff <= 0) { return 0; }
  return math.ceil(diff / 86400000);
}

function c_sleepsUntil(state: AppState): number {
  return c_daysUntil(state) * state.sleepsPerNight;
}

function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, tripDate: state.tripDate, sleepsPerNight: state.sleepsPerNight};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Sleeps Until Trip", "TRIP COUNTDOWN", "Count the nights until your trip begins", ""));
  {
      let sleepsPerNight: number = state.sleepsPerNight;
      let msPerDay: number = 86400000;
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Trip start date", state.tripDate, "set_tripDate")]));
  }
  {
  {
    let days: number = c_daysUntil(state);
    let sleeps: number = c_sleepsUntil(state);
    let hasDate: boolean = strings.toNumber(state.tripDate, 0) > 0;
    let rows: ui.View[] = [];
    rows.push(ui.NumberStat("accent", "Days until trip", days, "", "", 1, "calendar days", "calendar"));
    rows.push(ui.NumberStat("default", "Sleeps until trip", sleeps, "", "", 1, "nights of sleep", "clock"));
    let body: ui.View[] = [];
    body.push(ui.MetricGroup("default", 2, rows));
    if (!hasDate) {
      body.push(ui.Text("caption", "Set the trip start date above to see the countdown."));
    }
    sections.push(ui.Section("summary", "Countdown", "", body));
  }
  }
  {
    let settingsWord: string = "Show";
    if (state.settingsOpen) { settingsWord = "Hide"; }
    sections.push(ui.Section("supporting", "", "", [
      ui.ListItem("default", "Settings", "1 setting", settingsWord, "toggleSettings", 0, true, ""),
      ui.When(state.settingsOpen, ui.Column("default", [ui.NumberField("default", "Sleeps per night", state.sleepsPerNight, 1, 1, "set_sleepsPerNight")]))
    ]));
  }
  return ui.AppTheme("clean", "", sections);
}

