@jsonable
class AppState {
  startDate: string;
  endDate: string;
}

function init(): AppState {
  return {startDate: "", endDate: ""};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_startDate(state: AppState, value: string): AppState {
  return {startDate: value, endDate: state.endDate};
}

function set_endDate(state: AppState, value: string): AppState {
  return {endDate: value, startDate: state.startDate};
}







function c_parseDay(s: string): number {
  let t: string = strings.trim(s);
  if (strings.length(t) === 0) { return 0; }
  let parts: string[] = strings.split(t, "-");
  if (parts.length() !== 3) { return 0; }
  let y: number = strings.toNumber(parts[0], 0);
  let m: number = strings.toNumber(parts[1], 0);
  let d: number = strings.toNumber(parts[2], 0);
  if (y < 1 || m < 1 || m > 12 || d < 1 || d > 31) { return 0; }
  let yy: number = y;
  let mm: number = m;
  if (mm <= 2) { yy = yy - 1; }
  let era: number = math.floor(yy / 400);
  let yoe: number = yy - era * 400;
  let mp: number = mm + 9;
  if (mm > 2) { mp = mm - 3; }
  let doy: number = math.floor((153 * mp + 2) / 5) + d - 1;
  let doe: number = yoe * 365 + math.floor(yoe / 4) - math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

function c_daysApart(state: AppState): number {
  let a: number = c_parseDay(state.startDate);
  let b: number = c_parseDay(state.endDate);
  return b - a;
}

function c_weeksBetween(state: AppState): number {
  return c_daysApart(state) / 7;
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Weeks Between Dates", "DATE GAP", "Count the weeks between any two dates", ""));
  {
      let daysPerWeek: number = 7;
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Start date", state.startDate, "set_startDate"), ui.TextField("default", "End date", state.endDate, "set_endDate")]));
  }
  {
  {
    let c_days: number = c_daysApart(state);
    let c_weeks: number = c_weeksBetween(state);
    let c_valid: boolean = strings.length(strings.trim(state.startDate)) > 0 && strings.length(strings.trim(state.endDate)) > 0;
    let c_metrics: ui.View[] = [];
    c_metrics.push(ui.NumberStat("default", "Days apart", c_days, "", "", 1, "", "calendar"));
    c_metrics.push(ui.NumberStat("accent", "Weeks between", c_weeks, "", "", 1, "days / 7", "chart"));
    sections.push(ui.Section("summary", "Result", "From the two dates above", [
      ui.When(c_valid, ui.MetricGroup("default", 2, c_metrics)),
      ui.When(!c_valid, ui.InsetBanner("default", "Enter both dates", "Type a start and an end date as YYYY-MM-DD to see the gap.", "", "", "info"))
    ]));
  }
  }
  return ui.AppTheme("technical", "", sections);
}

