@jsonable
class AppState {
  weddingDate: string;
  c_weddingDay: number;
}

function init(): AppState {
  return {weddingDate: "", c_weddingDay: 0};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_weddingDate(state: AppState, value: string): AppState {
  return {weddingDate: value, c_weddingDay: state.c_weddingDay};
}







function c_parseDay(text: string): number {
  let t: string = strings.trim(text);
  if (strings.length(t) === 0) { return 0; }
  let parts: string[] = strings.split(t, "-");
  if (parts.length() !== 3) { return 0; }
  let y: number = strings.toNumber(parts[0], 0);
  let m: number = strings.toNumber(parts[1], 0);
  let d: number = strings.toNumber(parts[2], 0);
  if (y < 1970 || m < 1 || m > 12 || d < 1 || d > 31) { return 0; }
  let days: number = 0;
  let yy: number = 1970;
  while (yy < y) {
    if ((yy % 4 === 0 && yy % 100 !== 0) || yy % 400 === 0) {
      days = days + 366;
    } else {
      days = days + 365;
    }
    yy = yy + 1;
  }
  let mm: number = 1;
  while (mm < m) {
    if (mm === 2) {
      if ((y % 4 === 0 && y % 100 !== 0) || y % 400 === 0) {
        days = days + 29;
      } else {
        days = days + 28;
      }
    } else if (mm === 4 || mm === 6 || mm === 9 || mm === 11) {
      days = days + 30;
    } else {
      days = days + 31;
    }
    mm = mm + 1;
  }
  days = days + d - 1;
  return days;
}

function c_daysLeft(state: AppState): number {
  if (state.c_weddingDay <= 0) { return 0; }
  let today: number = time.daysSinceEpoch();
  let diff: number = state.c_weddingDay - today;
  if (diff < 0) { return 0; }
  return math.ceil(diff / 1);
}

function c_setDate(state: AppState, value: string): AppState {
  return {weddingDate: value, c_weddingDay: c_parseDay(value)};
}

