}

function set_draft_payout(state: AppState, value: string): AppState {
  return {draft_payout: value, startingBankrollText: state.startingBankrollText, entries: state.entries, draft_numberItem: state.draft_numberItem, draft_color: state.draft_color, draft_bet: state.draft_bet, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_color) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {numberItem: strings.toNumber(state.draft_numberItem, 0), color: strings.trim(state.draft_color), bet: strings.toNumber(state.draft_bet, 0), payout: strings.toNumber(state.draft_payout, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_numberItem: "", draft_color: "", draft_bet: "", draft_payout: "", startingBankrollText: state.startingBankrollText, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, startingBankrollText: state.startingBankrollText, draft_numberItem: state.draft_numberItem, draft_color: state.draft_color, draft_bet: state.draft_bet, draft_payout: state.draft_payout, settingsOpen: state.settingsOpen};
