  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, startingBankrollText: state.startingBankrollText, draft_numberItem: state.draft_numberItem, draft_color: state.draft_color, draft_bet: state.draft_bet, draft_payout: state.draft_payout, settingsOpen: state.settingsOpen};
}

