import * as ui from "std/ui"

@jsonable class C_Pick {
  numbers: number[];
  day: number;
  minute: number;
}

@jsonable
class AppState {
  pickCount: number;
  maxNumber: number;
  c_picks: C_Pick[];
  c_current: number[];
  c_selected: number;
  c_trigger: number;
  c_seed: number;
}

function init(): AppState {
  return {pickCount: 6, maxNumber: 49, c_picks: [], c_current: [], c_selected: -1, c_trigger: 0, c_seed: 7};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_pickCount(state: AppState, value: number): AppState {
  return {pickCount: value, maxNumber: state.maxNumber, c_picks: state.c_picks, c_current: state.c_current, c_selected: state.c_selected, c_trigger: state.c_trigger, c_seed: state.c_seed};
}

function set_maxNumber(state: AppState, value: number): AppState {
  return {maxNumber: value, pickCount: state.pickCount, c_picks: state.c_picks, c_current: state.c_current, c_selected: state.c_selected, c_trigger: state.c_trigger, c_seed: state.c_seed};
}







function c_draw(state: AppState, ignored: number): AppState {
  let max: number = state.maxNumber;
  let count: number = state.pickCount;
  if (count > max) { count = max; }
  let seed: number = state.c_seed;
  let pool: number[] = [];
  let i: number = 1;
  while (i <= max) {
    pool.push(i);
    i = i + 1;
  }
  let chosen: number[] = [];
  let k: number = 0;
  while (k < count && pool.length() > 0) {
    seed = math.randomStep(seed);
    let idx: number = math.randomBelow(seed, pool.length());
    let picked: number = pool[idx];
    let rest: number[] = [];
    let j: number = 0;
    while (j < pool.length()) {
      if (j !== idx) { rest.push(pool[j]); }
      j = j + 1;
    }
    pool = rest;
    chosen.push(picked);
    k = k + 1;
  }
  let entry: C_Pick = {
    numbers: chosen,
    day: time.daysSinceEpoch(),
    minute: time.hourOfDay() * 60 + time.minuteOfHour()
  };
  let out: C_Pick[] = [];
  for (let old: C_Pick of state.c_picks) {
    out.push(old);
  }
  out.push(entry);
  return {c_picks: out, c_current: chosen, c_selected: out.length() - 1, c_trigger: state.c_trigger + 1, c_seed: seed, pickCount: state.pickCount, maxNumber: state.maxNumber};
}

function c_select(state: AppState, value: number): AppState {
  let idx: number = math.floor(value);
  if (idx < 0 || idx >= state.c_picks.length()) {
    return {pickCount: state.pickCount, maxNumber: state.maxNumber, c_picks: state.c_picks, c_current: state.c_current, c_selected: state.c_selected, c_trigger: state.c_trigger, c_seed: state.c_seed};
  }
  let entry: C_Pick = state.c_picks[idx];
  let copy: number[] = [];
  for (let n: number of entry.numbers) {
    copy.push(n);
  }
  return {c_selected: idx, c_current: copy, c_trigger: state.c_trigger + 1, pickCount: state.pickCount, maxNumber: state.maxNumber, c_picks: state.c_picks, c_seed: state.c_seed};
}

function c_clear(state: AppState, ignored: number): AppState {
  let empty: C_Pick[] = [];
  let none: number[] = [];
  return {c_picks: empty, c_current: none, c_selected: -1, pickCount: state.pickCount, maxNumber: state.maxNumber, c_trigger: state.c_trigger, c_seed: state.c_seed};
}

function c_has(numbers: number[], n: number): boolean {
  for (let v: number of numbers) {
    if (v === n) { return true; }
  }
  return false;
}

