    sections.push(ui.Section("content", "", "", [ui.NumberField("default", "Numbers per pick", state.pickCount, 1, 10, "set_pickCount"), ui.NumberField("default", "Highest number", state.maxNumber, 10, 99, "set_maxNumber")]));
  }
  {
  {
    let max: number = state.maxNumber;
    let balls: ui.View[] = [];
    let b: number = 1;
    while (b <= max) {
      let hit: boolean = c_has(state.c_current, b);
      let style: string = "default";
