      balls.push(ui.Cell(style, ui.numberToString(b), "", 0, true));
      b = b + 1;
    }
    let grid: ui.View = ui.Grid("compact", 7, balls);
    let animated: ui.View = ui.Motion("tumble", state.c_trigger, [grid]);
    let rows: ui.View[] = [];
    let r: number = state.c_picks.length() - 1;
    while (r >= 0) {
      let p: C_Pick = state.c_picks[r];
