      r = r - 1;
    }
    sections.push(ui.Section("content", "Draw", "Tap draw to shuffle and settle on your numbers", [
      animated,
      ui.ActionBar("spread", [
        ui.Button("primary", "Draw numbers", "c_draw", 0, true),
        ui.Button("secondary", "Clear history", "c_clear", 0, state.c_picks.length() > 0)
      ])
    ]));
