  while (i <= max) {
    pool.push(i);
    i = i + 1;
  }
  let chosen: number[] = [];
  let k: number = 0;
  while (k < count && pool.length() > 0) {
    seed = math.randomStep(seed);
    let idx: number = math.randomBelow(seed, pool.length());
    let picked: number = pool[idx];
    let rest: number[] = [];
    let j: number = 0;
    while (j < pool.length()) {
      if (j !== idx) { rest.push(pool[j]); }
      j = j + 1;
    }
    pool = rest;
    chosen.push(picked);
    k = k + 1;
  }
  let entry: C_Pick = {
    numbers: chosen,
    day: time.daysSinceEpoch(),
    minute: time.hourOfDay() * 60 + time.minuteOfHour()
  };
  let out: C_Pick[] = [];
  for (let old: C_Pick of state.c_picks) {
    out.push(old);
  }
  out.push(entry);
  return {c_picks: out, c_current: chosen, c_selected: out.length() - 1, c_trigger: state.c_trigger + 1, c_seed: seed__PASSTHROUGH__};
}

