<functions>
function c_cardName(index: number): string {
  if (index === 0) { return "The Fool"; }
  if (index === 1) { return "The Magician"; }
  if (index === 2) { return "The High Priestess"; }
  if (index === 3) { return "The Empress"; }
  if (index === 4) { return "The Emperor"; }
  if (index === 5) { return "The Hierophant"; }
  if (index === 6) { return "The Lovers"; }
  if (index === 7) { return "The Chariot"; }
  if (index === 8) { return "Strength"; }
  if (index === 9) { return "The Hermit"; }
  if (index === 10) { return "Wheel of Fortune"; }
  if (index === 11) { return "Justice"; }
  if (index === 12) { return "The Hanged Man"; }
  if (index === 13) { return "Death"; }
  if (index === 14) { return "Temperance"; }
  if (index === 15) { return "The Devil"; }
  if (index === 16) { return "The Tower"; }
  if (index === 17) { return "The Star"; }
  if (index === 18) { return "The Moon"; }
  if (index === 19) { return "The Sun"; }
  if (index === 20) { return "Judgement"; }
  if (index === 21) { return "The World"; }
  let minor: number = index - 22;
  let suit: number = math.floor(minor / 14);
  let rank: number = minor % 14;
  let suitName: string = "Wands";
  if (suit === 1) { suitName = "Cups"; }
  if (suit === 2) { suitName = "Swords"; }
  if (suit === 3) { suitName = "Pentacles"; }
  let rankName: string = "Ace";
  if (rank === 1) { rankName = "Two"; }
  if (rank === 2) { rankName = "Three"; }
  if (rank === 3) { rankName = "Four"; }
  if (rank === 4) { rankName = "Five"; }
  if (rank === 5) { rankName = "Six"; }
  if (rank === 6) { rankName = "Seven"; }
  if (rank === 7) { rankName = "Eight"; }
  if (rank === 8) { rankName = "Nine"; }
  if (rank === 9) { rankName = "Ten"; }
  if (rank === 10) { rankName = "Page"; }
  if (rank === 11) { rankName = "Knight"; }
  if (rank === 12) { rankName = "Queen"; }
  if (rank === 13) { rankName = "King"; }
  return rankName + " of " + suitName;
}

function c_shuffle(state: AppState, ignored: number): AppState {
  let seed: number = state.c_seed;
  let fan: number[] = [];
  let i: number = 0;
  while (i < 78) {
    fan.push(i);
    i = i + 1;
  }
  let j: number = 77;
  while (j > 0) {
    seed = math.randomStep(seed);
    let k: number = math.randomBelow(seed, j + 1);
    let tmp: number = fan[j];
    fan[j] = fan[k];
    fan[k] = tmp;
    j = j - 1;
  }
  return {c_phase: 1, c_fan: fan, c_seed: seed, c_hasPicked: false__PASSTHROUGH__};
}

function c_draw(state: AppState, value: number): AppState {
  if (state.c_phase !== 1) { return {__PASSTHROUGH__}; }
  let count: number = state.c_fan.length();
  if (count === 0) { return {__PASSTHROUGH__}; }
  let seed: number = math.randomStep(state.c_seed);
  let pick: number = math.randomBelow(seed, count);
  let index: number = state.c_fan[pick];
  let reversed: boolean = math.randomBelow(seed, 2) === 1;
  let minute: number = time.hourOfDay() * 60 + time.minuteOfHour();
  let day: number = time.daysSinceEpoch();
  let entry: C_Draw = {card: c_cardName(index), reversed: reversed, minute: minute, day: day};
  let out: C_Draw[] = [];
  for (let old: C_Draw of state.c_draws) {
    out.push(old);
  }
  out.push(entry);
  return {
    c_draws: out,
    c_phase: 0,
    c_seed: seed,
    c_picked: entry.card,
    c_pickedReversed: reversed,
    c_pickedMinute: minute,
    c_hasPicked: true
  __PASSTHROUGH__};
}

function c_clear(state: AppState, ignored: number): AppState {
  let empty: C_Draw[] = [];
  return {c_draws: empty, c_hasPicked: false__PASSTHROUGH__};
}
</functions>
