@jsonable
class AppState {
  c_cards: C_Card[];
  c_index: number;
  c_flipped: boolean;
  c_flipCount: number;
}

function init(): AppState {
  return {c_cards: [], c_index: 0, c_flipped: false, c_flipCount: 0};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}











function c_flip(state: AppState, ignored: number): AppState {
  return {c_flipped: !state.c_flipped, c_flipCount: state.c_flipCount + 1, c_cards: state.c_cards, c_index: state.c_index};
}

function c_next(state: AppState, ignored: number): AppState {
  let n: number = state.c_cards.length();
  if (n === 0) { return {c_cards: state.c_cards, c_index: state.c_index, c_flipped: state.c_flipped, c_flipCount: state.c_flipCount}; }
  let i: number = state.c_index + 1;
  if (i >= n) { i = 0; }
  return {c_index: i, c_flipped: false, c_flipCount: state.c_flipCount + 1, c_cards: state.c_cards};
}

function c_prev(state: AppState, ignored: number): AppState {
  let n: number = state.c_cards.length();
  if (n === 0) { return {c_cards: state.c_cards, c_index: state.c_index, c_flipped: state.c_flipped, c_flipCount: state.c_flipCount}; }
  let i: number = state.c_index - 1;
  if (i < 0) { i = n - 1; }
  return {c_index: i, c_flipped: false, c_flipCount: state.c_flipCount + 1, c_cards: state.c_cards};
}

