import * as ui from "std/ui"

@jsonable
class LogEntry {
  cardFront: string;
  cardBack: string;
  timesMissed: number;
  minute: number;
}

@jsonable
class AppState {
  deckSizeText: string;
  masteryTargetText: string;
  entries: LogEntry[];
  draft_cardFront: string;
  draft_cardBack: string;
  draft_timesMissed: string;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {deckSizeText: "20", masteryTargetText: "80", entries: emptyEntries, draft_cardFront: "", draft_cardBack: "", draft_timesMissed: "", removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_deckSize(state: AppState, value: string): AppState {
  return {deckSizeText: value, masteryTargetText: state.masteryTargetText, entries: state.entries, draft_cardFront: state.draft_cardFront, draft_cardBack: state.draft_cardBack, draft_timesMissed: state.draft_timesMissed, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_masteryTarget(state: AppState, value: string): AppState {
  return {masteryTargetText: value, deckSizeText: state.deckSizeText, entries: state.entries, draft_cardFront: state.draft_cardFront, draft_cardBack: state.draft_cardBack, draft_timesMissed: state.draft_timesMissed, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_cardFront(state: AppState, value: string): AppState {
  return {draft_cardFront: value, deckSizeText: state.deckSizeText, masteryTargetText: state.masteryTargetText, entries: state.entries, draft_cardBack: state.draft_cardBack, draft_timesMissed: state.draft_timesMissed, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_cardBack(state: AppState, value: string): AppState {
  return {draft_cardBack: value, deckSizeText: state.deckSizeText, masteryTargetText: state.masteryTargetText, entries: state.entries, draft_cardFront: state.draft_cardFront, draft_timesMissed: state.draft_timesMissed, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_timesMissed(state: AppState, value: string): AppState {
  return {draft_timesMissed: value, deckSizeText: state.deckSizeText, masteryTargetText: state.masteryTargetText, entries: state.entries, draft_cardFront: state.draft_cardFront, draft_cardBack: state.draft_cardBack, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_cardFront) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {cardFront: strings.trim(state.draft_cardFront), cardBack: strings.trim(state.draft_cardBack), timesMissed: strings.toNumber(state.draft_timesMissed, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_cardFront: "", draft_cardBack: "", draft_timesMissed: "", deckSizeText: state.deckSizeText, masteryTargetText: state.masteryTargetText, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, deckSizeText: state.deckSizeText, masteryTargetText: state.masteryTargetText, draft_cardFront: state.draft_cardFront, draft_cardBack: state.draft_cardBack, draft_timesMissed: state.draft_timesMissed, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, deckSizeText: state.deckSizeText, masteryTargetText: state.masteryTargetText, draft_cardFront: state.draft_cardFront, draft_cardBack: state.draft_cardBack, draft_timesMissed: state.draft_timesMissed, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, deckSizeText: state.deckSizeText, masteryTargetText: state.masteryTargetText, entries: state.entries, draft_cardFront: state.draft_cardFront, draft_cardBack: state.draft_cardBack, draft_timesMissed: state.draft_timesMissed, settingsOpen: state.settingsOpen};
}





function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, deckSizeText: state.deckSizeText, masteryTargetText: state.masteryTargetText, entries: state.entries, draft_cardFront: state.draft_cardFront, draft_cardBack: state.draft_cardBack, draft_timesMissed: state.draft_timesMissed, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Missed Cards", "FLASHCARDS", "Track the cards you miss and drill them again", ""));
  {
      let deckSize: number = strings.toNumber(state.deckSizeText, 0);
      let masteryTarget: number = strings.toNumber(state.masteryTargetText, 0);
      let entryCount: number = state.entries.length();
      let entryTotal: number = 0;
      for (let e: LogEntry of state.entries) { entryTotal = entryTotal + e.timesMissed; }
      let missedCount: number = entryCount;
      let missedShare: number = share(missedCount, deckSize) * 100;
      let masteryProgress: number = math.min(1, share((100 - (share(entryCount, deckSize) * 100)), masteryTarget));
    sections.push(ui.Section("content", "", "", [ui.Progress("accent", "Mastery progress", math.round(math.min(math.max(masteryProgress, 0), 1) * 1000), 1000)]));
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 2, [ui.NumberStat("default", "Missed cards", missedCount, "", " cards", 1, "", "chart", 0), ui.NumberStat("default", "Share missed", missedShare, "", "%", 1, "", "chart", 1)])]));
    let rows: ui.View[] = [];
    let i: number = entryCount - 1;
    while (i >= 0 && i > entryCount - 21) {
      let e: LogEntry = state.entries[i];
      let sub: string = e.cardBack + " · " + "Added " + ui.clockToString(e.minute);
      rows.push(ui.ListItem("default", e.cardFront, sub, ui.formatNumber(e.timesMissed, 0), "", 0, false, ""));
      rows.push(ui.ActionBar("end", [ui.Button("secondary", "Remove", "removeEntry", i, true)]));
      i = i - 1;
    }
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Front", state.draft_cardFront, "set_draft_cardFront"), ui.TextField("default", "Back", state.draft_cardBack, "set_draft_cardBack"), ui.TextField("default", "Times missed", state.draft_timesMissed, "set_draft_timesMissed", "number"), ui.ActionBar("end", [ui.Button("primary", "Add", "addEntry", 0, strings.trim(state.draft_cardFront) !== "")])]));
    sections.push(ui.Section("content", "", "", [ui.SectionHeader("default", "Missed cards", "Newest first", ui.numberToString(entryCount)), ui.When(entryCount === 0, ui.EmptyState("default", "Nothing added yet", "Fill in the fields above and tap Add.", "", "", "list")), ui.When(entryCount > 0, ui.ListGroup("default", "", rows)), ui.When(state.removedEntries.length() > 0, ui.Snackbar("default", "Removed", "Undo", "undoRemove")), ui.Ticker("default", "undoClock", 6000 + state.entries.length() % 7, state.removedEntries.length() > 0, "expireUndo")]));
  }
  {
    let settingsWord: string = "Show";
    if (state.settingsOpen) { settingsWord = "Hide"; }
    sections.push(ui.Section("supporting", "", "", [
      ui.ListItem("default", "Settings", "2 settings", settingsWord, "toggleSettings", 0, true, ""),
      ui.When(state.settingsOpen, ui.Column("default", [ui.TextField("default", "Cards in deck", state.deckSizeText, "set_deckSize", "number"), ui.TextField("default", "Mastery target (%)", state.masteryTargetText, "set_masteryTarget", "number")]))
    ]));
  }
  return ui.AppTheme("technical", "", sections);
