  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {sessionSize: 20, entries: emptyEntries, draft_term: "", draft_definition: "", draft_timesMissed: "", removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_sessionSize(state: AppState, value: number): AppState {
  return {sessionSize: value, entries: state.entries, draft_term: state.draft_term, draft_definition: state.draft_definition, draft_timesMissed: state.draft_timesMissed, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_term(state: AppState, value: string): AppState {
  return {draft_term: value, sessionSize: state.sessionSize, entries: state.entries, draft_definition: state.draft_definition, draft_timesMissed: state.draft_timesMissed, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_definition(state: AppState, value: string): AppState {
  return {draft_definition: value, sessionSize: state.sessionSize, entries: state.entries, draft_term: state.draft_term, draft_timesMissed: state.draft_timesMissed, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_timesMissed(state: AppState, value: string): AppState {
  return {draft_timesMissed: value, sessionSize: state.sessionSize, entries: state.entries, draft_term: state.draft_term, draft_definition: state.draft_definition, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_term) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {term: strings.trim(state.draft_term), definition: strings.trim(state.draft_definition), timesMissed: strings.toNumber(state.draft_timesMissed, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_term: "", draft_definition: "", draft_timesMissed: "", sessionSize: state.sessionSize, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
