<functions>
function c_deck(): C_Element[] {
  let d: C_Element[] = [];
  d.push({symbol: "H", name: "Hydrogen", number: 1, mass: 1.008, fact: "Lightest element; most of the universe is hydrogen."});
  d.push({symbol: "He", name: "Helium", number: 2, mass: 4.003, fact: "Noble gas used in balloons and cooling."});
  d.push({symbol: "C", name: "Carbon", number: 6, mass: 12.011, fact: "Basis of all organic life."});
  d.push({symbol: "N", name: "Nitrogen", number: 7, mass: 14.007, fact: "About 78% of the air you breathe."});
  d.push({symbol: "O", name: "Oxygen", number: 8, mass: 15.999, fact: "Essential for breathing and combustion."});
  d.push({symbol: "Na", name: "Sodium", number: 11, mass: 22.99, fact: "Half of table salt; reacts with water."});
  d.push({symbol: "Fe", name: "Iron", number: 26, mass: 55.845, fact: "Core of steel and of Earth's core."});
  d.push({symbol: "Cu", name: "Copper", number: 29, mass: 63.546, fact: "Excellent conductor used in wiring."});
  d.push({symbol: "Ag", name: "Silver", number: 47, mass: 107.868, fact: "Best electrical conductor of all metals."});
  d.push({symbol: "Au", name: "Gold", number: 79, mass: 196.967, fact: "Precious metal that never tarnishes."});
  return d;
}

function c_flip(state: AppState, ignored: number): AppState {
  return {c_flipped: !state.c_flipped, c_flipTrigger: state.c_flipTrigger + 1__PASSTHROUGH__};
}

function c_next(state: AppState, ignored: number): AppState {
  let n: number = c_deck().length();
  let i: number = state.c_index + 1;
  if (i >= n) { i = 0; }
  return {c_index: i, c_flipped: false, c_flipTrigger: state.c_flipTrigger + 1__PASSTHROUGH__};
}

function c_prev(state: AppState, ignored: number): AppState {
  let n: number = c_deck().length();
  let i: number = state.c_index - 1;
  if (i < 0) { i = n - 1; }
  return {c_index: i, c_flipped: false, c_flipTrigger: state.c_flipTrigger + 1__PASSTHROUGH__};
}
</functions>
