import * as ui from "std/ui"

@jsonable
class LogEntry {
  category: string;
  weight: number;
  score: number;
  minute: number;
}

@jsonable
class AppState {
  targetGradeText: string;
  entries: LogEntry[];
  draft_category: string;
  draft_weight: string;
  draft_score: string;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {targetGradeText: "90", entries: emptyEntries, draft_category: "", draft_weight: "", draft_score: "", removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_targetGrade(state: AppState, value: string): AppState {
  return {targetGradeText: value, entries: state.entries, draft_category: state.draft_category, draft_weight: state.draft_weight, draft_score: state.draft_score, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_category(state: AppState, value: string): AppState {
  return {draft_category: value, targetGradeText: state.targetGradeText, entries: state.entries, draft_weight: state.draft_weight, draft_score: state.draft_score, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_weight(state: AppState, value: string): AppState {
  return {draft_weight: value, targetGradeText: state.targetGradeText, entries: state.entries, draft_category: state.draft_category, draft_score: state.draft_score, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_score(state: AppState, value: string): AppState {
  return {draft_score: value, targetGradeText: state.targetGradeText, entries: state.entries, draft_category: state.draft_category, draft_weight: state.draft_weight, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_category) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {category: strings.trim(state.draft_category), weight: strings.toNumber(state.draft_weight, 0), score: strings.toNumber(state.draft_score, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_category: "", draft_weight: "", draft_score: "", targetGradeText: state.targetGradeText, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, targetGradeText: state.targetGradeText, draft_category: state.draft_category, draft_weight: state.draft_weight, draft_score: state.draft_score, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, targetGradeText: state.targetGradeText, draft_category: state.draft_category, draft_weight: state.draft_weight, draft_score: state.draft_score, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, targetGradeText: state.targetGradeText, entries: state.entries, draft_category: state.draft_category, draft_weight: state.draft_weight, draft_score: state.draft_score, settingsOpen: state.settingsOpen};
}





function c_weightedGrade(state: AppState): number {
  let totalWeight: number = 0;
  let entryTotal: number = 0;
  for (let e: LogEntry of state.entries) {
    totalWeight = totalWeight + e.weight;
    entryTotal = entryTotal + e.score * e.weight;
  }
  if (totalWeight === 0) { return 0; }
  return entryTotal / totalWeight;
}

function c_pointsToTarget(state: AppState): number {
  let target: number = strings.toNumber(state.targetGradeText, 0);
  return target - c_weightedGrade(state);
}

function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, targetGradeText: state.targetGradeText, entries: state.entries, draft_category: state.draft_category, draft_weight: state.draft_weight, draft_score: state.draft_score, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

