  while (i < state.records7.length() - 1) {
    out.push(state.records7[i]);
    i = i + 1;
  }
  return {labels7: state.labels7, records7: out, draftWho7: state.draftWho7, draftAmount7: state.draftAmount7, draftNote7: state.draftNote7, currency7: state.currency7, targetGradeText: state.targetGradeText, settingsOpen: state.settingsOpen};
}

function clearRecords7(state: AppState, ignored: number): AppState {
  let out: Tally[] = [];
  return {labels7: state.labels7, records7: out, draftWho7: 0, draftAmount7: "", draftNote7: "", currency7: state.currency7, targetGradeText: state.targetGradeText, settingsOpen: state.settingsOpen};
}

function totals7(state: AppState): number[] {
  let out: number[] = [];
  let i: number = 0;
  while (i < state.labels7.length()) {
    out.push(0);
    i = i + 1;
  }
  for (let r: Tally of state.records7) {
    if (r.who >= 0 && r.who < out.length()) { out[r.who] = math.round((out[r.who] + r.amount) * 100) / 100; }
  }
  return out;
}

function totalSum7(state: AppState): number {
  let sum: number = 0;
  for (let r: Tally of state.records7) { sum = sum + r.amount; }
  return math.round(sum * 100) / 100;
}

function average7(state: AppState): number {
  let n: number = state.labels7.length();
  if (n === 0) { return 0; }
  return math.round(totalSum7(state) / n * 100) / 100;
}

function balances7(state: AppState): number[] {
  let totals: number[] = totals7(state);
  let n: number = state.labels7.length();
  let totalCents: number = math.round(totalSum7(state) * 100);
  let shareCents: number = 0;
  let extra: number = 0;
  if (n > 0) {
    shareCents = math.floor(totalCents / n);
    extra = totalCents - shareCents * n;
  }
  let out: number[] = [];
  let i: number = 0;
  while (i < totals.length()) {
    let owed: number = shareCents;
    if (i < extra) { owed = owed + 1; }
    out.push((math.round(totals[i] * 100) - owed) / 100);
    i = i + 1;
  }
  return out;
}

function c_totalWeight(state: AppState): number {
  let sum: number = 0;
  for (let r: Tally of state.records7) { sum = sum + r.amount; }
  return math.round(sum * 100) / 100;
}

function c_weightedScore(state: AppState): number {
  let sum: number = 0;
  for (let r: Tally of state.records7) { sum = sum + r.amount * r.amount; }
  return math.round(sum * 100) / 100;
}

function c_currentGrade(state: AppState): number {
  let w: number = c_totalWeight(state);
  if (w === 0) { return 0; }
  return math.round(c_weightedScore(state) / w * 100) / 100;
}

function c_pointsToTarget(state: AppState): number {
  let target: number = strings.toNumber(state.targetGradeText, 0);
  return math.round((target - c_currentGrade(state)) * 100) / 100;
}

