  testWeightText: string;
  entries: LogEntry[];
  draft_score: string;
  draft_kind: string;
  removedEntries: LogEntry[];
  removedAt: number;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {quizWeightText: "40", testWeightText: "60", entries: emptyEntries, draft_score: "", draft_kind: "", removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_quizWeight(state: AppState, value: string): AppState {
