}



function set_draft_score(state: AppState, value: string): AppState {
  return {draft_score: value, quizWeightText: state.quizWeightText, testWeightText: state.testWeightText, entries: state.entries, draft_kind: state.draft_kind, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_kind(state: AppState, value: string): AppState {
  return {draft_kind: value, quizWeightText: state.quizWeightText, testWeightText: state.testWeightText, entries: state.entries, draft_score: state.draft_score, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_kind) === "") { return state; }
  let none: LogEntry[] = [];
