}



function set_draft_score(state: AppState, value: string): AppState {
  return {draft_score: value, quizWeightText: state.quizWeightText, testWeightText: state.testWeightText, entries: state.entries, draft_kind: state.draft_kind, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_kind(state: AppState, value: string): AppState {
  return {draft_kind: value, quizWeightText: state.quizWeightText, testWeightText: state.testWeightText, entries: state.entries, draft_score: state.draft_score, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_kind) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {score: strings.toNumber(state.draft_score, 0), kind: strings.trim(state.draft_kind), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_score: "", draft_kind: "", quizWeightText: state.quizWeightText, testWeightText: state.testWeightText, removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, quizWeightText: state.quizWeightText, testWeightText: state.testWeightText, draft_score: state.draft_score, draft_kind: state.draft_kind};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, quizWeightText: state.quizWeightText, testWeightText: state.testWeightText, draft_score: state.draft_score, draft_kind: state.draft_kind};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, quizWeightText: state.quizWeightText, testWeightText: state.testWeightText, entries: state.entries, draft_score: state.draft_score, draft_kind: state.draft_kind};
}





