import * as ui from "std/ui"

@jsonable
class AppState {
  scores: string;
  dropCount: number;
  settingsOpen: boolean;
}

function init(): AppState {
  return {scores: "", dropCount: 1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_scores(state: AppState, value: string): AppState {
  return {scores: value, dropCount: state.dropCount, settingsOpen: state.settingsOpen};
}

function set_dropCount(state: AppState, value: number): AppState {
  return {dropCount: value, scores: state.scores, settingsOpen: state.settingsOpen};
}







function c_parseScores(text: string): number[] {
  let out: number[] = [];
  let parts: string[] = strings.split(text, ",");
  for (let p: string of parts) {
    let t: string = strings.trim(p);
    if (strings.length(t) > 0) {
      let n: number = strings.toNumber(t, -1);
      if (n >= 0) {
        out.push(n);
      }
    }
  }
  return out;
}

function c_keptCount(state: AppState): number {
  let all: number[] = c_parseScores(state.scores);
  let kept: number = all.length() - state.dropCount;
  if (kept < 0) { kept = 0; }
  return kept;
}

function c_droppedTotal(state: AppState): number {
  let all: number[] = c_parseScores(state.scores);
  let n: number = all.length();
  let drop: number = state.dropCount;
  if (drop > n) { drop = n; }
  let total: number = 0;
  let taken: number = 0;
  while (taken < drop) {
    let bestIndex: number = -1;
    let bestValue: number = 0;
    let i: number = 0;
    while (i < n) {
      let v: number = all[i];
      if (v >= 0 && (bestIndex < 0 || v < bestValue)) {
        bestValue = v;
        bestIndex = i;
      }
      i = i + 1;
    }
    if (bestIndex < 0) {
      taken = drop;
    } else {
      total = total + bestValue;
      all[bestIndex] = -1;
      taken = taken + 1;
    }
  }
  return total;
}

function c_keptTotal(state: AppState): number {
  let all: number[] = c_parseScores(state.scores);
  let sum: number = 0;
  for (let v: number of all) {
    sum = sum + v;
  }
  return sum - c_droppedTotal(state);
}

function c_finalGrade(state: AppState): number {
  let kept: number = c_keptCount(state);
  if (kept <= 0) { return 0; }
  return c_keptTotal(state) / kept;
}

function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, scores: state.scores, dropCount: state.dropCount};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
