import * as ui from "std/ui"

@jsonable
class LogEntry {
  movieTitle: string;
  correct: boolean;
  minute: number;
}

@jsonable
class AppState {
  roundsPerGame: number;
  entries: LogEntry[];
  draft_movieTitle: string;
  draft_correct: boolean;
  removedEntries: LogEntry[];
  removedAt: number;
  c_puzzleIndex: number;
  c_guess: string;
  c_feedback: string;
  c_checked: boolean;
  c_lastCorrect: boolean;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {roundsPerGame: 10, entries: emptyEntries, draft_movieTitle: "", draft_correct: false, removedEntries: emptyEntries, removedAt: -1, c_puzzleIndex: 0, c_guess: "", c_feedback: "", c_checked: false, c_lastCorrect: false, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_roundsPerGame(state: AppState, value: number): AppState {
  return {roundsPerGame: value, entries: state.entries, draft_movieTitle: state.draft_movieTitle, draft_correct: state.draft_correct, removedEntries: state.removedEntries, removedAt: state.removedAt, c_puzzleIndex: state.c_puzzleIndex, c_guess: state.c_guess, c_feedback: state.c_feedback, c_checked: state.c_checked, c_lastCorrect: state.c_lastCorrect, settingsOpen: state.settingsOpen};
}



function set_draft_movieTitle(state: AppState, value: string): AppState {
  return {draft_movieTitle: value, roundsPerGame: state.roundsPerGame, entries: state.entries, draft_correct: state.draft_correct, removedEntries: state.removedEntries, removedAt: state.removedAt, c_puzzleIndex: state.c_puzzleIndex, c_guess: state.c_guess, c_feedback: state.c_feedback, c_checked: state.c_checked, c_lastCorrect: state.c_lastCorrect, settingsOpen: state.settingsOpen};
}

function set_draft_correct(state: AppState, value: boolean): AppState {
  return {draft_correct: value, roundsPerGame: state.roundsPerGame, entries: state.entries, draft_movieTitle: state.draft_movieTitle, removedEntries: state.removedEntries, removedAt: state.removedAt, c_puzzleIndex: state.c_puzzleIndex, c_guess: state.c_guess, c_feedback: state.c_feedback, c_checked: state.c_checked, c_lastCorrect: state.c_lastCorrect, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_movieTitle) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {movieTitle: strings.trim(state.draft_movieTitle), correct: state.draft_correct, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_movieTitle: "", roundsPerGame: state.roundsPerGame, draft_correct: state.draft_correct, removedAt: state.removedAt, c_puzzleIndex: state.c_puzzleIndex, c_guess: state.c_guess, c_feedback: state.c_feedback, c_checked: state.c_checked, c_lastCorrect: state.c_lastCorrect, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, roundsPerGame: state.roundsPerGame, draft_movieTitle: state.draft_movieTitle, draft_correct: state.draft_correct, c_puzzleIndex: state.c_puzzleIndex, c_guess: state.c_guess, c_feedback: state.c_feedback, c_checked: state.c_checked, c_lastCorrect: state.c_lastCorrect, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, roundsPerGame: state.roundsPerGame, draft_movieTitle: state.draft_movieTitle, draft_correct: state.draft_correct, c_puzzleIndex: state.c_puzzleIndex, c_guess: state.c_guess, c_feedback: state.c_feedback, c_checked: state.c_checked, c_lastCorrect: state.c_lastCorrect, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, roundsPerGame: state.roundsPerGame, entries: state.entries, draft_movieTitle: state.draft_movieTitle, draft_correct: state.draft_correct, c_puzzleIndex: state.c_puzzleIndex, c_guess: state.c_guess, c_feedback: state.c_feedback, c_checked: state.c_checked, c_lastCorrect: state.c_lastCorrect, settingsOpen: state.settingsOpen};
}





function c_emojiFor(index: number): string {
  if (index === 0) { return "🦁👑"; }
  if (index === 1) { return "🚢🧊💔"; }
  if (index === 2) { return "🕷️🧑🕸️"; }
  if (index === 3) { return "🦖🏞️🧬"; }
  if (index === 4) { return "👻🚫👨"; }
  if (index === 5) { return "🐟🔍🤡"; }
  if (index === 6) { return "🌪️🏠👠"; }
  if (index === 7) { return "🦇🧛🌃"; }
  if (index === 8) { return "🚀🌌👨‍🚀"; }
  if (index === 9) { return "🐼🥋🐍"; }
  return "🎬❓";
}

function c_answerFor(index: number): string {
  if (index === 0) { return "The Lion King"; }
  if (index === 1) { return "Titanic"; }
  if (index === 2) { return "Spider-Man"; }
  if (index === 3) { return "Jurassic Park"; }
  if (index === 4) { return "Ghostbusters"; }
  if (index === 5) { return "Finding Nemo"; }
  if (index === 6) { return "The Wizard of Oz"; }
  if (index === 7) { return "Dracula"; }
  if (index === 8) { return "Interstellar"; }
  if (index === 9) { return "Kung Fu Panda"; }
  return "";
}

function c_puzzleCount(): number {
  return 10;
}

function c_normalize(s: string): string {
  let t: string = strings.toLowerCase(strings.trim(s));
  t = strings.replace(t, "the ", "");
  t = strings.replace(t, "-", " ");
  t = strings.replace(t, "  ", " ");
  return strings.trim(t);
}

function c_setGuess(state: AppState, value: string): AppState {
  return {c_guess: value, c_feedback: "", c_checked: false, roundsPerGame: state.roundsPerGame, entries: state.entries, draft_movieTitle: state.draft_movieTitle, draft_correct: state.draft_correct, removedEntries: state.removedEntries, removedAt: state.removedAt, c_puzzleIndex: state.c_puzzleIndex, c_lastCorrect: state.c_lastCorrect, settingsOpen: state.settingsOpen};
}

function c_check(state: AppState, ignored: number): AppState {
  let answer: string = c_answerFor(state.c_puzzleIndex);
  let ok: boolean = c_normalize(state.c_guess) === c_normalize(answer);
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push({movieTitle: answer, correct: ok, minute: time.hourOfDay() * 60 + time.minuteOfHour()});
  let msg: string = "Not quite — the answer was " + answer + ".";
  if (ok) { msg = "Correct! It was " + answer + "."; }
