function c_pickWord(state: AppState): string {
  let pools: string[] = [];
  if (state.wordLength <= 3) {
    pools.push("cat"); pools.push("dog"); pools.push("sun"); pools.push("map"); pools.push("pen"); pools.push("box"); pools.push("cup"); pools.push("key"); pools.push("hat"); pools.push("bus");
  } else if (state.wordLength === 4) {
    pools.push("tree"); pools.push("moon"); pools.push("fish"); pools.push("star"); pools.push("rain"); pools.push("book"); pools.push("lamp"); pools.push("wind"); pools.push("gold"); pools.push("ship");
  } else if (state.wordLength === 5) {
    pools.push("apple"); pools.push("river"); pools.push("cloud"); pools.push("stone"); pools.push("light"); pools.push("music"); pools.push("plant"); pools.push("beach"); pools.push("tiger"); pools.push("bread");
  } else if (state.wordLength === 6) {
    pools.push("garden"); pools.push("planet"); pools.push("silver"); pools.push("orange"); pools.push("castle"); pools.push("forest"); pools.push("winter"); pools.push("rocket"); pools.push("camera"); pools.push("puzzle");
  } else if (state.wordLength === 7) {
    pools.push("journey"); pools.push("diamond"); pools.push("mystery"); pools.push("picture"); pools.push("freedom"); pools.push("balance"); pools.push("harvest"); pools.push("lantern"); pools.push("compass"); pools.push("whisper");
  } else if (state.wordLength === 8) {
    pools.push("mountain"); pools.push("elephant"); pools.push("umbrella"); pools.push("sandwich"); pools.push("birthday"); pools.push("treasure"); pools.push("festival"); pools.push("hospital"); pools.push("notebook"); pools.push("triangle");
  } else if (state.wordLength === 9) {
    pools.push("adventure"); pools.push("chocolate"); pools.push("butterfly"); pools.push("landscape"); pools.push("wonderful"); pools.push("pineapple"); pools.push("harmonica"); pools.push("crocodile"); pools.push("blueprint"); pools.push("snowflake");
  } else if (state.wordLength === 10) {
    pools.push("basketball"); pools.push("strawberry"); pools.push("playground"); pools.push("watermelon"); pools.push("skateboard"); pools.push("friendship"); pools.push("helicopter"); pools.push("restaurant"); pools.push("typewriter"); pools.push("lighthouse");
  } else if (state.wordLength === 11) {
    pools.push("celebration"); pools.push("underground"); pools.push("temperature"); pools.push("grandmother"); pools.push("information"); pools.push("performance"); pools.push("environment"); pools.push("comfortable"); pools.push("instruction"); pools.push("photography");
  } else {
    pools.push("extraordinary"); pools.push("communication"); pools.push("understanding"); pools.push("international"); pools.push("concentration"); pools.push("architecture"); pools.push("neighbourhood"); pools.push("determination"); pools.push("investigation"); pools.push("entertainment");
  }
  let n: number = pools.length();
  let idx: number = math.randomBelow(state.c_seed, n);
  return pools[idx];
}

function c_newRound(state: AppState): AppState {
  let seed: number = math.randomStep(state.c_seed);
  let word: string = c_pickWord({wordLength: state.wordLength, c_word: state.c_word, c_guessed: state.c_guessed, c_wrong: state.c_wrong, c_status: state.c_status, c_round: state.c_round, c_seed: seed, c_hintUsed: state.c_hintUsed});
  return {c_word: word, c_guessed: "", c_wrong: 0, c_status: "playing", c_round: state.c_round + 1, c_seed: seed, wordLength: state.wordLength, c_hintUsed: false};
}

function c_start(state: AppState, ignored: number): AppState {
  return c_newRound(state);
}

function c_guess(state: AppState, value: number): AppState {
  if (state.c_status !== "playing") {
    return {wordLength: state.wordLength, c_word: state.c_word, c_guessed: state.c_guessed, c_wrong: state.c_wrong, c_status: state.c_status, c_round: state.c_round, c_seed: state.c_seed, c_hintUsed: state.c_hintUsed};
  }
  if (state.c_word === "") {
    return {wordLength: state.wordLength, c_word: state.c_word, c_guessed: state.c_guessed, c_wrong: state.c_wrong, c_status: state.c_status, c_round: state.c_round, c_seed: state.c_seed, c_hintUsed: state.c_hintUsed};
  }
  let letter: string = strings.substring("abcdefghijklmnopqrstuvwxyz", value, value + 1);
  if (strings.contains(state.c_guessed, letter)) {
    return {wordLength: state.wordLength, c_word: state.c_word, c_guessed: state.c_guessed, c_wrong: state.c_wrong, c_status: state.c_status, c_round: state.c_round, c_seed: state.c_seed, c_hintUsed: state.c_hintUsed};
  }
  let guessed: string = state.c_guessed + letter;
  let hit: boolean = strings.contains(state.c_word, letter);
  let wrong: number = state.c_wrong;
  if (!hit) {
    wrong = wrong + 1;
  }
  let filled: number = 0;
  let i: number = 0;
  while (i < state.c_word.length()) {
    let ch: string = strings.substring(state.c_word, i, i + 1);
    if (strings.contains(guessed, ch)) {
      filled = filled + 1;
    }
    i = i + 1;
  }
  let status: string = "playing";
  if (filled === state.c_word.length()) {
    status = "won";
  } else if (wrong >= 6) {
    status = "lost";
  }
  return {c_guessed: guessed, c_wrong: wrong, c_status: status, wordLength: state.wordLength, c_word: state.c_word, c_round: state.c_round, c_seed: state.c_seed, c_hintUsed: state.c_hintUsed};
}

function c_hint(state: AppState, ignored: number): AppState {
  if (state.c_status !== "playing" || state.c_word === "" || state.c_hintUsed) {
    return {wordLength: state.wordLength, c_word: state.c_word, c_guessed: state.c_guessed, c_wrong: state.c_wrong, c_status: state.c_status, c_round: state.c_round, c_seed: state.c_seed, c_hintUsed: state.c_hintUsed};
  }
  let candidates: string[] = [];
  let i: number = 0;
  while (i < state.c_word.length()) {
    let ch: string = strings.substring(state.c_word, i, i + 1);
    if (!strings.contains(state.c_guessed, ch) && !strings.contains(candidates, ch)) {
      candidates.push(ch);
    }
    i = i + 1;
  }
  if (candidates.length() === 0) {
    return {wordLength: state.wordLength, c_word: state.c_word, c_guessed: state.c_guessed, c_wrong: state.c_wrong, c_status: state.c_status, c_round: state.c_round, c_seed: state.c_seed, c_hintUsed: state.c_hintUsed};
  }
  let seed: number = math.randomStep(state.c_seed);
  let pick: number = math.randomBelow(seed, candidates.length());
  let letter: string = candidates[pick];
  let guessed: string = state.c_guessed + letter;
  let filled: number = 0;
  let j: number = 0;
  while (j < state.c_word.length()) {
    let ch: string = strings.substring(state.c_word, j, j + 1);
    if (strings.contains(guessed, ch)) {
      filled = filled + 1;
    }
    j = j + 1;
  }
  let status: string = "playing";
  if (filled === state.c_word.length()) {
    status = "won";
  }
  return {c_guessed: guessed, c_wrong: state.c_wrong, c_status: status, wordLength: state.wordLength, c_word: state.c_word, c_round: state.c_round, c_seed: seed, c_hintUsed: true};
}

