}







function c_roll(state: AppState, value: number): AppState {
  let predictionValues: number[] = [1, 2, 3, 4, 5, 6];
  let call: number = predictionValues[state.predictionIndex];
  let stake: number = strings.toNumber(state.stakeText, 0);
  if (stake <= 0) {
    return {c_message: "Enter a stake of at least 1 coin.", predictionIndex: state.predictionIndex, stakeText: state.stakeText, c_rolls: state.c_rolls, c_coins: state.c_coins, c_throws: state.c_throws, c_die1: state.c_die1, c_die2: state.c_die2, c_hasRolled: state.c_hasRolled};
