  let won: boolean = d1 === call;
  let delta: number = 0 - stake;
  if (won) { delta = stake; }
  let coinsAfter: number = state.c_coins + delta;
  let entry: C_Roll = {
    die1: d1,
    die2: d2,
    call: call,
    stake: stake,
    won: won,
    coinsAfter: coinsAfter
  };
  let out: C_Roll[] = [];
  for (let old: C_Roll of state.c_rolls) {
