  } else {
    msg = msg + "You called " + ui.numberToString(call) + " and lost " + ui.numberToString(stake) + " coins.";
  }
  return {
    c_rolls: out,
    c_coins: coinsAfter,
    c_throws: state.c_throws + 1,
    c_die1: d1,
    c_die2: d2,
    c_hasRolled: true,
    c_message: msg
  , predictionIndex: state.predictionIndex, stakeText: state.stakeText};
}

function c_reset(state: AppState, value: number): AppState {
