      let termYears: number = state.termYears;
      let monthsPerYear: number = 12;
      let monthlyPayment: number = share((loanAmount * share(share(annualRate, 100), monthsPerYear)), (1 - math.pow((1 + share(share(annualRate, 100), monthsPerYear)), ((0 - termYears) * monthsPerYear))));
      let totalInterest: number = (((monthlyPayment * termYears) * monthsPerYear) - loanAmount);
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Loan amount ($)", state.loanAmountText, "set_loanAmount", "number"), ui.TextField("default", "Interest rate (%)", state.annualRateText, "set_annualRate", "number"), ui.NumberField("default", "Term (years)", state.termYears, 1, 40, "set_termYears")]));
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 2, [ui.NumberStat("default", "Monthly payment", monthlyPayment, "$", "", 1, "", "chart", 2), ui.NumberStat("default", "Total interest", totalInterest, "$", "", 1, "", "chart", 2)])]));
  }
  {
      sections.push(ui.Section("content", "", "", [
        ui.Table("default", ["Year", "Interest", "Balance"], 3, [
          ui.TableRow("default", ["1", "$18,400", "$312,600"]),
          ui.TableRow("default", ["2", "$17,950", "$305,550"]),
          ui.TableRow("default", ["3", "$17,470", "$298,020"]),
          ui.TableRow("default", ["4", "$16,960", "$289,980"]),
          ui.TableRow("default", ["5", "$16,420", "$281,400"]),
          ui.TableRow("default", ["6", "$15,850", "$272,250"]),
          ui.TableRow("default", ["7", "$15,250", "$262,500"]),
          ui.TableRow("default", ["8", "$14,620", "$252,120"])
        ])
      ]));
    }
  {
  {
    let c_loan: number = strings.toNumber(state.loanAmountText, 0);
    let c_term: number = state.termYears;
    if (c_loan <= 0 || c_term <= 0) {
      sections.push(ui.Section("content", "", "", [
        ui.Text("body", "Enter a loan amount and term above to see your Year 1 interest and principal.")
      ]));
    } else {
      sections.push(ui.Section("summary", "", "", [
        ui.SectionHeader("default", "Year 1", "From your loan amount, rate and term", ""),
        ui.MetricGroup("default", 2, [
          ui.NumberStat("warning", "Year 1 interest", c_yearOneInterest(state), "$", "", 1, "paid in the first 12 months", "chart", 2),
          ui.NumberStat("success", "Year 1 principal", c_yearOnePrincipal(state), "$", "", 1, "of the loan repaid in year 1", "check", 2)
        ])
      ]));
