function c_paidOffYear1(balance: number, principalPaid: number): number {
  if (balance <= 0) { return 0; }
  let pct: number = principalPaid * 12 / balance * 100;
  if (pct > 100) { return 100; }
  if (pct < 0) { return 0; }
  return pct;
