    let c_monthlyRate: number = c_apr / 12;
    let c_months: number = c_monthsToPayoff(c_balance, c_monthlyRate, c_payment);
    let c_totalPaid: number = c_months * c_payment;
    let c_totalInterest: number = c_totalPaid - c_balance;
    if (c_totalInterest < 0) { c_totalInterest = 0; }
