  let y: number = (x - 1) / (x + 1);
  let y2: number = y * y;
  let term: number = y;
  let sum: number = 0;
  let n: number = 0;
  while (n < 40) {
    sum = sum + term / (2 * n + 1);
    term = term * y2;
    n = n + 1;
