function c_monthsToPayoff(balance: number, monthlyRate: number, payment: number): number {
  if (balance <= 0) { return 0; }
  if (payment <= 0) { return 0; }
  let monthlyInterest: number = monthlyRate / 100;
  let ratio: number = balance * monthlyInterest / payment;
  if (ratio >= 1) { return 0; }
  let inner: number = 1 - ratio;
  if (inner <= 0) { return 0; }
  let denom: number = c_ln(1 + monthlyInterest);
  if (denom === 0) { return 0; }
  let months: number = -c_ln(inner) / denom;
  return math.ceil(months);
}

function c_ln(x: number): number {
  if (x <= 0) { return 0; }
  let y: number = (x - 1) / (x + 1);
  let y2: number = y * y;
  let term: number = y;
  let sum: number = 0;
  let n: number = 0;
  while (n < 40) {
    sum = sum + term / (2 * n + 1);
    term = term * y2;
    n = n + 1;
  }
  return 2 * sum;
}
</functions>
