function c_balanceAfter(startingBalance: number, monthlyDeposit: number, monthlyRate: number, months: number): number {
  let factor: number = math.pow(1 + monthlyRate / 100, months);
  if (monthlyRate === 0) {
    return startingBalance * factor + monthlyDeposit * months;
  }
  return startingBalance * factor + monthlyDeposit * (factor - 1) / (monthlyRate / 100);
}

function c_growthPercent(finalBalance: number, totalDeposited: number): number {
  if (totalDeposited === 0) { return 0; }
  return finalBalance / totalDeposited * 100;
}
