}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_debtName) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {debtName: strings.trim(state.draft_debtName), balance: strings.toNumber(state.draft_balance, 0), minPayment: strings.toNumber(state.draft_minPayment, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_debtName: "", draft_balance: "", draft_minPayment: "", extraPaymentText: state.extraPaymentText, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, extraPaymentText: state.extraPaymentText, draft_debtName: state.draft_debtName, draft_balance: state.draft_balance, draft_minPayment: state.draft_minPayment, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, extraPaymentText: state.extraPaymentText, draft_debtName: state.draft_debtName, draft_balance: state.draft_balance, draft_minPayment: state.draft_minPayment, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, extraPaymentText: state.extraPaymentText, entries: state.entries, draft_debtName: state.draft_debtName, draft_balance: state.draft_balance, draft_minPayment: state.draft_minPayment, settingsOpen: state.settingsOpen};
}





function c_minPayments(state: AppState): number {
  let total: number = 0;
  for (let e: LogEntry of state.entries) { total = total + e.minPayment; }
  return total;
}

function c_extraPayment(state: AppState): number {
  let v: number = strings.toNumber(state.extraPaymentText, 0);
  if (v < 0) { return 0; }
  return v;
