  return {elapsedMs: 0, running: false, finished: false, tempoText: "120", beatsPerBar: 4, bars: 2};
}

function countdownSeconds(state: AppState): number {
  let tempo: number = strings.toNumber(state.tempoText, 0);
  let beatsPerBar: number = state.beatsPerBar;
  let bars: number = state.bars;
  let beatsPerMinute: number = 60;
  let beatLength: number = share(beatsPerMinute, tempo);
  let loopLength: number = ((beatLength * beatsPerBar) * bars);
  return loopLength;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, tempoText: state.tempoText, beatsPerBar: state.beatsPerBar, bars: state.bars}; }
  return {elapsedMs: total, running: false, finished: true, tempoText: state.tempoText, beatsPerBar: state.beatsPerBar, bars: state.bars};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, tempoText: state.tempoText, beatsPerBar: state.beatsPerBar, bars: state.bars};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, tempoText: state.tempoText, beatsPerBar: state.beatsPerBar, bars: state.bars};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, tempoText: state.tempoText, beatsPerBar: state.beatsPerBar, bars: state.bars};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



