import * as ui from "std/ui"

@jsonable
class AppState {
  elapsedMs: number;
  running: boolean;
  finished: boolean;
  moveCount: number;
  moveLength: number;
  repeats: number;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, moveCount: 4, moveLength: 4, repeats: 3};
}

function countdownSeconds(state: AppState): number {
  let moveCount: number = state.moveCount;
  let moveLength: number = state.moveLength;
  let repeats: number = state.repeats;
  let beatGap: number = 1;
  let sequenceLength: number = (moveCount * (moveLength + beatGap));
  return sequenceLength;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, moveCount: state.moveCount, moveLength: state.moveLength, repeats: state.repeats}; }
  return {elapsedMs: total, running: false, finished: true, moveCount: state.moveCount, moveLength: state.moveLength, repeats: state.repeats};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, moveCount: state.moveCount, moveLength: state.moveLength, repeats: state.repeats};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, moveCount: state.moveCount, moveLength: state.moveLength, repeats: state.repeats};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, moveCount: state.moveCount, moveLength: state.moveLength, repeats: state.repeats};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_moveCount(state: AppState, value: number): AppState {
  return {moveCount: value, elapsedMs: 0, running: false, finished: false, moveLength: state.moveLength, repeats: state.repeats};
}

function set_moveLength(state: AppState, value: number): AppState {
  return {moveLength: value, elapsedMs: 0, running: false, finished: false, moveCount: state.moveCount, repeats: state.repeats};
}

function set_repeats(state: AppState, value: number): AppState {
  return {repeats: value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, moveCount: state.moveCount, moveLength: state.moveLength};
}







function c_moveName(index: number): string {
  if (index === 0) { return "Step touch"; }
  if (index === 1) { return "Arm wave"; }
  if (index === 2) { return "Body roll"; }
  if (index === 3) { return "Spin"; }
  return "Free move";
}

function c_moveCue(index: number): string {
  if (index === 0) { return "Step to the side, tap the other foot in, and clap on the beat."; }
  if (index === 1) { return "Lift one arm at a time and ripple the wave from shoulder to fingertips."; }
  if (index === 2) { return "Roll your chest down and forward, then stack the spine back up."; }
  if (index === 3) { return "Turn a full circle on the spot, arms out, and land facing front."; }
  return "Make up your own move and keep the beat.";
}

function c_currentMove(state: AppState): number {
  let moveCount: number = state.moveCount;
  if (moveCount <= 0) { return 0; }
  let moveLength: number = state.moveLength;
  let beatGap: number = 1;
  let slot: number = moveLength + beatGap;
  if (slot <= 0) { return 0; }
  let elapsed: number = state.elapsedMs / 1000;
  let index: number = math.floor(elapsed / slot);
  if (index < 0) { index = 0; }
  if (index >= moveCount) { index = moveCount - 1; }
  return index;
}

function c_currentRepeat(state: AppState): number {
  let moveCount: number = state.moveCount;
  let moveLength: number = state.moveLength;
  let beatGap: number = 1;
  let sequenceLength: number = moveCount * (moveLength + beatGap);
  if (sequenceLength <= 0) { return 1; }
  let elapsed: number = state.elapsedMs / 1000;
  let rep: number = math.floor(elapsed / sequenceLength) + 1;
  if (rep < 1) { rep = 1; }
  if (rep > state.repeats) { rep = state.repeats; }
  return rep;
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Dance Move Repeater", "DANCE LOOP", "Follow the moves in order, then repeat the whole sequence.", "clock"));
  {
    sections.push(ui.Ticker("default", "clock", 200, state.running, "onTick"));
      let moveCount: number = state.moveCount;
      let moveLength: number = state.moveLength;
      let repeats: number = state.repeats;
      let beatGap: number = 1;
      let duration: number = countdownSeconds(state);
      let elapsed: number = math.min(state.elapsedMs / 1000, duration);
      let remaining: number = duration - elapsed;
      let sequenceLength: number = (moveCount * (moveLength + beatGap));
      let totalTime: number = (sequenceLength * repeats);
    sections.push(ui.Section("hero", "", "", [ui.Hero("accent", "Dance sequence", ui.durationToString(math.ceil(remaining)), "", [ui.ActionBar("spread", [ui.Button("primary", "Start", "onStart", 0, !state.running), ui.Button("secondary", "Stop", "onStop", 0, state.running), ui.Button("secondary", "Reset", "onReset", 0, true)])])]));
    sections.push(ui.Section("content", "", "", [ui.NumberField("default", "Moves in sequence", state.moveCount, 1, 12, "set_moveCount"), ui.NumberField("default", "Time per move (seconds)", state.moveLength, 1, 30, "set_moveLength"), ui.NumberField("default", "Repeats", state.repeats, 1, 20, "set_repeats")]));
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 1, [ui.Stat("default", "Total dance time", ui.durationToString(math.ceil(totalTime)), "", "clock")])]));
  }
  {
  {
    let c_moveCount: number = state.moveCount;
