    if (c_intoMove > c_moveLength) { c_intoMove = c_moveLength; }
    let c_left: number = c_moveLength - c_intoMove;
    if (c_left < 0) { c_left = 0; }

    let c_rows: ui.View[] = [];
    let c_i: number = 0;
    while (c_i < c_moveCount) {
      let c_name: string = c_moveName(c_i);
      let c_cue: string = c_moveCue(c_i);
      let c_trailing: string = "";
      if (state.running && c_i === c_current) {
        c_trailing = ui.durationToString(math.ceil(c_left));
      }
      if (c_i === c_current) {
        c_rows.push(ui.ListItem("accent", ui.numberToString(c_i + 1) + ". " + c_name, c_cue, c_trailing, "", 0, true, "star"));
      } else {
