      c_s = c_s + 1;
    }

    let c_body: ui.View[] = [];
    c_body.push(ui.SectionHeader("default", "Starter sequence", "Step touch, arm wave, body roll, spin", "4 moves"));
    c_body.push(ui.ListGroup("default", "", c_starter));
    if (c_moveCount === 0) {
      c_body.push(ui.Text("muted", "Set at least one move above and your own sequence will appear here."));
    } else {
      c_body.push(ui.SectionHeader("default", "Your sequence", "Repeat " + ui.numberToString(c_rep) + " of " + ui.numberToString(state.repeats), ui.numberToString(c_moveCount) + " moves"));
      c_body.push(ui.ListGroup("default", "", c_rows));
    }
    sections.push(ui.Section("content", "", "", c_body));
  }
  }
  return ui.AppTheme("playful", "", sections);
