    deck.push(p);
    p = p + 1;
  }
  let s: number = seed;
  let i: number = deck.length() - 1;
  while (i > 0) {
    s = math.randomStep(s);
    let j: number = math.randomBelow(s, i + 1);
    let tmp: number = deck[i];
    deck[i] = deck[j];
    deck[j] = tmp;
    i = i - 1;
  }
  return deck;
}

