class AppState {
  intervalMonths: number;
  items7: DueItem[];
  today7: number;
  soon7: number;
  draftName7: string;
  draftDue7: number;
  draftLife7: string;
  settingsOpen: boolean;
}

function init(): AppState {
  let today7: number = time.daysSinceEpoch();
  let seeds7: DueSeed[] = [

  ];
  let items7: DueItem[] = [];
  for (let s: DueSeed of seeds7) {
    let life7: number = s.lifeDays;
    if (life7 < 0) { life7 = 0; }
    items7.push({name: s.name, dueDay: today7 + s.inDays, lifeDays: life7});
  }
  let soon7: number = 14;
  if (soon7 < 0 || soon7 > 60) { soon7 = 3; }
  return {intervalMonths: 6, items7: items7, today7: today7, soon7: soon7, draftName7: "", draftDue7: today7, draftLife7: "", settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_intervalMonths(state: AppState, value: number): AppState {
  return {intervalMonths: value, items7: state.items7, today7: state.today7, soon7: state.soon7, draftName7: state.draftName7, draftDue7: state.draftDue7, draftLife7: state.draftLife7, settingsOpen: state.settingsOpen};
}







function withItems7(state: AppState, items: DueItem[]): AppState {
  return {items7: items, today7: time.daysSinceEpoch(), soon7: state.soon7, draftName7: state.draftName7, draftDue7: state.draftDue7, draftLife7: state.draftLife7, intervalMonths: state.intervalMonths, settingsOpen: state.settingsOpen};
}

function setName7(state: AppState, value: string): AppState {
  return {items7: state.items7, today7: state.today7, soon7: state.soon7, draftName7: value, draftDue7: state.draftDue7, draftLife7: state.draftLife7, intervalMonths: state.intervalMonths, settingsOpen: state.settingsOpen};
}

function setDue7(state: AppState, value: number): AppState {
  return {items7: state.items7, today7: state.today7, soon7: state.soon7, draftName7: state.draftName7, draftDue7: value, draftLife7: state.draftLife7, intervalMonths: state.intervalMonths, settingsOpen: state.settingsOpen};
}

function setLife7(state: AppState, value: string): AppState {
  return {items7: state.items7, today7: state.today7, soon7: state.soon7, draftName7: state.draftName7, draftDue7: state.draftDue7, draftLife7: value, intervalMonths: state.intervalMonths, settingsOpen: state.settingsOpen};
}

function setSoon7(state: AppState, value: number): AppState {
  return {items7: state.items7, today7: state.today7, soon7: value, draftName7: state.draftName7, draftDue7: state.draftDue7, draftLife7: state.draftLife7, intervalMonths: state.intervalMonths, settingsOpen: state.settingsOpen};
}

function addItem7(state: AppState, ignored: number): AppState {
  let name: string = strings.trim(state.draftName7);
  if (name === "") { return state; }
  let life: number = math.round(strings.toNumber(state.draftLife7, 0));
  if (life < 0) { life = 0; }
  let out: DueItem[] = [];
  for (let it: DueItem of state.items7) { out.push(it); }
  out.push({name: name, dueDay: state.draftDue7, lifeDays: life});
  let today: number = time.daysSinceEpoch();
  return {items7: out, today7: today, soon7: state.soon7, draftName7: "", draftDue7: today, draftLife7: "", intervalMonths: state.intervalMonths, settingsOpen: state.settingsOpen};
}

function renew7(state: AppState, index: number): AppState {
  let today: number = time.daysSinceEpoch();
  let out: DueItem[] = [];
  let i: number = 0;
  while (i < state.items7.length()) {
    let it: DueItem = state.items7[i];
    if (i === index && it.lifeDays > 0) { out.push({name: it.name, dueDay: today + it.lifeDays, lifeDays: it.lifeDays}); }
    else { out.push(it); }
    i = i + 1;
  }
  return withItems7(state, out);
}

function removeItem7(state: AppState, index: number): AppState {
  let out: DueItem[] = [];
  let i: number = 0;
  while (i < state.items7.length()) {
    if (i !== index) { out.push(state.items7[i]); }
    i = i + 1;
  }
  return withItems7(state, out);
}

function refreshToday7(state: AppState, elapsedMs: number): AppState {
  let today: number = time.daysSinceEpoch();
  if (today === state.today7) { return state; }
  return {items7: state.items7, today7: today, soon7: state.soon7, draftName7: state.draftName7, draftDue7: state.draftDue7, draftLife7: state.draftLife7, intervalMonths: state.intervalMonths, settingsOpen: state.settingsOpen};
}

function sorted7(state: AppState): number[] {
  let order: number[] = [];
  let i: number = 0;
  while (i < state.items7.length()) {
    let at: number = order.length();
    let j: number = 0;
    while (j < order.length()) {
      if (state.items7[i].dueDay < state.items7[order[j]].dueDay) { at = j; break; }
      j = j + 1;
    }
    let next: number[] = [];
    let k: number = 0;
    while (k < order.length()) {
      if (k === at) { next.push(i); }
      next.push(order[k]);
      k = k + 1;
    }
    if (at === order.length()) { next.push(i); }
    order = next;
    i = i + 1;
  }
  return order;
}

function expiredCount7(state: AppState): number {
  let n: number = 0;
  for (let it: DueItem of state.items7) { if (it.dueDay < state.today7) { n = n + 1; } }
  return n;
}

function soonCount7(state: AppState): number {
  let n: number = 0;
  for (let it: DueItem of state.items7) {
    let left: number = it.dueDay - state.today7;
    if (left >= 0 && left <= state.soon7) { n = n + 1; }
  }
  return n;
}

function soonNames7(state: AppState): string {
  let out: string = "";
  for (let i: number of sorted7(state)) {
    let it: DueItem = state.items7[i];
    let left: number = it.dueDay - state.today7;
    if (left >= 0 && left <= state.soon7) {
      if (out.length() > 0) { out = out + ", "; }
      out = out + it.name;
    }
  }
  return out;
}

function daysWord7(n: number): string {
  if (n === 1) { return "1 day"; }
  return ui.numberToString(n) + " days";
}

function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, intervalMonths: state.intervalMonths, items7: state.items7, today7: state.today7, soon7: state.soon7, draftName7: state.draftName7, draftDue7: state.draftDue7, draftLife7: state.draftLife7};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Oil Change Tracker", "OIL CHANGES", "Know when each car is due for its next oil change", ""));
  {
