import * as ui from "std/ui"

@jsonable
class LogEntry {
  person: string;
  cutDate: number;
  minute: number;
}

@jsonable
class AppState {
  intervalWeeks: number;
  entries: LogEntry[];
  draft_person: string;
  draft_cutDate: number;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {intervalWeeks: 6, entries: emptyEntries, draft_person: "", draft_cutDate: time.daysSinceEpoch(), removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_intervalWeeks(state: AppState, value: number): AppState {
  return {intervalWeeks: value, entries: state.entries, draft_person: state.draft_person, draft_cutDate: state.draft_cutDate, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_person(state: AppState, value: string): AppState {
  return {draft_person: value, intervalWeeks: state.intervalWeeks, entries: state.entries, draft_cutDate: state.draft_cutDate, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_cutDate(state: AppState, value: number): AppState {
  return {draft_cutDate: value, intervalWeeks: state.intervalWeeks, entries: state.entries, draft_person: state.draft_person, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_person) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {person: strings.trim(state.draft_person), cutDate: state.draft_cutDate, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_person: "", intervalWeeks: state.intervalWeeks, draft_cutDate: state.draft_cutDate, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, intervalWeeks: state.intervalWeeks, draft_person: state.draft_person, draft_cutDate: state.draft_cutDate, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, intervalWeeks: state.intervalWeeks, draft_person: state.draft_person, draft_cutDate: state.draft_cutDate, settingsOpen: state.settingsOpen};
}

