import * as ui from "std/ui"

@jsonable
class AppState {
  cycleLengthIndex: number;
  lastBillDay: number;
  billAmountText: string;
  settingsOpen: boolean;
}

function init(): AppState {
  return {cycleLengthIndex: 1, lastBillDay: 1, billAmountText: "50", settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_cycleLength(state: AppState, value: number): AppState {
  return {cycleLengthIndex: value, lastBillDay: state.lastBillDay, billAmountText: state.billAmountText, settingsOpen: state.settingsOpen};
}

function set_lastBillDay(state: AppState, value: number): AppState {
  return {lastBillDay: value, cycleLengthIndex: state.cycleLengthIndex, billAmountText: state.billAmountText, settingsOpen: state.settingsOpen};
}

function set_billAmount(state: AppState, value: string): AppState {
  return {billAmountText: value, cycleLengthIndex: state.cycleLengthIndex, lastBillDay: state.lastBillDay, settingsOpen: state.settingsOpen};
}







function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, cycleLengthIndex: state.cycleLengthIndex, lastBillDay: state.lastBillDay, billAmountText: state.billAmountText};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Next Bill Due", "BILL CYCLE", "See when your next bill is due and how long you have.", ""));
  {
      let cycleLengthValues: number[] = [7, 30, 365];
      let cycleLength: number = cycleLengthValues[state.cycleLengthIndex];
      let lastBillDay: number = state.lastBillDay;
      let billAmount: number = strings.toNumber(state.billAmountText, 0);
      let daysPerMonth: number = 30;
      let amountDue: number = billAmount;
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 1, [ui.NumberStat("default", "Amount due", amountDue, "$", "", 1, "", "chart", 2)])]));
  }
  {
    let settingsWord: string = "Show";
    if (state.settingsOpen) { settingsWord = "Hide"; }
    sections.push(ui.Section("supporting", "", "", [
      ui.ListItem("default", "Settings", "3 settings", settingsWord, "toggleSettings", 0, true, ""),
      ui.When(state.settingsOpen, ui.Column("default", [ui.Select("default", "Cycle length", ["Weekly", "Monthly", "Yearly"], state.cycleLengthIndex, "set_cycleLength"), ui.NumberField("default", "Last bill day (day of month)", state.lastBillDay, 1, 31, "set_lastBillDay"), ui.TextField("default", "Bill amount ($)", state.billAmountText, "set_billAmount", "number")]))
    ]));
  }
  return ui.AppTheme("technical", "", sections);
}

