  c_alarmPending: boolean;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {intervalDays: 7, alarmTime: 540, entries: emptyEntries, draft_plantName: "", draft_lastWatered: time.daysSinceEpoch(), removedEntries: emptyEntries, removedAt: -1, c_alarmStatus: "", c_alarmPending: false, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_intervalDays(state: AppState, value: number): AppState {
  return {intervalDays: value, alarmTime: state.alarmTime, entries: state.entries, draft_plantName: state.draft_plantName, draft_lastWatered: state.draft_lastWatered, removedEntries: state.removedEntries, removedAt: state.removedAt, c_alarmStatus: state.c_alarmStatus, c_alarmPending: state.c_alarmPending, settingsOpen: state.settingsOpen};
}

