}



function set_draft_plantName(state: AppState, value: string): AppState {
  return {draft_plantName: value, intervalDays: state.intervalDays, alarmTime: state.alarmTime, entries: state.entries, draft_lastWatered: state.draft_lastWatered, removedEntries: state.removedEntries, removedAt: state.removedAt, c_alarmStatus: state.c_alarmStatus, c_alarmPending: state.c_alarmPending, settingsOpen: state.settingsOpen};
}

function set_draft_lastWatered(state: AppState, value: number): AppState {
  return {draft_lastWatered: value, intervalDays: state.intervalDays, alarmTime: state.alarmTime, entries: state.entries, draft_plantName: state.draft_plantName, removedEntries: state.removedEntries, removedAt: state.removedAt, c_alarmStatus: state.c_alarmStatus, c_alarmPending: state.c_alarmPending, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_plantName) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {plantName: strings.trim(state.draft_plantName), lastWatered: state.draft_lastWatered, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_plantName: "", intervalDays: state.intervalDays, alarmTime: state.alarmTime, draft_lastWatered: state.draft_lastWatered, removedAt: state.removedAt, c_alarmStatus: state.c_alarmStatus, c_alarmPending: state.c_alarmPending, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, intervalDays: state.intervalDays, alarmTime: state.alarmTime, draft_plantName: state.draft_plantName, draft_lastWatered: state.draft_lastWatered, c_alarmStatus: state.c_alarmStatus, c_alarmPending: state.c_alarmPending, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, intervalDays: state.intervalDays, alarmTime: state.alarmTime, draft_plantName: state.draft_plantName, draft_lastWatered: state.draft_lastWatered, c_alarmStatus: state.c_alarmStatus, c_alarmPending: state.c_alarmPending, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, intervalDays: state.intervalDays, alarmTime: state.alarmTime, entries: state.entries, draft_plantName: state.draft_plantName, draft_lastWatered: state.draft_lastWatered, c_alarmStatus: state.c_alarmStatus, c_alarmPending: state.c_alarmPending, settingsOpen: state.settingsOpen};
}





function c_nextDue(state: AppState): number {
  let best: number = -1;
  for (let e: LogEntry of state.entries) {
    let due: number = e.lastWatered + state.intervalDays;
    if (best < 0 || due < best) { best = due; }
  }
  return best;
}

function c_dueCount(state: AppState): number {
  let today: number = time.daysSinceEpoch();
  let n: number = 0;
  for (let e: LogEntry of state.entries) {
    if (e.lastWatered + state.intervalDays <= today) { n = n + 1; }
  }
  return n;
}

function c_armAlarm(state: AppState, ignored: number): AppState {
  sdk.call("NotificationKit.notificationManager.requestEnableNotification", [], "c_onAlarmAnswer");
  return {c_alarmStatus: "Asking your phone to allow reminders...", c_alarmPending: true, intervalDays: state.intervalDays, alarmTime: state.alarmTime, entries: state.entries, draft_plantName: state.draft_plantName, draft_lastWatered: state.draft_lastWatered, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function c_onAlarmAnswer(state: AppState, value: string): AppState {
  let failed: boolean = strings.startsWith(value, "declined") || strings.startsWith(value, "error");
  if (failed) {
    return {c_alarmStatus: "Reminders are off: " + value, c_alarmPending: false, intervalDays: state.intervalDays, alarmTime: state.alarmTime, entries: state.entries, draft_plantName: state.draft_plantName, draft_lastWatered: state.draft_lastWatered, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
  }
  sdk.call("SensorServiceKit.vibrator.vibrate", ["duration", "800"], "c_onVibrateAnswer");
  return {c_alarmStatus: "Reminders allowed. Testing the alert...", c_alarmPending: true, intervalDays: state.intervalDays, alarmTime: state.alarmTime, entries: state.entries, draft_plantName: state.draft_plantName, draft_lastWatered: state.draft_lastWatered, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function c_onVibrateAnswer(state: AppState, value: string): AppState {
  let failed: boolean = strings.startsWith(value, "declined") || strings.startsWith(value, "error");
  if (failed) {
    return {c_alarmStatus: "Alert test failed: " + value, c_alarmPending: false, intervalDays: state.intervalDays, alarmTime: state.alarmTime, entries: state.entries, draft_plantName: state.draft_plantName, draft_lastWatered: state.draft_lastWatered, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
