}

function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, intervalDays: state.intervalDays, alarmTime: state.alarmTime, entries: state.entries, draft_plantName: state.draft_plantName, draft_lastWatered: state.draft_lastWatered, removedEntries: state.removedEntries, removedAt: state.removedAt, c_alarmStatus: state.c_alarmStatus, c_alarmPending: state.c_alarmPending};
