@jsonable
class AppState {
  effectStatus: string;
  workSec7: number;
  restSec7: number;
  rounds7: number;
  round7: number;
  phase7: number;
  phaseMs7: number;
  running7: boolean;
  focusMs7: number;
  inSeconds7: boolean;
}

function init(): AppState {
  let workSec7: number = 40;
  if (workSec7 < 5 || workSec7 > 14400) { workSec7 = 1500; }
  let restSec7: number = 20;
  if (restSec7 < 0 || restSec7 > 7200) { restSec7 = 300; }
  let rounds7: number = 8;
  if (rounds7 < 1 || rounds7 > 50) { rounds7 = 4; }
  let inSeconds7: boolean = workSec7 < 120;
  return {effectStatus: "", workSec7: workSec7, restSec7: restSec7, rounds7: rounds7, round7: 1, phase7: 0, phaseMs7: 0, running7: false, focusMs7: 0, inSeconds7: inSeconds7};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}







function onEffect(state: AppState, value: string): AppState {
  return {effectStatus: value, workSec7: state.workSec7, restSec7: state.restSec7, rounds7: state.rounds7, round7: state.round7, phase7: state.phase7, phaseMs7: state.phaseMs7, running7: state.running7, focusMs7: state.focusMs7, inSeconds7: state.inSeconds7};
}



function rebuildCycle7(state: AppState, round: number, phase: number, phaseMs: number, running: boolean, focusMs: number): AppState {
  return {workSec7: state.workSec7, restSec7: state.restSec7, rounds7: state.rounds7, round7: round, phase7: phase, phaseMs7: phaseMs, running7: running, focusMs7: focusMs, inSeconds7: state.inSeconds7, effectStatus: state.effectStatus};
}

function phaseLimitMs7(state: AppState, phase: number): number {
  if (phase === 0) { return state.workSec7 * 1000; }
  if (phase === 1) { return state.restSec7 * 1000; }
  return 0;
}

function signal7(): number {
  if (true) { sdk.call("SensorServiceKit.vibrator.vibrate", ["duration", "800"], "onSignalAnswered7"); }
  return 0;
}

function onSignalAnswered7(state: AppState, value: string): AppState {
  return state;
}

function nextPhase7(state: AppState, focusMs: number, running: boolean): AppState {
  if (state.phase7 === 0) {
    if (state.round7 >= state.rounds7) { return rebuildCycle7(state, state.round7, 2, 0, false, focusMs); }
    if (state.restSec7 <= 0) { return rebuildCycle7(state, state.round7 + 1, 0, 0, running, focusMs); }
    return rebuildCycle7(state, state.round7, 1, 0, running, focusMs);
  }
  if (state.phase7 === 1) { return rebuildCycle7(state, state.round7 + 1, 0, 0, running, focusMs); }
  return state;
}

function onCycleTick7(state: AppState, elapsedMs: number): AppState {
  if (!state.running7 || state.phase7 === 2) { return state; }
  let limit: number = phaseLimitMs7(state, state.phase7);
  let next: number = state.phaseMs7 + elapsedMs;
  let focus: number = state.focusMs7;
  if (next >= limit) {
    if (state.phase7 === 0) { focus = focus + (limit - state.phaseMs7); }
    let ignored: number = signal7();
    return nextPhase7(state, focus, true);
  }
  if (state.phase7 === 0) { focus = focus + elapsedMs; }
  return rebuildCycle7(state, state.round7, state.phase7, next, true, focus);
}

function toggleCycle7(state: AppState, ignored: number): AppState {
  if (state.phase7 === 2) { return rebuildCycle7(state, 1, 0, 0, true, 0); }
  return rebuildCycle7(state, state.round7, state.phase7, state.phaseMs7, !state.running7, state.focusMs7);
}

function skipPhase7(state: AppState, ignored: number): AppState {
  if (state.phase7 === 2) { return state; }
  return nextPhase7(state, state.focusMs7, state.running7);
}

function resetCycle7(state: AppState, ignored: number): AppState {
  return rebuildCycle7(state, 1, 0, 0, false, 0);
}

