  let seconds: number = value * 60;
  if (state.inSeconds7) { seconds = value; }
  if (seconds < 5) { seconds = 5; }
  return {workSec7: seconds, phaseMs7: 0, effectStatus: state.effectStatus, restSec7: state.restSec7, rounds7: state.rounds7, round7: state.round7, phase7: state.phase7, running7: state.running7, focusMs7: state.focusMs7, inSeconds7: state.inSeconds7};
}

function setRest7(state: AppState, value: number): AppState {
  let seconds: number = value * 60;
  if (state.inSeconds7) { seconds = value; }
  if (seconds < 0) { seconds = 0; }
  return {restSec7: seconds, phaseMs7: 0, effectStatus: state.effectStatus, workSec7: state.workSec7, rounds7: state.rounds7, round7: state.round7, phase7: state.phase7, running7: state.running7, focusMs7: state.focusMs7, inSeconds7: state.inSeconds7};
