function c_daysInMonth(year: number, month: number): number {
  if (month === 2) {
    if (year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0)) { return 29; }
    return 28;
  }
  if (month === 4 || month === 6 || month === 9 || month === 11) { return 30; }
  return 31;
}

function c_firstWeekday(year: number, month: number): number {
  let y: number = year;
  let m: number = month;
  if (m < 3) { m = m + 12; y = y - 1; }
  let k: number = y % 100;
  let j: number = math.floor(y / 100);
  let h: number = (1 + math.floor(13 * (m + 1) / 5) + k + math.floor(k / 4) + math.floor(j / 4) + 5 * j) % 7;
  return (h + 6) % 7;
}

function c_dayNumber(year: number, month: number, day: number): number {
  let total: number = 0;
  let y: number = 1970;
  while (y < year) {
    if (y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0)) { total = total + 366; } else { total = total + 365; }
    y = y + 1;
  }
  let m: number = 1;
  while (m < month) {
    total = total + c_daysInMonth(year, m);
    m = m + 1;
  }
  total = total + day - 1;
  return total;
}

