  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_billName: "", draft_amount: "", draft_dueDate: state.draft_dueDate, removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
