function c_addReminder(state: AppState, ignored: number): AppState {
  let leadValues: number[] = [0, 15, 60, 1440];
  let lead: number = leadValues[state.reminderLeadIndex];
  let nowMs: number = time.nowMillis();
  let dayMs: number = 86400000;
  let todayStart: number = nowMs - time.millisOfDay();
  let paydayStart: number = todayStart + state.payday * 60000;
  if (paydayStart <= nowMs) {
    paydayStart = paydayStart + dayMs;
  }
  let endMs: number = paydayStart + 3600000;
  let freq: number = 2;
  let interval: number = 1;
  if (state.repeatDaysIndex === 0) {
    freq = 2;
    interval = 1;
  } else {
    if (state.repeatDaysIndex === 1) {
      freq = 2;
      interval = 2;
    } else {
      freq = 1;
      interval = 1;
    }
  }
  let events: string = "[{\"title\":\"Payday\",\"startTime\":\"" + ui.numberToString(paydayStart) + "\",\"endTime\":\"" + ui.numberToString(endMs) + "\",\"reminderTime\":[" + ui.numberToString(lead) + "],\"recurrenceRule\":{\"recurrenceFrequency\":" + ui.numberToString(freq) + ",\"interval\":" + ui.numberToString(interval) + "}}]";
