    return 28;
  }
  if (m === 4 || m === 6 || m === 9 || m === 11) { return 30; }
  return 31;
}

function c_firstWeekday(monthIndex: number): number {
  let today: number = time.year() * 12 + time.monthOfYear() - 1;
  let diff: number = monthIndex - today;
  let wd: number = time.weekday() + diff * 31;
  wd = wd % 7;
  if (wd < 0) { wd = wd + 7; }
