import * as ui from "std/ui"

@jsonable
class AppState {
  elapsedMs: number;
  running: boolean;
  finished: boolean;
  callLengthIndex: number;
  reminderLeadIndex: number;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, callLengthIndex: 2, reminderLeadIndex: 1};
}

function countdownSeconds(state: AppState): number {
  let callLengthValues: number[] = [300, 600, 900, 1800];
  let callLength: number = callLengthValues[state.callLengthIndex];
  let reminderLeadValues: number[] = [0, 60, 120, 300];
  let reminderLead: number = reminderLeadValues[state.reminderLeadIndex];
  return callLength;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, callLengthIndex: state.callLengthIndex, reminderLeadIndex: state.reminderLeadIndex}; }
  return {elapsedMs: total, running: false, finished: true, callLengthIndex: state.callLengthIndex, reminderLeadIndex: state.reminderLeadIndex};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, callLengthIndex: state.callLengthIndex, reminderLeadIndex: state.reminderLeadIndex};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, callLengthIndex: state.callLengthIndex, reminderLeadIndex: state.reminderLeadIndex};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, callLengthIndex: state.callLengthIndex, reminderLeadIndex: state.reminderLeadIndex};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_callLength(state: AppState, value: number): AppState {
  return {callLengthIndex: value, elapsedMs: 0, running: false, finished: false, reminderLeadIndex: state.reminderLeadIndex};
}

function set_reminderLead(state: AppState, value: number): AppState {
  return {reminderLeadIndex: value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, callLengthIndex: state.callLengthIndex};
}







