import * as ui from "std/ui"

@jsonable
class LogEntry {
  name: string;
  phone: string;
  minute: number;
}

@jsonable
class AppState {
  entries: LogEntry[];
  draft_name: string;
  draft_phone: string;
  removedEntries: LogEntry[];
  removedAt: number;
  c_callStatus: string;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {entries: emptyEntries, draft_name: "", draft_phone: "", removedEntries: emptyEntries, removedAt: -1, c_callStatus: ""};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}







function set_draft_name(state: AppState, value: string): AppState {
  return {draft_name: value, entries: state.entries, draft_phone: state.draft_phone, removedEntries: state.removedEntries, removedAt: state.removedAt, c_callStatus: state.c_callStatus};
}

function set_draft_phone(state: AppState, value: string): AppState {
  return {draft_phone: value, entries: state.entries, draft_name: state.draft_name, removedEntries: state.removedEntries, removedAt: state.removedAt, c_callStatus: state.c_callStatus};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_name) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {name: strings.trim(state.draft_name), phone: strings.trim(state.draft_phone), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_name: "", draft_phone: "", removedAt: state.removedAt, c_callStatus: state.c_callStatus};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, draft_name: state.draft_name, draft_phone: state.draft_phone, c_callStatus: state.c_callStatus};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, draft_name: state.draft_name, draft_phone: state.draft_phone, c_callStatus: state.c_callStatus};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, entries: state.entries, draft_name: state.draft_name, draft_phone: state.draft_phone, c_callStatus: state.c_callStatus};
}





function c_callCoworker(state: AppState, value: number): AppState {
  if (value < 0 || value >= state.entries.length()) { return {c_callStatus: "That coworker is no longer in the list.", entries: state.entries, draft_name: state.draft_name, draft_phone: state.draft_phone, removedEntries: state.removedEntries, removedAt: state.removedAt}; }
  let e: LogEntry = state.entries[value];
  let num: string = strings.trim(e.phone);
  if (num === "") { return {c_callStatus: "Add a phone number for " + e.name + " first.", entries: state.entries, draft_name: state.draft_name, draft_phone: state.draft_phone, removedEntries: state.removedEntries, removedAt: state.removedAt}; }
  sdk.call("TelephonyKit.call.makeCall", ["phoneNumber", num], "c_onCall");
  return {c_callStatus: "Opening the dialer for " + e.name + "…", entries: state.entries, draft_name: state.draft_name, draft_phone: state.draft_phone, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function c_onCall(state: AppState, value: string): AppState {
  let failed: boolean = strings.startsWith(value, "declined") || strings.startsWith(value, "error");
  if (failed) {
    return {c_callStatus: "Could not open the dialer: " + value, entries: state.entries, draft_name: state.draft_name, draft_phone: state.draft_phone, removedEntries: state.removedEntries, removedAt: state.removedAt};
  }
  return {c_callStatus: "Dialer opened with the number ready — confirm the call there.", entries: state.entries, draft_name: state.draft_name, draft_phone: state.draft_phone, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Quick Dial", "SPEED DIAL", "One tap to call a coworker", ""));
