    }
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Name", state.draft_name, "set_draft_name"), ui.TextField("default", "Phone", state.draft_phone, "set_draft_phone"), ui.ActionBar("end", [ui.Button("primary", "Add", "addEntry", 0, strings.trim(state.draft_name) !== "")])]));
    sections.push(ui.Section("content", "", "", [ui.SectionHeader("default", "Coworkers", "Newest first", ui.numberToString(entryCount)), ui.When(entryCount === 0, ui.EmptyState("default", "Nothing added yet", "Fill in the fields above and tap Add.", "", "", "list")), ui.When(entryCount > 0, ui.ListGroup("default", "", rows)), ui.When(state.removedEntries.length() > 0, ui.Snackbar("default", "Removed", "Undo", "undoRemove")), ui.Ticker("default", "undoClock", 6000 + state.entries.length() % 7, state.removedEntries.length() > 0, "expireUndo")]));
