function liveCap(n: number, places: number): number {
  let a: number = n;
  if (a < 0) { a = 0 - a; }
  let most: number = 6;
  while (a >= 1 && most > 0) {
    a = a / 10;
    most = most - 1;
  }
  if (places > most) { return most; }
