  if (strings.startsWith(why, "error")) {
    let parts: string[] = strings.split(why, ": ");
    if (parts.length() > 1) {
      why = "";
      let i: number = 1;
      while (i < parts.length()) {
        if (i > 1) { why = why + ": "; }
        why = why + parts[i];
        i = i + 1;
