import * as ui from "std/ui"

@jsonable
class Item {
  label: string;
  detail: string;
  done: boolean;
}

@jsonable
class AppState {
  items7: Item[];
  c_heard: string;
  c_status: string;
  c_pending: boolean;
}

function init(): AppState {
  let items7: Item[] = [
    {label: "Milk", detail: "", done: false},
    {label: "Eggs", detail: "", done: false},
    {label: "Bread", detail: "", done: false},
    {label: "Butter", detail: "", done: false},
    {label: "Apples", detail: "", done: false},
    {label: "Bananas", detail: "", done: false},
    {label: "Rice", detail: "", done: false},
    {label: "Coffee", detail: "", done: false}
  ];
  return {items7: items7, c_heard: "", c_status: "", c_pending: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}











function toggle7(state: AppState, index: number): AppState {
  let out: Item[] = [];
  let i: number = 0;
  while (i < state.items7.length()) {
    let it: Item = state.items7[i];
    if (i === index) {
      out.push({label: it.label, detail: it.detail, done: !it.done});
    } else {
      out.push(it);
    }
    i = i + 1;
  }
  return {items7: out, c_heard: state.c_heard, c_status: state.c_status, c_pending: state.c_pending};
}

function doneCount7(state: AppState): number {
  let n: number = 0;
  let i: number = 0;
  while (i < state.items7.length()) {
    let it: Item = state.items7[i];
    if (it.done) { n = n + 1; }
    i = i + 1;
  }
  return n;
}

function c_startListening(state: AppState, ignored: number): AppState {
  sdk.call("com.huawei.hmos.soundrecorder/phone/MainAbility/StartRecord", [], "c_onRecorded", "background");
  return {c_pending: true, c_status: "Recording a voice note. Speak your items, then stop it in the recorder and come back.", items7: state.items7, c_heard: state.c_heard};
}

function c_onRecorded(state: AppState, value: string): AppState {
  let failed: boolean = strings.startsWith(value, "declined") || strings.startsWith(value, "error");
  if (failed) {
    return {c_pending: false, c_status: "The recorder did not start: " + value, items7: state.items7, c_heard: state.c_heard};
  }
  return {c_pending: false, c_status: "Recorder opened. Speak your items there, then type what you said below.", items7: state.items7, c_heard: state.c_heard};
}

function c_setHeard(state: AppState, value: string): AppState {
  return {c_heard: value, items7: state.items7, c_status: state.c_status, c_pending: state.c_pending};
}

function c_addHeard(state: AppState, ignored: number): AppState {
  let text: string = strings.trim(state.c_heard);
  if (text.length() === 0) {
    return {c_status: "Type or paste the items you spoke first.", items7: state.items7, c_heard: state.c_heard, c_pending: state.c_pending};
  }
  let parts: string[] = strings.split(text, ",");
  let out: Item[] = [];
  for (let old: Item of state.items7) {
    out.push(old);
  }
  let added: number = 0;
  for (let raw: string of parts) {
    let name: string = strings.trim(raw);
    if (name.length() > 0) {
      out.push({label: name, detail: "spoken", done: false});
      added = added + 1;
    }
  }
  if (added === 0) {
    return {c_status: "No items found in that text. Separate items with commas.", items7: state.items7, c_heard: state.c_heard, c_pending: state.c_pending};
  }
  return {items7: out, c_heard: "", c_status: "Added " + ui.numberToString(added) + " item(s) to the list.", c_pending: state.c_pending};
}



function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Voice Grocery List", "SPEAK & SHOP", "", ""));
  {
  }
  {
      let count: number = state.items7.length();
      let rows: ui.View[] = [];
      let j: number = 0;
      while (j < count) {
        let it: Item = state.items7[j];
        let icon: string = "";
        let subtitle: string = it.detail;
        if (it.done) { icon = "check"; subtitle = "done"; if (it.detail.length() > 0) { subtitle = it.detail + " - done"; } }
        rows.push(ui.ListItem("default", it.label, subtitle, "", "toggle7", j, true, icon));
        j = j + 1;
      }
      sections.push(ui.Section("content", "", "", [
        ui.When(count === 0, ui.EmptyState("default", "Nothing here", "Add an item to get started.", "", "", "pin")),
        ui.When(count > 0, ui.ListGroup("default", ui.numberToString(doneCount7(state)) + " of " + ui.numberToString(count) + " done - tap one to tick it", rows))
      ]));
    }
  {
  sections.push(ui.Section("content", "Speak your list", "Record a voice note, then type what you said", [
    ui.ActionBar("end", [
      ui.Button("primary", "Start voice note", "c_startListening", 0, !state.c_pending)
    ]),
    ui.When(state.c_pending, ui.Spinner("default", "Opening the recorder...")),
    ui.When(state.c_status.length() > 0, ui.InsetBanner("default", "", state.c_status, "", "", "info")),
    ui.TextField("default", "Items you spoke (separate with commas)", state.c_heard, "c_setHeard"),
    ui.ActionBar("end", [
      ui.Button("secondary", "Add to list", "c_addHeard", 0, true)
    ])
  ]));
  }
  {
    sections.push(ui.Section("supporting", "", "", [ui.InsetBanner("default", "Done differently", "Your phone's recorder can capture the voice note, but this app cannot turn that recording into text by itself, so you type or paste what...", "", "", "info")]));
  }
  return ui.AppTheme("clean", "", sections);
}

