import * as ui from "std/ui"

@jsonable
class AppState {
  neighborName: string;
  packageSpotIndex: number;
  sendNow: boolean;
}

function init(): AppState {
  return {neighborName: "", packageSpotIndex: 0, sendNow: true};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_neighborName(state: AppState, value: string): AppState {
  return {neighborName: value, packageSpotIndex: state.packageSpotIndex, sendNow: state.sendNow};
}

function set_packageSpot(state: AppState, value: number): AppState {
  return {packageSpotIndex: value, neighborName: state.neighborName, sendNow: state.sendNow};
}

function set_sendNow(state: AppState, value: boolean): AppState {
  return {sendNow: value, neighborName: state.neighborName, packageSpotIndex: state.packageSpotIndex};
}







function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Package Text", "QUICK TEXT", "Send a neighbor a heads-up about a package", ""));
  {
      let packageSpotValues: number[] = [0, 1, 2, 3];
      let packageSpot: number = packageSpotValues[state.packageSpotIndex];
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Neighbor", state.neighborName, "set_neighborName"), ui.Select("default", "Left at", ["Front door", "Porch", "Mailbox", "With me"], state.packageSpotIndex, "set_packageSpot"), ui.Toggle("default", "Send now", state.sendNow, "set_sendNow")]));
  }
  return ui.AppTheme("soft", "", sections);
}

