@jsonable
class AppState {
  newTime: number;
  newDate: string;
  reasonIndex: number;
  includeApology: boolean;
}

function init(): AppState {
  return {newTime: 600, newDate: "", reasonIndex: 0, includeApology: true};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_newTime(state: AppState, value: number): AppState {
  return {newTime: value, newDate: state.newDate, reasonIndex: state.reasonIndex, includeApology: state.includeApology};
}

function set_newDate(state: AppState, value: string): AppState {
  return {newDate: value, newTime: state.newTime, reasonIndex: state.reasonIndex, includeApology: state.includeApology};
}

function set_reason(state: AppState, value: number): AppState {
  return {reasonIndex: value, newTime: state.newTime, newDate: state.newDate, includeApology: state.includeApology};
}

function set_includeApology(state: AppState, value: boolean): AppState {
  return {includeApology: value, newTime: state.newTime, newDate: state.newDate, reasonIndex: state.reasonIndex};
}







function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Meeting Change", "GROUP MESSAGE", "Draft a quick note about a meeting change", ""));
