      let newTime: number = state.newTime;
      let reasonValues: number[] = [0, 1, 2, 3];
      let reason: number = reasonValues[state.reasonIndex];
      let messageLead: number = 0;
    sections.push(ui.Section("content", "", "", [ui.TimeField("default", "New time", state.newTime, "set_newTime"), ui.TextField("default", "New date", state.newDate, "set_newDate"), ui.Select("default", "Reason", ["Conflict", "Running late", "Room change", "Other"], state.reasonIndex, "set_reason"), ui.Toggle("default", "Include apology", state.includeApology, "set_includeApology")]));
