  c_message: string;
}

function init(): AppState {
  return {c_airplane: false, c_wifi: true, c_bluetooth: true, c_cellular: true, c_dnd: false, c_message: ""};
}

function c_offCount(state: AppState): number {
  let n: number = 0;
  if (!state.c_airplane) { n = n + 1; }
  if (!state.c_wifi) { n = n + 1; }
  if (!state.c_bluetooth) { n = n + 1; }
  if (!state.c_cellular) { n = n + 1; }
  return n;
}

function c_setAirplane(state: AppState, value: boolean): AppState {
  sdk.call("com.huawei.hmos.slassistant/phone/DefaultIntentBackgroundUiAbility/SetSettingSwitch", [], "c_onAnswer", "background");
  return {c_airplane: value, c_message: "Asking the phone to change Airplane mode...", c_wifi: state.c_wifi, c_bluetooth: state.c_bluetooth, c_cellular: state.c_cellular, c_dnd: state.c_dnd};
}

function c_setWifi(state: AppState, value: boolean): AppState {
  if (value) {
    sdk.call("ConnectivityKit.wifiManager.enableWifi", [], "c_onAnswer");
  } else {
    sdk.call("ConnectivityKit.wifiManager.disableWifi", [], "c_onAnswer");
  }
  return {c_wifi: value, c_message: "Asking the phone to change Wi-Fi...", c_airplane: state.c_airplane, c_bluetooth: state.c_bluetooth, c_cellular: state.c_cellular, c_dnd: state.c_dnd};
}

function c_setBluetooth(state: AppState, value: boolean): AppState {
  sdk.call("com.huawei.hmos.settings/phone_settings/DefaultIntentBackgroundUiAbility/SetDeviceInterconnectivity", [], "c_onAnswer", "background");
  return {c_bluetooth: value, c_message: "Asking the phone to change Bluetooth...", c_airplane: state.c_airplane, c_wifi: state.c_wifi, c_cellular: state.c_cellular, c_dnd: state.c_dnd};
}

function c_setCellular(state: AppState, value: boolean): AppState {
  sdk.call("com.huawei.hmos.communicationsetting/entry/DefaultIntentBackgroundUiAbility/JumpToTrafficManagement", [], "c_onAnswer", "background");
  return {c_cellular: value, c_message: "Opening mobile data settings...", c_airplane: state.c_airplane, c_wifi: state.c_wifi, c_bluetooth: state.c_bluetooth, c_dnd: state.c_dnd};
}

function c_setDnd(state: AppState, value: boolean): AppState {
  sdk.call("com.huawei.hmos.slassistant/phone/DefaultIntentBackgroundUiAbility/SetSettingSwitch", [], "c_onAnswer", "background");
  return {c_dnd: value, c_message: "Asking the phone to change Do not disturb...", c_airplane: state.c_airplane, c_wifi: state.c_wifi, c_bluetooth: state.c_bluetooth, c_cellular: state.c_cellular};
}

