  c_radioRows.push(ui.ListItem("default", "Wi-Fi", "Wireless networks", "", "c_tapWifi", 0, true, ""));
  c_radioRows.push(ui.ListItem("default", "Bluetooth", "Headphones and accessories", "", "c_tapBluetooth", 0, true, ""));
  c_radioRows.push(ui.ListItem("default", "Cellular data", "Mobile internet", "", "c_tapCellular", 0, true, ""));
  sections.push(ui.Section("summary", "", "", [
    ui.MetricGroup("default", 2, [
