import * as ui from "std/ui"

@jsonable
class AppState {
  autoRotate: boolean;
}

function init(): AppState {
  return {autoRotate: true};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_autoRotate(state: AppState, value: boolean): AppState {
  return {autoRotate: value};
}







function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Auto Rotate Lock", "SCREEN LOCK", "Lock or unlock auto-rotate with one tap", ""));
  {
    sections.push(ui.Section("content", "", "", [ui.Toggle("default", "Auto-rotate", state.autoRotate, "set_autoRotate")]));
  }
  return ui.AppTheme("clean", "", sections);
}

