import * as ui from "std/ui"

@jsonable
class AppState {
  hotspotOn: boolean;
  c_hotspotStatus: string;
  c_hotspotPending: boolean;
}

function init(): AppState {
  return {hotspotOn: false, c_hotspotStatus: "", c_hotspotPending: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_hotspotOn(state: AppState, value: boolean): AppState {
  return {hotspotOn: value, c_hotspotStatus: state.c_hotspotStatus, c_hotspotPending: state.c_hotspotPending};
}







function c_toggleHotspot(state: AppState, value: boolean): AppState {
  sdk.call("com.ohos.sceneboard/phone_sceneboard/ScbIntentUIAbility/SetSettingSwitch", [], "c_onHotspotSet", "background");
  return {hotspotOn: value, c_hotspotPending: true, c_hotspotStatus: ""};
}

function c_onHotspotSet(state: AppState, value: string): AppState {
  let failed: boolean = strings.startsWith(value, "declined") || strings.startsWith(value, "error");
  let msg: string = "";
  if (failed) {
    msg = "The hotspot setting could not be changed: " + value;
  } else {
    msg = "The hotspot setting was sent to your phone's settings.";
  }
  return {c_hotspotStatus: msg, c_hotspotPending: false, hotspotOn: state.hotspotOn};
}

function c_checkHotspot(state: AppState, ignored: number): AppState {
  sdk.call("ConnectivityKit.wifiManager.isHotspotActive", [], "c_onHotspotChecked");
