  return {wifi: true, bluetooth: true, gps: true, airplane: false, mobileData: true, hotspot: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_wifi(state: AppState, value: boolean): AppState {
  return {wifi: value, bluetooth: state.bluetooth, gps: state.gps, airplane: state.airplane, mobileData: state.mobileData, hotspot: state.hotspot};
}

function set_bluetooth(state: AppState, value: boolean): AppState {
  return {bluetooth: value, wifi: state.wifi, gps: state.gps, airplane: state.airplane, mobileData: state.mobileData, hotspot: state.hotspot};
}

function set_gps(state: AppState, value: boolean): AppState {
  return {gps: value, wifi: state.wifi, bluetooth: state.bluetooth, airplane: state.airplane, mobileData: state.mobileData, hotspot: state.hotspot};
}

function set_airplane(state: AppState, value: boolean): AppState {
  return {airplane: value, wifi: state.wifi, bluetooth: state.bluetooth, gps: state.gps, mobileData: state.mobileData, hotspot: state.hotspot};
}

function set_mobileData(state: AppState, value: boolean): AppState {
  return {mobileData: value, wifi: state.wifi, bluetooth: state.bluetooth, gps: state.gps, airplane: state.airplane, hotspot: state.hotspot};
}

function set_hotspot(state: AppState, value: boolean): AppState {
  return {hotspot: value, wifi: state.wifi, bluetooth: state.bluetooth, gps: state.gps, airplane: state.airplane, mobileData: state.mobileData};
}







function c_switchesOn(state: AppState): number {
  let n: number = 0;
  if (state.wifi) { n = n + 1; }
  if (state.bluetooth) { n = n + 1; }
  if (state.gps) { n = n + 1; }
  if (state.airplane) { n = n + 1; }
  if (state.mobileData) { n = n + 1; }
  if (state.hotspot) { n = n + 1; }
  return n;
}

function c_locationReady(state: AppState): number {
  if (state.gps && !state.airplane) { return 1; }
  return 0;
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Quick Switches", "LOCATION TOGGLES", "One-tap switches for the location services you use most", ""));
  {
    sections.push(ui.Section("content", "", "", [ui.Toggle("default", "Wi-Fi", state.wifi, "set_wifi"), ui.Toggle("default", "Bluetooth", state.bluetooth, "set_bluetooth"), ui.Toggle("default", "GPS", state.gps, "set_gps"), ui.Toggle("default", "Airplane Mode", state.airplane, "set_airplane"), ui.Toggle("default", "Mobile Data", state.mobileData, "set_mobileData"), ui.Toggle("default", "Hotspot", state.hotspot, "set_hotspot")]));
  }
  {
  let c_on: number = c_switchesOn(state);
  let c_ready: number = c_locationReady(state);
  let c_readyText: string = "No";
  if (c_ready === 1) { c_readyText = "Yes"; }
  sections.push(ui.Section("summary", "Status", "How the switches stand right now", [
    ui.MetricGroup("default", 2, [
      ui.NumberStat("default", "Switches On", c_on, "", " of 6", 1, "quick switches currently on", "check"),
      ui.Stat("accent", "Location Ready", c_readyText, "GPS on and airplane mode off", "pin")
    ]),
    ui.When(c_ready === 0,
      ui.InsetBanner("warning", "Location services are blocked",
        "Turn GPS on and airplane mode off so location services can work.", "", "", "warning"))
  ]));
  }
  return ui.AppTheme("technical", "", sections);
}

