import * as ui from "std/ui"

@jsonable
class AppState {
  elapsedMs: number;
  running: boolean;
  finished: boolean;
  intervalIndex: number;
  sessionLengthIndex: number;
  c_lastBellIndex: number;
  c_bellStatus: string;
  settingsOpen: boolean;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, intervalIndex: 1, sessionLengthIndex: 2, c_lastBellIndex: 0, c_bellStatus: "", settingsOpen: false};
}

function countdownSeconds(state: AppState): number {
  let intervalValues: number[] = [60, 180, 300, 600];
  let interval: number = intervalValues[state.intervalIndex];
  let sessionLengthValues: number[] = [600, 1200, 1800, 2700];
  let sessionLength: number = sessionLengthValues[state.sessionLengthIndex];
  return sessionLength;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, intervalIndex: state.intervalIndex, sessionLengthIndex: state.sessionLengthIndex, c_lastBellIndex: state.c_lastBellIndex, c_bellStatus: state.c_bellStatus, settingsOpen: state.settingsOpen}; }
  return {elapsedMs: total, running: false, finished: true, intervalIndex: state.intervalIndex, sessionLengthIndex: state.sessionLengthIndex, c_lastBellIndex: state.c_lastBellIndex, c_bellStatus: state.c_bellStatus, settingsOpen: state.settingsOpen};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, intervalIndex: state.intervalIndex, sessionLengthIndex: state.sessionLengthIndex, c_lastBellIndex: state.c_lastBellIndex, c_bellStatus: state.c_bellStatus, settingsOpen: state.settingsOpen};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, intervalIndex: state.intervalIndex, sessionLengthIndex: state.sessionLengthIndex, c_lastBellIndex: state.c_lastBellIndex, c_bellStatus: state.c_bellStatus, settingsOpen: state.settingsOpen};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, intervalIndex: state.intervalIndex, sessionLengthIndex: state.sessionLengthIndex, c_lastBellIndex: state.c_lastBellIndex, c_bellStatus: state.c_bellStatus, settingsOpen: state.settingsOpen};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_interval(state: AppState, value: number): AppState {
  return {intervalIndex: value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, sessionLengthIndex: state.sessionLengthIndex, c_lastBellIndex: state.c_lastBellIndex, c_bellStatus: state.c_bellStatus, settingsOpen: state.settingsOpen};
}

function set_sessionLength(state: AppState, value: number): AppState {
  return {sessionLengthIndex: value, elapsedMs: 0, running: false, finished: false, intervalIndex: state.intervalIndex, c_lastBellIndex: state.c_lastBellIndex, c_bellStatus: state.c_bellStatus, settingsOpen: state.settingsOpen};
}







function c_intervalSeconds(state: AppState): number {
  let values: number[] = [60, 180, 300, 600];
  return values[state.intervalIndex];
}

function c_bellsDue(state: AppState): number {
  let interval: number = c_intervalSeconds(state);
  if (interval <= 0) { return 0; }
  return math.floor(state.elapsedMs / (interval * 1000));
}

function c_ringBell(state: AppState, ignored: number): AppState {
  sdk.call("AudioKit.TonePlayer.start", [], "c_onBellAnswer");
  return {c_bellStatus: "Ringing the bell...", elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, intervalIndex: state.intervalIndex, sessionLengthIndex: state.sessionLengthIndex, c_lastBellIndex: state.c_lastBellIndex, settingsOpen: state.settingsOpen};
}

function c_onBellAnswer(state: AppState, value: string): AppState {
  let failed: boolean = strings.startsWith(value, "declined") || strings.startsWith(value, "error");
  if (failed) {
    return {c_bellStatus: "The bell could not play: " + value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, intervalIndex: state.intervalIndex, sessionLengthIndex: state.sessionLengthIndex, c_lastBellIndex: state.c_lastBellIndex, settingsOpen: state.settingsOpen};
  }
  return {c_bellStatus: "Bell played", elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, intervalIndex: state.intervalIndex, sessionLengthIndex: state.sessionLengthIndex, c_lastBellIndex: state.c_lastBellIndex, settingsOpen: state.settingsOpen};
}

function c_checkBell(state: AppState, ignored: number): AppState {
  let due: number = c_bellsDue(state);
  if (due > state.c_lastBellIndex) {
    sdk.call("AudioKit.TonePlayer.start", [], "c_onBellAnswer");
    return {c_lastBellIndex: due, c_bellStatus: "Bell rang at " + ui.durationToString(due * c_intervalSeconds(state)), elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, intervalIndex: state.intervalIndex, sessionLengthIndex: state.sessionLengthIndex, settingsOpen: state.settingsOpen};
  }
  return {c_lastBellIndex: state.c_lastBellIndex, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, intervalIndex: state.intervalIndex, sessionLengthIndex: state.sessionLengthIndex, c_bellStatus: state.c_bellStatus, settingsOpen: state.settingsOpen};
}

function c_syncBell(state: AppState, ignored: number): AppState {
  let due: number = c_bellsDue(state);
  if (due > state.c_lastBellIndex) {
    sdk.call("AudioKit.TonePlayer.start", [], "c_onBellAnswer");
