import * as ui from "std/ui"

@jsonable
class AppState {
  elapsedMs: number;
  running: boolean;
  finished: boolean;
  timerLengthIndex: number;
  effectStatus: string;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, timerLengthIndex: 2, effectStatus: ""};
}

function countdownSeconds(state: AppState): number {
  let timerLengthValues: number[] = [300, 600, 900, 1200, 1800, 2700, 3600];
  let timerLength: number = timerLengthValues[state.timerLengthIndex];
  return timerLength;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, timerLengthIndex: state.timerLengthIndex, effectStatus: state.effectStatus}; }
  sdk.call("SensorServiceKit.vibrator.vibrate", ["duration", "2000"], "onEffect");
  return {elapsedMs: total, running: false, finished: true, effectStatus: "pending", timerLengthIndex: state.timerLengthIndex};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, timerLengthIndex: state.timerLengthIndex, effectStatus: state.effectStatus};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, timerLengthIndex: state.timerLengthIndex, effectStatus: state.effectStatus};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, timerLengthIndex: state.timerLengthIndex, effectStatus: state.effectStatus};
}

