import * as ui from "std/ui"

@jsonable
class AppState {
  startTime: number;
  endTime: number;
  c_lastBuzz: number;
  c_buzzCount: number;
  c_status: string;
}

function init(): AppState {
  return {startTime: 540, endTime: 1080, c_lastBuzz: 0, c_buzzCount: 0, c_status: ""};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_startTime(state: AppState, value: number): AppState {
  return {startTime: value, endTime: state.endTime, c_lastBuzz: state.c_lastBuzz, c_buzzCount: state.c_buzzCount, c_status: state.c_status};
}

function set_endTime(state: AppState, value: number): AppState {
  return {endTime: value, startTime: state.startTime, c_lastBuzz: state.c_lastBuzz, c_buzzCount: state.c_buzzCount, c_status: state.c_status};
}







function c_buzz(state: AppState, ignored: number): AppState {
  sdk.call("SensorServiceKit.vibrator.vibrate", ["duration", "800"], "c_onBuzz");
  return {c_status: "Vibrating now - time to stretch.", startTime: state.startTime, endTime: state.endTime, c_lastBuzz: state.c_lastBuzz, c_buzzCount: state.c_buzzCount};
}

function c_onBuzz(state: AppState, value: string): AppState {
  let failed: boolean = strings.startsWith(value, "declined") || strings.startsWith(value, "error");
  if (failed) {
    return {c_status: "The phone could not vibrate: " + value, startTime: state.startTime, endTime: state.endTime, c_lastBuzz: state.c_lastBuzz, c_buzzCount: state.c_buzzCount};
  }
  return {c_status: "Buzzed - time to stretch.", startTime: state.startTime, endTime: state.endTime, c_lastBuzz: state.c_lastBuzz, c_buzzCount: state.c_buzzCount};
}

function c_tick(state: AppState, elapsedMs: number): AppState {
  let nowMinute: number = time.hourOfDay() * 60 + time.minuteOfHour();
  let start: number = state.startTime;
  let end: number = state.endTime;
  let inWindow: boolean = false;
  if (start <= end) {
    inWindow = nowMinute >= start && nowMinute < end;
  } else {
    inWindow = nowMinute >= start || nowMinute < end;
  }
  if (!inWindow) {
    return {startTime: state.startTime, endTime: state.endTime, c_lastBuzz: state.c_lastBuzz, c_buzzCount: state.c_buzzCount, c_status: state.c_status};
  }
  let last: number = state.c_lastBuzz;
  let due: boolean = false;
  if (last === 0) {
    due = true;
  } else {
    let gap: number = nowMinute - last;
    if (gap < 0) {
      gap = gap + 1440;
    }
    due = gap >= 60;
  }
  if (!due) {
    return {startTime: state.startTime, endTime: state.endTime, c_lastBuzz: state.c_lastBuzz, c_buzzCount: state.c_buzzCount, c_status: state.c_status};
  }
  sdk.call("SensorServiceKit.vibrator.vibrate", ["duration", "800"], "c_onBuzz");
  return {c_lastBuzz: nowMinute, c_buzzCount: state.c_buzzCount + 1, c_status: "Buzzed - time to stretch.", startTime: state.startTime, endTime: state.endTime};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Hourly Stretch", "HOURLY REMINDER", "A gentle buzz every hour to get you moving", ""));
  {
      let startTime: number = state.startTime;
      let endTime: number = state.endTime;
      let intervalMinutes: number = 60;
    sections.push(ui.Section("content", "", "", [ui.TimeField("default", "Start time", state.startTime, "set_startTime"), ui.TimeField("default", "End time", state.endTime, "set_endTime")]));
  }
  {
  {
    let c_nowMinute: number = time.hourOfDay() * 60 + time.minuteOfHour();
    let c_start: number = state.startTime;
    let c_end: number = state.endTime;
    let c_inWindow: boolean = false;
    if (c_start <= c_end) {
      c_inWindow = c_nowMinute >= c_start && c_nowMinute < c_end;
    } else {
      c_inWindow = c_nowMinute >= c_start || c_nowMinute < c_end;
    }
    let c_next: number = c_nowMinute - (c_nowMinute % 60) + 60;
    if (c_next >= 1440) {
      c_next = c_next - 1440;
    }
    let c_rows: ui.View[] = [];
    c_rows.push(ui.KeyValueItem("default", "Reminder window", ui.clockToString(c_start) + " - " + ui.clockToString(c_end), "A buzz every hour inside this window"));
    c_rows.push(ui.KeyValueItem("default", "Next buzz", ui.clockToString(c_next), "On the hour"));
    c_rows.push(ui.KeyValueItem("default", "Buzzes so far", ui.numberToString(state.c_buzzCount), ""));
    let c_body: ui.View[] = [];
    c_body.push(ui.Ticker("default", "c_stretchTicker", 30000, true, "c_tick"));
    if (c_inWindow) {
      c_body.push(ui.InsetBanner("success", "Reminders running", "The phone will buzz every hour until " + ui.clockToString(c_end) + ".", "", "", "check"));
    } else {
      c_body.push(ui.InsetBanner("default", "Outside the window", "Reminders pause until " + ui.clockToString(c_start) + ".", "", "", "clock"));
    }
    c_body.push(ui.KeyValueGroup("default", 1, c_rows));
    if (state.c_status !== "") {
      c_body.push(ui.Text("caption", state.c_status));
    }
    c_body.push(ui.ActionBar("end", [
      ui.Button("primary", "Buzz now", "c_buzz", 0, true)
    ]));
    sections.push(ui.Section("content", "Stretch reminders", "Vibrates every hour between your start and end time", c_body));
  }
  }
  return ui.AppTheme("soft", "", sections);
}

