import * as ui from "std/ui"

@jsonable
class AppState {
  elapsedMs: number;
  running: boolean;
  finished: boolean;
  workSecondsText: string;
  restSecondsText: string;
  rounds: number;
  effectStatus: string;
  settingsOpen: boolean;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, workSecondsText: "45", restSecondsText: "15", rounds: 8, effectStatus: "", settingsOpen: false};
}

function countdownSeconds(state: AppState): number {
  let workSeconds: number = strings.toNumber(state.workSecondsText, 0);
  let restSeconds: number = strings.toNumber(state.restSecondsText, 0);
  let rounds: number = state.rounds;
  return workSeconds;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, workSecondsText: state.workSecondsText, restSecondsText: state.restSecondsText, rounds: state.rounds, effectStatus: state.effectStatus, settingsOpen: state.settingsOpen}; }
  sdk.call("SensorServiceKit.vibrator.vibrate", ["duration", "2000"], "onEffect");
  return {elapsedMs: total, running: false, finished: true, effectStatus: "pending", workSecondsText: state.workSecondsText, restSecondsText: state.restSecondsText, rounds: state.rounds, settingsOpen: state.settingsOpen};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, workSecondsText: state.workSecondsText, restSecondsText: state.restSecondsText, rounds: state.rounds, effectStatus: state.effectStatus, settingsOpen: state.settingsOpen};
