}

function c_answer(state: AppState, value: number): AppState {
  if (state.c_answered || state.c_finished) {
    return {questionCount: state.questionCount, c_quiz: state.c_quiz, c_index: state.c_index, c_score: state.c_score, c_answered: state.c_answered, c_picked: state.c_picked, c_finished: state.c_finished, c_started: state.c_started, c_seed: state.c_seed};
  }
  let total: number = state.c_quiz.length();
  if (state.c_index >= total) {
    return {questionCount: state.questionCount, c_quiz: state.c_quiz, c_index: state.c_index, c_score: state.c_score, c_answered: state.c_answered, c_picked: state.c_picked, c_finished: state.c_finished, c_started: state.c_started, c_seed: state.c_seed};
  }
  let q: C_Question = state.c_quiz[state.c_index];
  let gained: number = 0;
  if (value === q.correct) { gained = 1; }
  return {c_answered: true, c_picked: value, c_score: state.c_score + gained, questionCount: state.questionCount, c_quiz: state.c_quiz, c_index: state.c_index, c_finished: state.c_finished, c_started: state.c_started, c_seed: state.c_seed};
}

function c_next(state: AppState, ignored: number): AppState {
  if (!state.c_answered) {
    return {questionCount: state.questionCount, c_quiz: state.c_quiz, c_index: state.c_index, c_score: state.c_score, c_answered: state.c_answered, c_picked: state.c_picked, c_finished: state.c_finished, c_started: state.c_started, c_seed: state.c_seed};
  }
  let total: number = state.c_quiz.length();
  let nextIndex: number = state.c_index + 1;
  if (nextIndex >= total) {
    return {c_finished: true, c_answered: false, c_picked: -1, questionCount: state.questionCount, c_quiz: state.c_quiz, c_index: state.c_index, c_score: state.c_score, c_started: state.c_started, c_seed: state.c_seed};
  }
  return {c_index: nextIndex, c_answered: false, c_picked: -1, questionCount: state.questionCount, c_quiz: state.c_quiz, c_score: state.c_score, c_finished: state.c_finished, c_started: state.c_started, c_seed: state.c_seed};
