import * as ui from "std/ui"

@jsonable
class LogEntry {
  animal: string;
  correct: boolean;
  minute: number;
}

@jsonable
class AppState {
  rounds: number;
  entries: LogEntry[];
  draft_animal: string;
  draft_correct: boolean;
  removedEntries: LogEntry[];
  removedAt: number;
  c_round: number;
  c_phase: string;
  c_choice: number;
  c_lastCorrect: boolean;
  c_score: number;
  c_answered: number;
  c_sound: string;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {rounds: 10, entries: emptyEntries, draft_animal: "", draft_correct: false, removedEntries: emptyEntries, removedAt: -1, c_round: 0, c_phase: "listen", c_choice: 0, c_lastCorrect: false, c_score: 0, c_answered: 0, c_sound: "", settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_rounds(state: AppState, value: number): AppState {
  return {rounds: value, entries: state.entries, draft_animal: state.draft_animal, draft_correct: state.draft_correct, removedEntries: state.removedEntries, removedAt: state.removedAt, c_round: state.c_round, c_phase: state.c_phase, c_choice: state.c_choice, c_lastCorrect: state.c_lastCorrect, c_score: state.c_score, c_answered: state.c_answered, c_sound: state.c_sound, settingsOpen: state.settingsOpen};
}



function set_draft_animal(state: AppState, value: string): AppState {
  return {draft_animal: value, rounds: state.rounds, entries: state.entries, draft_correct: state.draft_correct, removedEntries: state.removedEntries, removedAt: state.removedAt, c_round: state.c_round, c_phase: state.c_phase, c_choice: state.c_choice, c_lastCorrect: state.c_lastCorrect, c_score: state.c_score, c_answered: state.c_answered, c_sound: state.c_sound, settingsOpen: state.settingsOpen};
}

function set_draft_correct(state: AppState, value: boolean): AppState {
  return {draft_correct: value, rounds: state.rounds, entries: state.entries, draft_animal: state.draft_animal, removedEntries: state.removedEntries, removedAt: state.removedAt, c_round: state.c_round, c_phase: state.c_phase, c_choice: state.c_choice, c_lastCorrect: state.c_lastCorrect, c_score: state.c_score, c_answered: state.c_answered, c_sound: state.c_sound, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_animal) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {animal: strings.trim(state.draft_animal), correct: state.draft_correct, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_animal: "", rounds: state.rounds, draft_correct: state.draft_correct, removedAt: state.removedAt, c_round: state.c_round, c_phase: state.c_phase, c_choice: state.c_choice, c_lastCorrect: state.c_lastCorrect, c_score: state.c_score, c_answered: state.c_answered, c_sound: state.c_sound, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, rounds: state.rounds, draft_animal: state.draft_animal, draft_correct: state.draft_correct, c_round: state.c_round, c_phase: state.c_phase, c_choice: state.c_choice, c_lastCorrect: state.c_lastCorrect, c_score: state.c_score, c_answered: state.c_answered, c_sound: state.c_sound, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, rounds: state.rounds, draft_animal: state.draft_animal, draft_correct: state.draft_correct, c_round: state.c_round, c_phase: state.c_phase, c_choice: state.c_choice, c_lastCorrect: state.c_lastCorrect, c_score: state.c_score, c_answered: state.c_answered, c_sound: state.c_sound, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, rounds: state.rounds, entries: state.entries, draft_animal: state.draft_animal, draft_correct: state.draft_correct, c_round: state.c_round, c_phase: state.c_phase, c_choice: state.c_choice, c_lastCorrect: state.c_lastCorrect, c_score: state.c_score, c_answered: state.c_answered, c_sound: state.c_sound, settingsOpen: state.settingsOpen};
}





function c_animalAt(index: number): string {
  let names: string[] = ["Cow", "Dog", "Cat", "Duck", "Sheep", "Frog", "Horse", "Pig"];
  let i: number = index % 8;
  if (i < 0) { i = i + 8; }
  return names[i];
}

function c_freqFor(index: number): number {
  let freqs: number[] = [180, 320, 620, 480, 260, 140, 400, 220];
  let i: number = index % 8;
  if (i < 0) { i = i + 8; }
  return freqs[i];
}

function c_optionAt(round: number, slot: number): number {
  return (round * 3 + slot * 5 + 1) % 8;
}

function c_playSound(state: AppState, ignored: number): AppState {
  let animal: number = state.c_round % 8;
  let freq: number = c_freqFor(animal);
  sdk.call("AudioKit.AudioRenderer.write", ["frequencyHz", ui.numberToString(freq), "durationMs", "700", "volume", "0.4"], "c_onAudio");
  return {c_phase: "listen", c_choice: 0, c_sound: "Playing " + c_animalAt(animal) + " sound...", rounds: state.rounds, entries: state.entries, draft_animal: state.draft_animal, draft_correct: state.draft_correct, removedEntries: state.removedEntries, removedAt: state.removedAt, c_round: state.c_round, c_lastCorrect: state.c_lastCorrect, c_score: state.c_score, c_answered: state.c_answered, settingsOpen: state.settingsOpen};
}

function c_onAudio(state: AppState, value: string): AppState {
  if (strings.startsWith(value, "error") || strings.startsWith(value, "declined")) {
    return {c_sound: "Could not play the sound. Try again.", rounds: state.rounds, entries: state.entries, draft_animal: state.draft_animal, draft_correct: state.draft_correct, removedEntries: state.removedEntries, removedAt: state.removedAt, c_round: state.c_round, c_phase: state.c_phase, c_choice: state.c_choice, c_lastCorrect: state.c_lastCorrect, c_score: state.c_score, c_answered: state.c_answered, settingsOpen: state.settingsOpen};
  }
  return {c_sound: "Sound played. Pick the animal.", rounds: state.rounds, entries: state.entries, draft_animal: state.draft_animal, draft_correct: state.draft_correct, removedEntries: state.removedEntries, removedAt: state.removedAt, c_round: state.c_round, c_phase: state.c_phase, c_choice: state.c_choice, c_lastCorrect: state.c_lastCorrect, c_score: state.c_score, c_answered: state.c_answered, settingsOpen: state.settingsOpen};
}

function c_answer(state: AppState, value: number): AppState {
  if (state.c_phase !== "listen") { return state; }
  let animal: number = state.c_round % 8;
  let picked: number = c_optionAt(state.c_round, value);
  let right: boolean = picked === animal;
  let entry: LogEntry = {animal: c_animalAt(animal), correct: right, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  let score: number = state.c_score;
