import * as ui from "std/ui"

@jsonable
class LogEntry {
  animal: string;
  correct: boolean;
  minute: number;
}

@jsonable
class AppState {
  rounds: number;
  entries: LogEntry[];
  draft_animal: string;
  draft_correct: boolean;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {rounds: 10, entries: emptyEntries, draft_animal: "", draft_correct: false, removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_rounds(state: AppState, value: number): AppState {
  return {rounds: value, entries: state.entries, draft_animal: state.draft_animal, draft_correct: state.draft_correct, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_animal(state: AppState, value: string): AppState {
  return {draft_animal: value, rounds: state.rounds, entries: state.entries, draft_correct: state.draft_correct, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_correct(state: AppState, value: boolean): AppState {
  return {draft_correct: value, rounds: state.rounds, entries: state.entries, draft_animal: state.draft_animal, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_animal) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {animal: strings.trim(state.draft_animal), correct: state.draft_correct, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_animal: "", rounds: state.rounds, draft_correct: state.draft_correct, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, rounds: state.rounds, draft_animal: state.draft_animal, draft_correct: state.draft_correct, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, rounds: state.rounds, draft_animal: state.draft_animal, draft_correct: state.draft_correct, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, rounds: state.rounds, entries: state.entries, draft_animal: state.draft_animal, draft_correct: state.draft_correct, settingsOpen: state.settingsOpen};
