import * as ui from "std/ui"

@jsonable
class AppState {
  rounds: number;
  settingsOpen: boolean;
}

function init(): AppState {
  return {rounds: 10, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_rounds(state: AppState, value: number): AppState {
  return {rounds: value, settingsOpen: state.settingsOpen};
}







function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, rounds: state.rounds};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "World Flags Quiz", "FLAG QUIZ", "Guess the country from its flag", ""));
  {
      let rounds: number = state.rounds;
      let pointsPerCorrect: number = 1;
      let score: number = rounds * pointsPerCorrect;
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 1, [ui.NumberStat("default", "Score", score, "", " points", 1, "", "chart", 0)])]));
  }
  {
    let settingsWord: string = "Show";
    if (state.settingsOpen) { settingsWord = "Hide"; }
    sections.push(ui.Section("supporting", "", "", [
      ui.ListItem("default", "Settings", "1 setting", settingsWord, "toggleSettings", 0, true, ""),
      ui.When(state.settingsOpen, ui.Column("default", [ui.NumberField("default", "Rounds", state.rounds, 1, 50, "set_rounds")]))
    ]));
  }
  return ui.AppTheme("playful", "", sections);
}

