function c_nextSeed(seed: number): number {
  return (seed * 1103515245 + 12345) % 2147483648;
}

function c_askedText(e: C_Element, mode: number): string {
  if (mode === 0) { return e.symbol; }
  if (mode === 1) { return e.name; }
  return ui.numberToString(e.number);
}

function c_answerText(e: C_Element, mode: number): string {
  if (mode === 0) { return e.name; }
  return e.symbol;
}

function c_promptText(mode: number): string {
  if (mode === 0) { return "Which element has this symbol?"; }
  if (mode === 1) { return "What is the symbol for this element?"; }
  return "Which symbol has this atomic number?";
}

function c_buildChoices(state: AppState, correct: number, seed: number): number[] {
  let out: number[] = [];
  out.push(correct);
  let s: number = seed;
  let guard: number = 0;
  while (out.length() < 4 && guard < 200) {
    s = c_nextSeed(s);
    let pick: number = s % 20;
    let dup: boolean = false;
    for (let v: number of out) {
      if (v === pick) { dup = true; }
    }
    if (!dup) { out.push(pick); }
    guard = guard + 1;
  }
  let i: number = out.length() - 1;
  while (i > 0) {
    s = c_nextSeed(s);
    let j: number = s % (i + 1);
    let tmp: number = out[i];
    out[i] = out[j];
    out[j] = tmp;
    i = i - 1;
  }
  return out;
}

