<functions>
function c_nextSeed(seed: number): number {
  return (seed * 1103515245 + 12345) % 2147483648;
}

function c_askedText(e: C_Element, mode: number): string {
  if (mode === 0) { return e.symbol; }
  if (mode === 1) { return e.name; }
  return ui.numberToString(e.number);
}

function c_answerText(e: C_Element, mode: number): string {
  if (mode === 0) { return e.name; }
  return e.symbol;
}

function c_promptText(mode: number): string {
  if (mode === 0) { return "Which element has this symbol?"; }
  if (mode === 1) { return "What is the symbol for this element?"; }
  return "Which symbol has this atomic number?";
}

function c_buildChoices(state: AppState, correct: number, seed: number): number[] {
  let out: number[] = [];
  out.push(correct);
  let s: number = seed;
  let guard: number = 0;
  while (out.length() < 4 && guard < 200) {
    s = c_nextSeed(s);
    let pick: number = s % 20;
    let dup: boolean = false;
    for (let v: number of out) {
      if (v === pick) { dup = true; }
    }
    if (!dup) { out.push(pick); }
    guard = guard + 1;
  }
  let i: number = out.length() - 1;
  while (i > 0) {
    s = c_nextSeed(s);
    let j: number = s % (i + 1);
    let tmp: number = out[i];
    out[i] = out[j];
    out[j] = tmp;
    i = i - 1;
  }
  return out;
}

function c_start(state: AppState, ignored: number): AppState {
  let total: number = state.questionCount;
  if (total < 1) { total = 1; }
  if (total > 20) { total = 20; }
  let s: number = c_nextSeed(state.c_seed + 7);
  let pool: number[] = [];
  let k: number = 0;
  while (k < 20) { pool.push(k); k = k + 1; }
  let order: number[] = [];
  let n: number = 0;
  while (n < total) {
    s = c_nextSeed(s);
    let j: number = s % pool.length();
    order.push(pool[j]);
    let rest: number[] = [];
    let m: number = 0;
    while (m < pool.length()) {
      if (m !== j) { rest.push(pool[m]); }
      m = m + 1;
    }
    pool = rest;
    n = n + 1;
  }
  let choices: number[] = c_buildChoices(state, order[0], s);
  let empty: C_Miss[] = [];
  return {c_order: order, c_choices: choices, c_index: 0, c_score: 0, c_answered: false, c_picked: -1, c_wasRight: false, c_misses: empty, c_phase: 1, c_seed: s, c_trigger: state.c_trigger + 1__PASSTHROUGH__};
}

function c_pick(state: AppState, value: number): AppState {
  if (state.c_phase !== 1 || state.c_answered) { return {__PASSTHROUGH__}; }
  let correct: number = state.c_order[state.c_index];
  let right: boolean = value === correct;
  let score: number = state.c_score;
  if (right) { score = score + 1; }
  let misses: C_Miss[] = [];
  for (let old: C_Miss of state.c_misses) { misses.push(old); }
  if (!right) {
    let e: C_Element = state.c_elements[correct];
    let given: C_Element = state.c_elements[value];
    let mode: number = state.quizModeIndex;
    misses.push({name: e.name, symbol: e.symbol, number: e.number, asked: c_askedText(e, mode), given: c_answerText(given, mode)});
  }
  return {c_score: score, c_answered: true, c_picked: value, c_wasRight: right, c_misses: misses, c_trigger: state.c_trigger + 1__PASSTHROUGH__};
}

function c_next(state: AppState, ignored: number): AppState {
  if (state.c_phase !== 1 || !state.c_answered) { return {__PASSTHROUGH__}; }
  let nextIndex: number = state.c_index + 1;
  if (nextIndex >= state.c_order.length()) {
    return {c_phase: 2, c_answered: false, c_picked: -1, c_trigger: state.c_trigger + 1__PASSTHROUGH__};
  }
  let s: number = c_nextSeed(state.c_seed + 3);
  let choices: number[] = c_buildChoices(state, state.c_order[nextIndex], s);
  return {c_index: nextIndex, c_choices: choices, c_answered: false, c_picked: -1, c_wasRight: false, c_seed: s, c_trigger: state.c_trigger + 1__PASSTHROUGH__};
}

function c_restart(state: AppState, ignored: number): AppState {
  return {c_phase: 0, c_order: [], c_choices: [], c_index: 0, c_score: 0, c_answered: false, c_picked: -1, c_wasRight: false, c_misses: [], c_trigger: state.c_trigger + 1__PASSTHROUGH__};
}
