import * as ui from "std/ui"

@jsonable
class C_Pair {
  spanish: string;
  english: string;
}

@jsonable
class AppState {
  questionCount: number;
  answerModeIndex: number;
  c_pairs: C_Pair[];
  c_order: number[];
  c_index: number;
  c_answered: boolean;
  c_lastCorrect: boolean;
  c_correctCount: number;
  c_askedCount: number;
  c_typed: string;
  c_finished: boolean;
  c_seed: number;
}

function init(): AppState {
  return {questionCount: 10, answerModeIndex: 0, c_pairs: [], c_order: [], c_index: 0, c_answered: false, c_lastCorrect: false, c_correctCount: 0, c_askedCount: 0, c_typed: "", c_finished: false, c_seed: 7};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_questionCount(state: AppState, value: number): AppState {
  return {questionCount: value, answerModeIndex: state.answerModeIndex, c_pairs: state.c_pairs, c_order: state.c_order, c_index: state.c_index, c_answered: state.c_answered, c_lastCorrect: state.c_lastCorrect, c_correctCount: state.c_correctCount, c_askedCount: state.c_askedCount, c_typed: state.c_typed, c_finished: state.c_finished, c_seed: state.c_seed};
}

function set_answerMode(state: AppState, value: number): AppState {
  return {answerModeIndex: value, questionCount: state.questionCount, c_pairs: state.c_pairs, c_order: state.c_order, c_index: state.c_index, c_answered: state.c_answered, c_lastCorrect: state.c_lastCorrect, c_correctCount: state.c_correctCount, c_askedCount: state.c_askedCount, c_typed: state.c_typed, c_finished: state.c_finished, c_seed: state.c_seed};
}







function c_buildPairs(): C_Pair[] {
  let out: C_Pair[] = [];
  out.push({spanish: "hola", english: "hello"});
  out.push({spanish: "gracias", english: "thank you"});
  out.push({spanish: "casa", english: "house"});
  out.push({spanish: "perro", english: "dog"});
  out.push({spanish: "libro", english: "book"});
  out.push({spanish: "agua", english: "water"});
  out.push({spanish: "amigo", english: "friend"});
  out.push({spanish: "escuela", english: "school"});
  out.push({spanish: "comida", english: "food"});
  out.push({spanish: "tiempo", english: "time"});
  out.push({spanish: "gato", english: "cat"});
  out.push({spanish: "mesa", english: "table"});
  out.push({spanish: "ciudad", english: "city"});
  out.push({spanish: "noche", english: "night"});
  out.push({spanish: "trabajo", english: "work"});
  out.push({spanish: "familia", english: "family"});
  out.push({spanish: "rojo", english: "red"});
  out.push({spanish: "grande", english: "big"});
  out.push({spanish: "siempre", english: "always"});
  out.push({spanish: "comer", english: "to eat"});
  return out;
}

function c_start(state: AppState, ignored: number): AppState {
  let pairs: C_Pair[] = c_buildPairs();
  let total: number = pairs.length();
  let order: number[] = [];
  let i: number = 0;
  while (i < total) {
    order.push(i);
    i = i + 1;
  }
  let seed: number = state.c_seed + 1;
  let j: number = total - 1;
  while (j > 0) {
    let r: number = math.randomBelow(seed, j + 1);
    seed = math.randomStep(seed);
    let tmp: number = order[j];
    order[j] = order[r];
    order[r] = tmp;
    j = j - 1;
  }
  return {c_pairs: pairs, c_order: order, c_index: 0, c_answered: false, c_lastCorrect: false, c_correctCount: 0, c_askedCount: 0, c_typed: "", c_finished: false, c_seed: seed, questionCount: state.questionCount, answerModeIndex: state.answerModeIndex};
}

function c_type(state: AppState, value: string): AppState {
  return {c_typed: value, questionCount: state.questionCount, answerModeIndex: state.answerModeIndex, c_pairs: state.c_pairs, c_order: state.c_order, c_index: state.c_index, c_answered: state.c_answered, c_lastCorrect: state.c_lastCorrect, c_correctCount: state.c_correctCount, c_askedCount: state.c_askedCount, c_finished: state.c_finished, c_seed: state.c_seed};
}

function c_check(state: AppState, ignored: number): AppState {
  if (state.c_finished) { return {questionCount: state.questionCount, answerModeIndex: state.answerModeIndex, c_pairs: state.c_pairs, c_order: state.c_order, c_index: state.c_index, c_answered: state.c_answered, c_lastCorrect: state.c_lastCorrect, c_correctCount: state.c_correctCount, c_askedCount: state.c_askedCount, c_typed: state.c_typed, c_finished: state.c_finished, c_seed: state.c_seed}; }
  if (state.c_answered) { return {questionCount: state.questionCount, answerModeIndex: state.answerModeIndex, c_pairs: state.c_pairs, c_order: state.c_order, c_index: state.c_index, c_answered: state.c_answered, c_lastCorrect: state.c_lastCorrect, c_correctCount: state.c_correctCount, c_askedCount: state.c_askedCount, c_typed: state.c_typed, c_finished: state.c_finished, c_seed: state.c_seed}; }
  let total: number = state.c_order.length();
  if (total === 0) { return {questionCount: state.questionCount, answerModeIndex: state.answerModeIndex, c_pairs: state.c_pairs, c_order: state.c_order, c_index: state.c_index, c_answered: state.c_answered, c_lastCorrect: state.c_lastCorrect, c_correctCount: state.c_correctCount, c_askedCount: state.c_askedCount, c_typed: state.c_typed, c_finished: state.c_finished, c_seed: state.c_seed}; }
  if (state.c_index >= total) { return {questionCount: state.questionCount, answerModeIndex: state.answerModeIndex, c_pairs: state.c_pairs, c_order: state.c_order, c_index: state.c_index, c_answered: state.c_answered, c_lastCorrect: state.c_lastCorrect, c_correctCount: state.c_correctCount, c_askedCount: state.c_askedCount, c_typed: state.c_typed, c_finished: state.c_finished, c_seed: state.c_seed}; }
  let pair: C_Pair = state.c_pairs[state.c_order[state.c_index]];
  let expected: string = pair.english;
  if (state.answerModeIndex === 1) {
    expected = pair.spanish;
  }
  let given: string = strings.toLowerCase(strings.trim(state.c_typed));
  let want: string = strings.toLowerCase(strings.trim(expected));
  let ok: boolean = given === want;
  let correct: number = state.c_correctCount;
  if (ok) { correct = correct + 1; }
  return {c_answered: true, c_lastCorrect: ok, c_correctCount: correct, c_askedCount: state.c_askedCount + 1, questionCount: state.questionCount, answerModeIndex: state.answerModeIndex, c_pairs: state.c_pairs, c_order: state.c_order, c_index: state.c_index, c_typed: state.c_typed, c_finished: state.c_finished, c_seed: state.c_seed};
}

function c_next(state: AppState, ignored: number): AppState {
  if (!state.c_answered) { return {questionCount: state.questionCount, answerModeIndex: state.answerModeIndex, c_pairs: state.c_pairs, c_order: state.c_order, c_index: state.c_index, c_answered: state.c_answered, c_lastCorrect: state.c_lastCorrect, c_correctCount: state.c_correctCount, c_askedCount: state.c_askedCount, c_typed: state.c_typed, c_finished: state.c_finished, c_seed: state.c_seed}; }
  let total: number = state.c_order.length();
  let nextIndex: number = state.c_index + 1;
  let limit: number = state.questionCount;
  if (limit > total) { limit = total; }
  if (nextIndex >= limit) {
    return {c_finished: true, c_answered: false, c_typed: "", questionCount: state.questionCount, answerModeIndex: state.answerModeIndex, c_pairs: state.c_pairs, c_order: state.c_order, c_index: state.c_index, c_lastCorrect: state.c_lastCorrect, c_correctCount: state.c_correctCount, c_askedCount: state.c_askedCount, c_seed: state.c_seed};
  }
  return {c_index: nextIndex, c_answered: false, c_typed: "", questionCount: state.questionCount, answerModeIndex: state.answerModeIndex, c_pairs: state.c_pairs, c_order: state.c_order, c_lastCorrect: state.c_lastCorrect, c_correctCount: state.c_correctCount, c_askedCount: state.c_askedCount, c_finished: state.c_finished, c_seed: state.c_seed};
}

function c_restart(state: AppState, ignored: number): AppState {
  return c_start(state, 0);
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Spanish Vocabulary Quiz", "VOCAB QUIZ", "Test yourself on common Spanish words", ""));
  {
      let questionCount: number = state.questionCount;
      let answerModeValues: number[] = [0, 1];
      let answerMode: number = answerModeValues[state.answerModeIndex];
      let pointsPerCorrect: number = 1;
    sections.push(ui.Section("content", "", "", [ui.NumberField("default", "Questions", state.questionCount, 1, 50, "set_questionCount"), ui.Select("default", "Answer with", ["Spanish", "English"], state.answerModeIndex, "set_answerMode")]));
  }
  {
  {
    let total: number = state.c_order.length();
    let limit: number = state.questionCount;
    if (limit > total) { limit = total; }
    if (total === 0) {
      sections.push(ui.Section("content", "Quiz", "", [
        ui.EmptyState("default", "Ready when you are", "Start the quiz to draw questions from the built-in word list.", "Start quiz", "c_start", "star")
      ]));
    } else if (state.c_finished) {
      sections.push(ui.Section("summary", "Result", "", [
        ui.MetricGroup("default", 2, [
          ui.NumberStat("accent", "Correct", state.c_correctCount, "", "", 1, "of " + ui.numberToString(limit), "check"),
          ui.NumberStat("default", "Asked", state.c_askedCount, "", "", 1, "", "list")
        ]),
        ui.ActionBar("end", [
          ui.Button("primary", "Play again", "c_restart", 0, true)
        ])
      ]));
    } else {
      let pair: C_Pair = state.c_pairs[state.c_order[state.c_index]];
      let prompt: string = pair.spanish;
      let hint: string = "Type the English meaning";
      if (state.answerModeIndex === 1) {
        prompt = pair.english;
        hint = "Type the Spanish word";
      }
      let feedback: ui.View[] = [];
      if (state.c_answered) {
        if (state.c_lastCorrect) {
          feedback.push(ui.InsetBanner("success", "Correct", "Well done.", "", "", "check"));
        } else {
          let answer: string = pair.english;
          if (state.answerModeIndex === 1) { answer = pair.spanish; }
          feedback.push(ui.InsetBanner("danger", "Not quite", "The answer is " + answer + ".", "", "", "close"));
        }
      }
      let controls: ui.View[] = [];
      if (!state.c_answered) {
        controls.push(ui.TextField("default", hint, state.c_typed, "c_type"));
        controls.push(ui.ActionBar("end", [
          ui.Button("primary", "Check", "c_check", 0, true)
        ]));
      } else {
        controls.push(ui.ActionBar("end", [
          ui.Button("primary", "Next", "c_next", 0, true)
        ]));
      }
      sections.push(ui.Section("hero", "Question " + ui.numberToString(state.c_index + 1) + " of " + ui.numberToString(limit), "", [
        ui.Hero("accent", "", prompt, hint, feedback),
        ui.Progress("accent", "", state.c_askedCount, limit),
        ui.Column("default", controls)
      ]));
    }
  }
  }
  return ui.AppTheme("playful", "", sections);
}

