import * as ui from "std/ui"

@jsonable
class C_Question {
  text: string;
  a: string;
  b: string;
  c: string;
  d: string;
  correct: number;
  category: string;
}

@jsonable
class AppState {
  questionCount: number;
  c_order: number[];
  c_index: number;
  c_correct: number;
  c_answered: number;
  c_picked: number;
  c_finished: boolean;
  c_started: boolean;
  c_round: number;
}

function init(): AppState {
  return {questionCount: 10, c_order: [], c_index: 0, c_correct: 0, c_answered: 0, c_picked: -1, c_finished: false, c_started: false, c_round: 0};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_questionCount(state: AppState, value: number): AppState {
  return {questionCount: value, c_order: state.c_order, c_index: state.c_index, c_correct: state.c_correct, c_answered: state.c_answered, c_picked: state.c_picked, c_finished: state.c_finished, c_started: state.c_started, c_round: state.c_round};
}







function c_bank(): C_Question[] {
  let q: C_Question[] = [];
  q.push({text: "Which band released the album \"Abbey Road\"?", a: "The Beatles", b: "The Rolling Stones", c: "The Who", d: "Pink Floyd", correct: 0, category: "Albums"});
