function c_shuffle(state: AppState, count: number): number[] {
  let bank: C_Question[] = c_bank();
  let total: number = bank.length();
  let pool: number[] = [];
  let i: number = 0;
  while (i < total) {
    pool.push(i);
    i = i + 1;
  }
  let seed: number = state.c_round * 7919 + count * 104729 + 17;
  let out: number[] = [];
  let n: number = 0;
  while (n < count && pool.length() > 0) {
    seed = math.randomStep(seed);
    let pick: number = math.randomBelow(seed, pool.length());
    let chosen: number = pool[pick];
    let kept: number[] = [];
    let j: number = 0;
    while (j < pool.length()) {
      if (j !== pick) {
        kept.push(pool[j]);
      }
      j = j + 1;
    }
    pool = kept;
    out.push(chosen);
    n = n + 1;
  }
  return out;
}

function c_start(state: AppState, ignored: number): AppState {
  let count: number = state.questionCount;
  if (count < 1) { count = 1; }
  if (count > 20) { count = 20; }
  let round: number = state.c_round + 1;
  let order: number[] = c_shuffle(state, count);
  return {c_order: order, c_index: 0, c_correct: 0, c_answered: 0, c_picked: -1, c_finished: false, c_started: true, c_round: round, questionCount: state.questionCount};
}

function c_answer(state: AppState, value: number): AppState {
  if (state.c_finished) { return {questionCount: state.questionCount, c_order: state.c_order, c_index: state.c_index, c_correct: state.c_correct, c_answered: state.c_answered, c_picked: state.c_picked, c_finished: state.c_finished, c_started: state.c_started, c_round: state.c_round}; }
  if (state.c_picked >= 0) { return {questionCount: state.questionCount, c_order: state.c_order, c_index: state.c_index, c_correct: state.c_correct, c_answered: state.c_answered, c_picked: state.c_picked, c_finished: state.c_finished, c_started: state.c_started, c_round: state.c_round}; }
  let bank: C_Question[] = c_bank();
  let pos: number = state.c_index;
  if (pos < 0 || pos >= state.c_order.length()) { return {questionCount: state.questionCount, c_order: state.c_order, c_index: state.c_index, c_correct: state.c_correct, c_answered: state.c_answered, c_picked: state.c_picked, c_finished: state.c_finished, c_started: state.c_started, c_round: state.c_round}; }
  let qi: number = state.c_order[pos];
  let q: C_Question = bank[qi];
  let correct: number = state.c_correct;
  if (value === q.correct) {
    correct = correct + 1;
  }
  return {c_picked: value, c_correct: correct, c_answered: state.c_answered + 1, questionCount: state.questionCount, c_order: state.c_order, c_index: state.c_index, c_finished: state.c_finished, c_started: state.c_started, c_round: state.c_round};
}

function c_next(state: AppState, ignored: number): AppState {
  if (state.c_picked < 0) { return {questionCount: state.questionCount, c_order: state.c_order, c_index: state.c_index, c_correct: state.c_correct, c_answered: state.c_answered, c_picked: state.c_picked, c_finished: state.c_finished, c_started: state.c_started, c_round: state.c_round}; }
  let nextIndex: number = state.c_index + 1;
  if (nextIndex >= state.c_order.length()) {
