function c_start(state: AppState, ignored: number): AppState {
  let order: number[] = [];
  let i: number = 0;
  while (i < 50) {
    order.push(i);
    i = i + 1;
  }
  let seed: number = state.c_quizSeed;
  let j: number = 49;
  while (j > 0) {
    seed = math.randomStep(seed);
    let k: number = math.randomBelow(seed, j + 1);
    let tmp: number = order[j];
    order[j] = order[k];
    order[k] = tmp;
    j = j - 1;
  }
  return {c_quizActive: true, c_quizIndex: 0, c_quizCorrect: 0, c_quizAnswered: false, c_quizPicked: 0, c_quizSeed: seed, c_quizOrder: order, c_quizDone: false, questionCount: state.questionCount, c_quizBuzz: state.c_quizBuzz};
}

function c_answer(state: AppState, value: number): AppState {
  if (state.c_quizAnswered === true) {
    return {questionCount: state.questionCount, c_quizActive: state.c_quizActive, c_quizIndex: state.c_quizIndex, c_quizCorrect: state.c_quizCorrect, c_quizAnswered: state.c_quizAnswered, c_quizPicked: state.c_quizPicked, c_quizSeed: state.c_quizSeed, c_quizOrder: state.c_quizOrder, c_quizDone: state.c_quizDone, c_quizBuzz: state.c_quizBuzz};
  }
  let correct: number = 0;
  let buzz: number = state.c_quizBuzz;
  if (value === state.c_quizOrder[state.c_quizIndex]) {
    correct = state.c_quizCorrect + 1;
  } else {
    correct = state.c_quizCorrect;
    buzz = state.c_quizBuzz + 1;
    sdk.call("sdk.vibrate", ["duration", "200"], "onVibrate");
  }
  return {c_quizAnswered: true, c_quizPicked: value, c_quizCorrect: correct, questionCount: state.questionCount, c_quizActive: state.c_quizActive, c_quizIndex: state.c_quizIndex, c_quizSeed: state.c_quizSeed, c_quizOrder: state.c_quizOrder, c_quizDone: state.c_quizDone, c_quizBuzz: buzz};
}

