  if (nextIndex >= state.questionCount) {
    return {c_quizDone: true, c_quizAnswered: false, questionCount: state.questionCount, c_quizActive: state.c_quizActive, c_quizIndex: state.c_quizIndex, c_quizCorrect: state.c_quizCorrect, c_quizPicked: state.c_quizPicked, c_quizSeed: state.c_quizSeed, c_quizOrder: state.c_quizOrder, c_quizBuzz: state.c_quizBuzz};
  }
  return {c_quizIndex: nextIndex, c_quizAnswered: false, c_quizPicked: 0, questionCount: state.questionCount, c_quizActive: state.c_quizActive, c_quizCorrect: state.c_quizCorrect, c_quizSeed: state.c_quizSeed, c_quizOrder: state.c_quizOrder, c_quizDone: state.c_quizDone, c_quizBuzz: state.c_quizBuzz};
