}

function c_option(state: AppState, slot: number): number {
  let correctIdx: number = state.c_quizOrder[state.c_quizIndex];
  if (slot === 0) { return correctIdx; }
  let offset: number = slot;
  let candidate: number = correctIdx + offset;
  if (candidate >= 50) { candidate = candidate - 50; }
  return candidate;
}

