  c_index: number;
  c_score: number;
  c_answered: boolean;
  c_picked: number;
  c_finished: boolean;
  c_round: number;
}

function init(): AppState {
  return {questionCount: 10, c_questions: [], c_index: 0, c_score: 0, c_answered: false, c_picked: 0, c_finished: false, c_round: 0};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_questionCount(state: AppState, value: number): AppState {
  return {questionCount: value, c_questions: state.c_questions, c_index: state.c_index, c_score: state.c_score, c_answered: state.c_answered, c_picked: state.c_picked, c_finished: state.c_finished, c_round: state.c_round};
}







