function c_start(state: AppState, ignored: number): AppState {
  let all: C_Question[] = c_buildQuestions();
  let picked: C_Question[] = [];
  let n: number = state.questionCount;
  if (n > all.length()) { n = all.length(); }
  let i: number = 0;
  while (i < n) {
    picked.push(all[i]);
    i = i + 1;
  }
  return {c_questions: picked, c_index: 0, c_score: 0, c_answered: false, c_picked: 0, c_finished: false, c_round: state.c_round + 1, questionCount: state.questionCount};
}

function c_answer(state: AppState, value: number): AppState {
  if (state.c_answered || state.c_finished) {
    return {questionCount: state.questionCount, c_questions: state.c_questions, c_index: state.c_index, c_score: state.c_score, c_answered: state.c_answered, c_picked: state.c_picked, c_finished: state.c_finished, c_round: state.c_round};
  }
  let q: C_Question = state.c_questions[state.c_index];
  let gained: number = 0;
  if (value === q.correct) { gained = 1; }
  return {c_answered: true, c_picked: value, c_score: state.c_score + gained, questionCount: state.questionCount, c_questions: state.c_questions, c_index: state.c_index, c_finished: state.c_finished, c_round: state.c_round};
}

function c_next(state: AppState, ignored: number): AppState {
  if (!state.c_answered) {
    return {questionCount: state.questionCount, c_questions: state.c_questions, c_index: state.c_index, c_score: state.c_score, c_answered: state.c_answered, c_picked: state.c_picked, c_finished: state.c_finished, c_round: state.c_round};
  }
  let nextIndex: number = state.c_index + 1;
  if (nextIndex >= state.c_questions.length()) {
    return {c_finished: true, c_answered: false, questionCount: state.questionCount, c_questions: state.c_questions, c_index: state.c_index, c_score: state.c_score, c_picked: state.c_picked, c_round: state.c_round};
  }
  return {c_index: nextIndex, c_answered: false, c_picked: 0, questionCount: state.questionCount, c_questions: state.c_questions, c_score: state.c_score, c_finished: state.c_finished, c_round: state.c_round};
}

function c_restart(state: AppState, ignored: number): AppState {
  return c_start(state, 0);
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Famous Inventions Quiz", "INVENTIONS QUIZ", "Guess who invented these famous things", ""));
  {
      let questionCount: number = state.questionCount;
      let pointsPerCorrect: number = 1;
    sections.push(ui.Section("content", "", "", [ui.NumberField("default", "Questions", state.questionCount, 1, 20, "set_questionCount")]));
  }
  {
  {
    let total: number = state.c_questions.length();
    let started: boolean = total > 0 && !state.c_finished;
    let rows: ui.View[] = [];
    if (started) {
      let q: C_Question = state.c_questions[state.c_index];
      rows.push(ui.SectionHeader("default", "Question " + ui.numberToString(state.c_index + 1) + " of " + ui.numberToString(total), "Who invented " + q.invention + "?", ""));
      let opts: ui.View[] = [];
      let k: number = 0;
      while (k < q.choices.length()) {
        let style: string = "default";
        if (state.c_answered) {
          if (k === q.correct) { style = "success"; }
          else if (k === state.c_picked) { style = "danger"; }
        }
        opts.push(ui.Cell(style, q.choices[k], "c_answer", k, !state.c_answered));
        k = k + 1;
      }
      rows.push(ui.Grid("default", 2, opts));
      if (state.c_answered) {
        let verdict: string = "Not quite.";
        if (state.c_picked === q.correct) { verdict = "Correct!"; }
        rows.push(ui.InsetBanner("default", verdict, "The answer is " + q.choices[q.correct] + ".", "", "", ""));
        rows.push(ui.ActionBar("end", [ui.Button("primary", "Next question", "c_next", 0, true)]));
      }
    }
    if (state.c_finished) {
      rows.push(ui.InsetBanner("success", "Quiz complete", "You scored " + ui.numberToString(state.c_score) + " out of " + ui.numberToString(total) + ".", "", "", "star"));
      rows.push(ui.ActionBar("end", [ui.Button("primary", "Play again", "c_restart", 0, true)]));
    }
    if (!started && !state.c_finished) {
      rows.push(ui.EmptyState("default", "Ready to play", "Set how many questions you want, then start the quiz.", "Start quiz", "c_start", "star"));
    }
    sections.push(ui.Section("content", "Inventions Quiz", "", [
      ui.MetricGroup("default", 2, [
        ui.NumberStat("accent", "Score", state.c_score, "", "", 1, "correct answers", "star"),
        ui.NumberStat("default", "Questions", state.questionCount, "", "", 1, "in this quiz", "list")
      ]),
      ui.Column("default", rows)
    ]));
  }
  }
  return ui.AppTheme("playful", "", sections);
}

