}

function tapGoal7(state: AppState): number {
  let n: number = strings.toNumber(state.goalText7, 0);
  if (n < 0) { n = 0; }
  return n;
}

function logTap7(state: AppState, amount: number): AppState {
  let out: Tap[] = [];
  for (let t: Tap of state.taps7) { out.push(t); }
  out.push({amount: amount, day: time.daysSinceEpoch(), minute: time.hourOfDay() * 60 + time.minuteOfHour()});
  return {taps7: out, presets7: state.presets7, amountText7: state.amountText7, goalText7: state.goalText7};
}

