  if (index < 0 || index >= state.taps7.length()) { return state; }
  let out: Tap[] = [];
  let i: number = 0;
  while (i < state.taps7.length()) {
    if (i !== index) { out.push(state.taps7[i]); }
    i = i + 1;
  }
  return {taps7: out, presets7: state.presets7, amountText7: state.amountText7, goalText7: state.goalText7};
}

