@jsonable
class AppState {
  flatmates: number;
  slotLengthIndex: number;
  startTime: number;
  settingsOpen: boolean;
}

function init(): AppState {
  return {flatmates: 4, slotLengthIndex: 1, startTime: 480, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_flatmates(state: AppState, value: number): AppState {
  return {flatmates: value, slotLengthIndex: state.slotLengthIndex, startTime: state.startTime, settingsOpen: state.settingsOpen};
}

