  return {slotLengthIndex: value, flatmates: state.flatmates, startTime: state.startTime, settingsOpen: state.settingsOpen};
}

function set_startTime(state: AppState, value: number): AppState {
  return {startTime: value, flatmates: state.flatmates, slotLengthIndex: state.slotLengthIndex, settingsOpen: state.settingsOpen};
}







