      let cycleLength: number = slotLength * slotsPerDay;
      let slotsPerPerson: number = share(slotsPerDay, flatmates);
    sections.push(ui.Section("content", "", "", [ui.Select("default", "Slot length", ["1 hour", "1.5 hours", "2 hours", "3 hours"], state.slotLengthIndex, "set_slotLength")]));
