import * as ui from "std/ui"

@jsonable
class LogEntry {
  driver: string;
  distance: number;
  minute: number;
}

@jsonable
class AppState {
  driverCount: number;
  entries: LogEntry[];
  draft_driver: string;
  draft_distance: string;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {driverCount: 3, entries: emptyEntries, draft_driver: "", draft_distance: "", removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_driverCount(state: AppState, value: number): AppState {
  return {driverCount: value, entries: state.entries, draft_driver: state.draft_driver, draft_distance: state.draft_distance, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_driver(state: AppState, value: string): AppState {
  return {draft_driver: value, driverCount: state.driverCount, entries: state.entries, draft_distance: state.draft_distance, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_distance(state: AppState, value: string): AppState {
  return {draft_distance: value, driverCount: state.driverCount, entries: state.entries, draft_driver: state.draft_driver, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_driver) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {driver: strings.trim(state.draft_driver), distance: strings.toNumber(state.draft_distance, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_driver: "", draft_distance: "", driverCount: state.driverCount, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, driverCount: state.driverCount, draft_driver: state.draft_driver, draft_distance: state.draft_distance, settingsOpen: state.settingsOpen};
}

