  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, driverCount: state.driverCount, draft_driver: state.draft_driver, draft_distance: state.draft_distance, settingsOpen: state.settingsOpen};
}

