  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, driverCount: state.driverCount, entries: state.entries, draft_driver: state.draft_driver, draft_distance: state.draft_distance, settingsOpen: state.settingsOpen};
}





function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, driverCount: state.driverCount, entries: state.entries, draft_driver: state.draft_driver, draft_distance: state.draft_distance, removedEntries: state.removedEntries, removedAt: state.removedAt};
