import * as ui from "std/ui"

@jsonable
class LogEntry {
  who: string;
  minutes: number;
  minute: number;
}

@jsonable
class AppState {
  people: number;
  entries: LogEntry[];
  draft_who: string;
  draft_minutes: string;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {people: 3, entries: emptyEntries, draft_who: "", draft_minutes: "", removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_people(state: AppState, value: number): AppState {
  return {people: value, entries: state.entries, draft_who: state.draft_who, draft_minutes: state.draft_minutes, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_who(state: AppState, value: string): AppState {
  return {draft_who: value, people: state.people, entries: state.entries, draft_minutes: state.draft_minutes, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_minutes(state: AppState, value: string): AppState {
  return {draft_minutes: value, people: state.people, entries: state.entries, draft_who: state.draft_who, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_who) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {who: strings.trim(state.draft_who), minutes: strings.toNumber(state.draft_minutes, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_who: "", draft_minutes: "", people: state.people, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, people: state.people, draft_who: state.draft_who, draft_minutes: state.draft_minutes, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, people: state.people, draft_who: state.draft_who, draft_minutes: state.draft_minutes, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, people: state.people, entries: state.entries, draft_who: state.draft_who, draft_minutes: state.draft_minutes, settingsOpen: state.settingsOpen};
}





function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, people: state.people, entries: state.entries, draft_who: state.draft_who, draft_minutes: state.draft_minutes, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Bathroom Turns", "CHORE TRACKER", "Log each bathroom cleaning turn and see who's up next", ""));
  {
