      for (let e: LogEntry of state.entries) { entryTotal = entryTotal + e.minutes; }
      let turnsDone: number = entryCount;
      let totalMinutes: number = entryTotal;
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 2, [ui.NumberStat("default", "Turns done", turnsDone, "", "", 1, "", "chart", 0), ui.NumberStat("default", "Total minutes", totalMinutes, "", " min", 1, "", "chart", 0)])]));
    let rows: ui.View[] = [];
    let i: number = entryCount - 1;
    while (i >= 0 && i > entryCount - 21) {
      let e: LogEntry = state.entries[i];
      let sub: string = "Added " + ui.clockToString(e.minute);
      rows.push(ui.ListItem("default", e.who, sub, ui.formatNumber(e.minutes, 0) + " min", "", 0, false, ""));
      rows.push(ui.ActionBar("end", [ui.Button("secondary", "Remove", "removeEntry", i, true)]));
      i = i - 1;
    }
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Who cleaned", state.draft_who, "set_draft_who"), ui.TextField("default", "Minutes spent", state.draft_minutes, "set_draft_minutes", "number"), ui.ActionBar("end", [ui.Button("primary", "Add", "addEntry", 0, strings.trim(state.draft_who) !== "")])]));
    sections.push(ui.Section("content", "", "", [ui.SectionHeader("default", "Cleaning turns", "Newest first", ui.numberToString(entryCount)), ui.When(entryCount === 0, ui.EmptyState("default", "Nothing added yet", "Fill in the fields above and tap Add.", "", "", "list")), ui.When(entryCount > 0, ui.ListGroup("default", "", rows)), ui.When(state.removedEntries.length() > 0, ui.Snackbar("default", "Removed", "Undo", "undoRemove")), ui.Ticker("default", "undoClock", 6000 + state.entries.length() % 7, state.removedEntries.length() > 0, "expireUndo")]));
