  out.push({name: name, dueDay: state.draftDue7, lifeDays: life});
  let today: number = time.daysSinceEpoch();
  return {items7: out, today7: today, soon7: state.soon7, draftName7: "", draftDue7: today, draftLife7: ""};
}

function renew7(state: AppState, index: number): AppState {
  let today: number = time.daysSinceEpoch();
  let out: DueItem[] = [];
  let i: number = 0;
  while (i < state.items7.length()) {
    let it: DueItem = state.items7[i];
    if (i === index && it.lifeDays > 0) { out.push({name: it.name, dueDay: today + it.lifeDays, lifeDays: it.lifeDays}); }
    else { out.push(it); }
    i = i + 1;
  }
  return withItems7(state, out);
}

function removeItem7(state: AppState, index: number): AppState {
  let out: DueItem[] = [];
  let i: number = 0;
  while (i < state.items7.length()) {
    if (i !== index) { out.push(state.items7[i]); }
    i = i + 1;
  }
  return withItems7(state, out);
}

function refreshToday7(state: AppState, elapsedMs: number): AppState {
  let today: number = time.daysSinceEpoch();
  if (today === state.today7) { return state; }
  return {items7: state.items7, today7: today, soon7: state.soon7, draftName7: state.draftName7, draftDue7: state.draftDue7, draftLife7: state.draftLife7};
}

function sorted7(state: AppState): number[] {
  let order: number[] = [];
  let i: number = 0;
  while (i < state.items7.length()) {
    let at: number = order.length();
    let j: number = 0;
    while (j < order.length()) {
      if (state.items7[i].dueDay < state.items7[order[j]].dueDay) { at = j; break; }
      j = j + 1;
    }
    let next: number[] = [];
    let k: number = 0;
    while (k < order.length()) {
      if (k === at) { next.push(i); }
      next.push(order[k]);
      k = k + 1;
    }
    if (at === order.length()) { next.push(i); }
    order = next;
    i = i + 1;
  }
  return order;
}

function expiredCount7(state: AppState): number {
