import * as ui from "std/ui"

@jsonable
class AppState {
  lastWorkout: number;
}

function init(): AppState {
  return {lastWorkout: 420};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_lastWorkout(state: AppState, value: number): AppState {
  return {lastWorkout: value};
}







function c_nowMinutes(state: AppState): number {
  return time.hourOfDay() * 60 + time.minuteOfHour();
}

function c_sinceMinutes(state: AppState): number {
  let now: number = c_nowMinutes(state);
  let diff: number = now - state.lastWorkout;
  if (diff < 0) {
    diff = diff + 1440;
  }
  return diff;
}

function c_sinceText(state: AppState): string {
  let total: number = c_sinceMinutes(state);
  let hours: number = math.floor(total / 60);
  let mins: number = total % 60;
  if (hours > 0) {
    return ui.numberToString(hours) + " h " + ui.numberToString(mins) + " min";
  }
  return ui.numberToString(mins) + " min";
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Time Since Last Workout", "WORKOUT GAP", "See how long it has been since your last session.", ""));
  {
      let lastWorkout: number = state.lastWorkout;
    sections.push(ui.Section("content", "", "", [ui.TimeField("default", "Last workout", state.lastWorkout, "set_lastWorkout")]));
  }
  {
  sections.push(ui.Section("summary", "Time since", "From your last workout to now", [
    ui.MetricGroup("default", 2, [
      ui.NumberStat("accent", "Time since", c_sinceMinutes(state), "", " min", 1, c_sinceText(state), "clock"),
      ui.NumberStat("default", "Last workout", state.lastWorkout, "", "", 1, ui.clockToString(state.lastWorkout), "calendar")
    ])
  ]));
  }
  return ui.AppTheme("technical", "", sections);
}

