import * as ui from "std/ui"

@jsonable
class AppState {
  lastSnackTime: number;
  c_nowMinute: number;
}

function init(): AppState {
  return {lastSnackTime: 720, c_nowMinute: 0};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_lastSnackTime(state: AppState, value: number): AppState {
  return {lastSnackTime: value, c_nowMinute: state.c_nowMinute};
}







function c_tick(state: AppState, elapsedMs: number): AppState {
  return {c_nowMinute: time.hourOfDay() * 60 + time.minuteOfHour(), lastSnackTime: state.lastSnackTime};
}

function c_elapsedMinutes(state: AppState): number {
  let now: number = state.c_nowMinute;
  if (now === 0) {
    now = time.hourOfDay() * 60 + time.minuteOfHour();
  }
  let diff: number = now - state.lastSnackTime;
  if (diff < 0) {
    diff = diff + 1440;
  }
  return diff;
}

function c_hours(state: AppState): number {
  return c_elapsedMinutes(state) / 60;
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Snack Clock", "SNACK TIMER", "See how long it's been since the last snack", ""));
  {
      let lastSnackTime: number = state.lastSnackTime;
    sections.push(ui.Section("content", "", "", [ui.TimeField("default", "Last snack time", state.lastSnackTime, "set_lastSnackTime")]));
  }
  {
  let c_now: number = state.c_nowMinute;
  if (c_now === 0) {
    c_now = time.hourOfDay() * 60 + time.minuteOfHour();
  }
  let c_diff: number = c_now - state.lastSnackTime;
  if (c_diff < 0) {
    c_diff = c_diff + 1440;
  }
  let c_hoursShown: number = c_diff / 60;
  sections.push(ui.Section("summary", "Hours since snack", "", [
    ui.MetricGroup("default", 1, [
      ui.NumberStat("accent", "Hours since snack", c_hoursShown, "", " h", 1, "since " + ui.clockToString(state.lastSnackTime), "clock")
    ]),
    ui.Ticker("default", "c_snackClock", 30000, true, "c_tick")
  ]));
  }
  return ui.AppTheme("technical", "", sections);
}

