  if (b === 0) { return 0; }
  return a / b;
}



function set_lastSnackTime(state: AppState, value: number): AppState {
  return {lastSnackTime: value, c_nowMinute: state.c_nowMinute};
}







function c_tick(state: AppState, elapsedMs: number): AppState {
  return {c_nowMinute: time.hourOfDay() * 60 + time.minuteOfHour(), lastSnackTime: state.lastSnackTime};
}

function c_elapsedMinutes(state: AppState): number {
  let now: number = state.c_nowMinute;
  if (now === 0) {
    now = time.hourOfDay() * 60 + time.minuteOfHour();
  }
  let diff: number = now - state.lastSnackTime;
  if (diff < 0) {
    diff = diff + 1440;
  }
  return diff;
}

function c_hours(state: AppState): number {
  return c_elapsedMinutes(state) / 60;
}

