}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_bowlerName) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {bowlerName: strings.trim(state.draft_bowlerName), game1: strings.toNumber(state.draft_game1, 0), game2: strings.toNumber(state.draft_game2, 0), game3: strings.toNumber(state.draft_game3, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_bowlerName: "", draft_game1: "", draft_game2: "", draft_game3: "", bowlerCount: state.bowlerCount, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
