  }
  return {entries: out, removedEntries: gone, removedAt: value, bowlerCount: state.bowlerCount, draft_bowlerName: state.draft_bowlerName, draft_game1: state.draft_game1, draft_game2: state.draft_game2, draft_game3: state.draft_game3, settingsOpen: state.settingsOpen};
