  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, bowlerCount: state.bowlerCount, draft_bowlerName: state.draft_bowlerName, draft_game1: state.draft_game1, draft_game2: state.draft_game2, draft_game3: state.draft_game3, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, bowlerCount: state.bowlerCount, entries: state.entries, draft_bowlerName: state.draft_bowlerName, draft_game1: state.draft_game1, draft_game2: state.draft_game2, draft_game3: state.draft_game3, settingsOpen: state.settingsOpen};
}





