}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_startingScore(state: AppState, value: number): AppState {
  return {startingScoreIndex: value, doubleOut: state.doubleOut, entries: state.entries, draft_player: state.draft_player, draft_points: state.draft_points, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
