    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, startingScoreIndex: state.startingScoreIndex, doubleOut: state.doubleOut, draft_player: state.draft_player, draft_points: state.draft_points, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
