import * as ui from "std/ui"

@jsonable
class LogEntry {
  runs: number;
  wicket: boolean;
  minute: number;
}

@jsonable
class AppState {
  oversTotal: number;
  entries: LogEntry[];
  draft_runs: string;
  draft_wicket: boolean;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {oversTotal: 20, entries: emptyEntries, draft_runs: "", draft_wicket: false, removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_oversTotal(state: AppState, value: number): AppState {
  return {oversTotal: value, entries: state.entries, draft_runs: state.draft_runs, draft_wicket: state.draft_wicket, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_runs(state: AppState, value: string): AppState {
  return {draft_runs: value, oversTotal: state.oversTotal, entries: state.entries, draft_wicket: state.draft_wicket, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_wicket(state: AppState, value: boolean): AppState {
  return {draft_wicket: value, oversTotal: state.oversTotal, entries: state.entries, draft_runs: state.draft_runs, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_runs) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {runs: strings.toNumber(state.draft_runs, 0), wicket: state.draft_wicket, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_runs: "", oversTotal: state.oversTotal, draft_wicket: state.draft_wicket, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, oversTotal: state.oversTotal, draft_runs: state.draft_runs, draft_wicket: state.draft_wicket, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, oversTotal: state.oversTotal, draft_runs: state.draft_runs, draft_wicket: state.draft_wicket, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, oversTotal: state.oversTotal, entries: state.entries, draft_runs: state.draft_runs, draft_wicket: state.draft_wicket, settingsOpen: state.settingsOpen};
}





function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, oversTotal: state.oversTotal, entries: state.entries, draft_runs: state.draft_runs, draft_wicket: state.draft_wicket, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

