  sections.push(ui.Header("default", "Cricket Tracker", "RUNS & WICKETS", "Log every run and wicket as it happens", ""));
  {
      let oversTotal: number = state.oversTotal;
      let ballsPerOver: number = 6;
      let entryCount: number = state.entries.length();
      let entryTotal: number = 0;
      for (let e: LogEntry of state.entries) { entryTotal = entryTotal + e.runs; }
      let ballsBowled: number = ballsPerOver * entryCount;
      let oversBowled: number = (math.floor(share(ballsBowled, ballsPerOver)) + share((ballsBowled % ballsPerOver), 10));
      let runsTotal: number = entryTotal;
