      let oversLeft: number = (oversTotal - oversBowled);
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 3, [ui.NumberStat("default", "Overs bowled", oversBowled, "", " overs", 1, "", "chart", 1), ui.NumberStat("default", "Runs", runsTotal, "", " runs", 1, "", "chart", 0), ui.NumberStat("default", "Run rate", runRate, "", " runs/over", 1, "", "chart", 2), ui.NumberStat("default", "Overs left", oversLeft, "", " overs", 1, "", "chart", 1)])]));
