  targetTime: number;
  entries: LogEntry[];
  draft_wakeTime: number;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {targetTime: 390, entries: emptyEntries, draft_wakeTime: 390, removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_targetTime(state: AppState, value: number): AppState {
  return {targetTime: value, entries: state.entries, draft_wakeTime: state.draft_wakeTime, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_wakeTime(state: AppState, value: number): AppState {
  return {draft_wakeTime: value, targetTime: state.targetTime, entries: state.entries, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  let none: LogEntry[] = [];
  let entry: LogEntry = {wakeTime: state.draft_wakeTime, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, targetTime: state.targetTime, draft_wakeTime: state.draft_wakeTime, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, targetTime: state.targetTime, draft_wakeTime: state.draft_wakeTime, settingsOpen: state.settingsOpen};
}

