  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, targetTime: state.targetTime, draft_wakeTime: state.draft_wakeTime, settingsOpen: state.settingsOpen};
