import * as ui from "std/ui"

@jsonable
class LogEntry {
  wakeTime: number;
  minute: number;
}

@jsonable
class AppState {
  targetTime: number;
  entries: LogEntry[];
  draft_wakeTime: number;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {targetTime: 390, entries: emptyEntries, draft_wakeTime: 390, removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_targetTime(state: AppState, value: number): AppState {
  return {targetTime: value, entries: state.entries, draft_wakeTime: state.draft_wakeTime, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_wakeTime(state: AppState, value: number): AppState {
  return {draft_wakeTime: value, targetTime: state.targetTime, entries: state.entries, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  let none: LogEntry[] = [];
  let entry: LogEntry = {wakeTime: state.draft_wakeTime, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, targetTime: state.targetTime, draft_wakeTime: state.draft_wakeTime, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, targetTime: state.targetTime, draft_wakeTime: state.draft_wakeTime, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, targetTime: state.targetTime, draft_wakeTime: state.draft_wakeTime, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, targetTime: state.targetTime, entries: state.entries, draft_wakeTime: state.draft_wakeTime, settingsOpen: state.settingsOpen};
}





function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, targetTime: state.targetTime, entries: state.entries, draft_wakeTime: state.draft_wakeTime, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Early Wake Streak", "STREAK", "Log each early wake-up and keep your streak alive", ""));
  {
      let targetTime: number = state.targetTime;
      let entryCount: number = state.entries.length();
      let entryTotal: number = 0;
    let rows: ui.View[] = [];
    let i: number = entryCount - 1;
    while (i >= 0 && i > entryCount - 21) {
      let e: LogEntry = state.entries[i];
      let sub: string = "Added " + ui.clockToString(e.minute);
      rows.push(ui.ListItem("default", "#" + ui.numberToString(i + 1), sub, ui.clockToString(e.wakeTime), "", 0, false, ""));
      rows.push(ui.ActionBar("end", [ui.Button("secondary", "Remove", "removeEntry", i, true)]));
      i = i - 1;
    }
    sections.push(ui.Section("content", "", "", [ui.TimeField("default", "Woke at", state.draft_wakeTime, "set_draft_wakeTime"), ui.ActionBar("end", [ui.Button("primary", "Add", "addEntry", 0, true)])]));
    sections.push(ui.Section("content", "", "", [ui.SectionHeader("default", "Wake-ups", "Newest first", ui.numberToString(entryCount)), ui.When(entryCount === 0, ui.EmptyState("default", "Nothing added yet", "Fill in the fields above and tap Add.", "", "", "list")), ui.When(entryCount > 0, ui.ListGroup("default", "", rows)), ui.When(state.removedEntries.length() > 0, ui.Snackbar("default", "Removed", "Undo", "undoRemove")), ui.Ticker("default", "undoClock", 6000 + state.entries.length() % 7, state.removedEntries.length() > 0, "expireUndo")]));
  }
  {
    let settingsWord: string = "Show";
