  sections.push(ui.Header("default", "Password Strength", "SECURITY CHECK", "See how strong your password is as you type", ""));
  {
      let minLength: number = 12;
      let maxScore: number = 100;
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Password", state.password, "set_password")]));
  }
  {
  {
    let c_pw: string = state.password;
    let c_len: number = strings.length(c_pw);
    let c_minLength: number = 12;
    let c_maxScore: number = 100;
    let c_lower: number = c_hasLower(c_pw);
    let c_upper: number = c_hasUpper(c_pw);
    let c_digit: number = c_hasDigit(c_pw);
    let c_symbol: number = c_hasSymbol(c_pw);
    let c_variety: number = c_lower + c_upper + c_digit + c_symbol;
    let c_lenScore: number = c_lengthScore(c_len);
    let c_lenBonus: number = c_lengthBonus(c_len, c_minLength);
    let c_varScore: number = c_varietyScore(c_variety);
    let c_score: number = c_strengthScore(c_len, c_variety, c_minLength, c_maxScore);
    let c_frac: number = share(c_score, c_maxScore);
    let c_tone: string = "danger";
    if (c_score >= 80) {
      c_tone = "success";
    } else if (c_score >= 50) {
      c_tone = "warning";
    }
    sections.push(ui.Section("summary", "Strength", "Scored out of " + ui.numberToString(c_maxScore), [
      ui.MetricGroup("default", 2, [
        ui.NumberStat(c_tone, "Strength score", c_score, "", "", 1, "of " + ui.numberToString(c_maxScore), "star"),
        ui.NumberStat("default", "Length", c_len, "", "", 1, "characters", "list")
      ]),
