import * as ui from "std/ui"

@jsonable
class C_WordCount {
  word: string;
  count: number;
}

@jsonable
class AppState {
  text: string;
  c_topCount: number;
  c_analyzed: boolean;
  c_words: C_WordCount[];
  c_totalWords: number;
  c_uniqueWords: number;
}

function init(): AppState {
  return {text: "", c_topCount: 10, c_analyzed: false, c_words: [], c_totalWords: 0, c_uniqueWords: 0};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_text(state: AppState, value: string): AppState {
  return {text: value, c_topCount: state.c_topCount, c_analyzed: state.c_analyzed, c_words: state.c_words, c_totalWords: state.c_totalWords, c_uniqueWords: state.c_uniqueWords};
}







function c_isLetter(ch: string): boolean {
  let lower: string = strings.toLowerCase(ch);
  if (lower.length() !== 1) { return false; }
  if (lower >= "a" && lower <= "z") { return true; }
  return false;
}

function c_analyze(state: AppState, ignored: number): AppState {
  let raw: string = strings.toLowerCase(state.text);
  let words: string[] = [];
  let current: string = "";
  for (let ch: string of raw) {
    if (c_isLetter(ch)) {
      current = current + ch;
    } else {
      if (current.length() > 0) {
        words.push(current);
        current = "";
      }
    }
  }
  if (current.length() > 0) {
    words.push(current);
  }

  let found: C_WordCount[] = [];
  for (let w: string of words) {
    let idx: number = -1;
    let i: number = 0;
    while (i < found.length()) {
      if (found[i].word === w) {
        idx = i;
        i = found.length();
      } else {
        i = i + 1;
      }
    }
    if (idx >= 0) {
      let rec: C_WordCount = found[idx];
      rec.count = rec.count + 1;
      found[idx] = rec;
    } else {
      found.push({word: w, count: 1});
    }
  }

  let sorted: C_WordCount[] = [];
  let remaining: C_WordCount[] = [];
  for (let f: C_WordCount of found) {
    remaining.push(f);
  }
  while (remaining.length() > 0) {
    let bestIdx: number = 0;
    let j: number = 1;
    while (j < remaining.length()) {
      let a: C_WordCount = remaining[j];
      let b: C_WordCount = remaining[bestIdx];
      if (a.count > b.count) {
        bestIdx = j;
      } else if (a.count === b.count && a.word < b.word) {
        bestIdx = j;
      }
      j = j + 1;
    }
    let picked: C_WordCount = remaining[bestIdx];
    sorted.push(picked);
    let rest: C_WordCount[] = [];
    let k: number = 0;
    while (k < remaining.length()) {
      if (k !== bestIdx) {
        rest.push(remaining[k]);
      }
      k = k + 1;
    }
    remaining = rest;
  }

  return {
    c_topCount: state.c_topCount,
    c_analyzed: true,
    c_words: sorted,
    c_totalWords: words.length(),
    c_uniqueWords: found.length()
    , text: state.text
  };
}

function c_setTop(state: AppState, value: number): AppState {
  return {c_topCount: value, text: state.text, c_analyzed: state.c_analyzed, c_words: state.c_words, c_totalWords: state.c_totalWords, c_uniqueWords: state.c_uniqueWords};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Common Words", "WORD COUNTER", "Paste text and see the words that repeat most", ""));
  {
      let topCount: number = 10;
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Text", state.text, "set_text")]));
  }
  {
  {
    let rows: ui.View[] = [];
    let shown: number = 0;
    let i: number = 0;
    while (i < state.c_words.length() && shown < state.c_topCount) {
      let w: C_WordCount = state.c_words[i];
      rows.push(ui.NumberListItem("default", w.word, "", w.count, "", "", 1, "", 0, false, ""));
      shown = shown + 1;
      i = i + 1;
    }

    let body: ui.View[] = [];
    body.push(ui.NumberField("default", "Top words to show", state.c_topCount, 1, 50, "c_setTop"));
    body.push(ui.ActionBar("end", [
      ui.Button("primary", "Count words", "c_analyze", 0, true)
    ]));

    if (state.c_analyzed) {
      if (state.c_totalWords === 0) {
        body.push(ui.InsetBanner("warning", "No words found", "The text has no letters to count yet.", "", "", "info"));
      } else {
        body.push(ui.MetricGroup("default", 2, [
          ui.NumberStat("default", "Words", state.c_totalWords, "", "", 1, "", "list"),
          ui.NumberStat("accent", "Unique", state.c_uniqueWords, "", "", 1, "", "chart")
        ]));
        body.push(ui.SectionHeader("default", "Most common", "Most frequent first", ui.numberToString(shown)));
        body.push(ui.ListGroup("default", "", rows));
      }
    }

    sections.push(ui.Section("content", "Word frequency", "Case and punctuation ignored", body));
  }
  }
  return ui.AppTheme("technical", "", sections);
}

