import * as ui from "std/ui"

@jsonable
class AppState {
  email: string;
  result: string;
}

function init(): AppState {
  return {email: "", result: ""};
}

function setEmail(state: AppState, value: string): AppState {
  return {email: value, result: state.result};
}

function check(state: AppState, ignored: number): AppState {
  let text: string = strings.trim(state.email);
  let ok: boolean = true;
  let message: string = "";
  if (strings.length(text) === 0) {
    ok = false;
    message = "Enter an email address.";
  } else if (strings.contains(text, " ")) {
    ok = false;
    message = "An email address cannot contain spaces.";
  } else {
    let atCount: number = 0;
    let atPos: number = -1;
    let i: number = 0;
    while (i < strings.length(text)) {
      if (strings.substring(text, i, i + 1) === "@") {
        atCount = atCount + 1;
        atPos = i;
      }
      i = i + 1;
    }
    if (atCount !== 1) {
      ok = false;
      message = "An email address needs exactly one @.";
    } else if (atPos === 0) {
      ok = false;
      message = "There is nothing before the @.";
    } else if (atPos === strings.length(text) - 1) {
      ok = false;
      message = "There is nothing after the @.";
    } else {
      let domain: string = strings.substring(text, atPos + 1, strings.length(text));
      let dotPos: number = -1;
      let j: number = 0;
      while (j < strings.length(domain)) {
        if (strings.substring(domain, j, j + 1) === ".") {
          dotPos = j;
        }
        j = j + 1;
      }
      if (dotPos <= 0) {
        ok = false;
        message = "The domain needs a dot and a name after it.";
      } else if (dotPos === strings.length(domain) - 1) {
        ok = false;
        message = "The domain needs a name after the last dot.";
      } else {
        message = "This looks like a valid email address.";
      }
    }
  }
  let result: string = "invalid";
  if (ok) {
    result = "valid";
  }
  return {email: state.email, result: result + "|" + message};
}

function expect(state: AppState): boolean {
  return strings.length(state.result) >= 0;
}















function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Email Format Checker", "EMAIL CHECK", "See if an email address is shaped correctly", ""));
  sections.push(ui.Section("content", "", "", [
    ui.TextField("default", "Email address", state.email, "setEmail", "email"),
    ui.ActionBar("end", [
      ui.Button("primary", "Check format", "check", 0, true)
    ])
  ]));
  let hasResult: boolean = strings.length(state.result) > 0;
  let valid: boolean = strings.startsWith(state.result, "valid");
  let message: string = "";
  if (hasResult) {
    let bar: number = 0;
    let i: number = 0;
    while (i < strings.length(state.result)) {
      if (strings.substring(state.result, i, i + 1) === "|") {
        bar = i;
      }
      i = i + 1;
    }
    message = strings.substring(state.result, bar + 1, strings.length(state.result));
  }
  let bannerStyle: string = "danger";
  let bannerTitle: string = "Not a valid format";
  if (valid) {
    bannerStyle = "success";
    bannerTitle = "Looks valid";
  }
  sections.push(ui.Section("summary", "", "", [
    ui.When(hasResult, ui.InsetBanner(bannerStyle, bannerTitle, message, "", "", "info"))
  ]));
  return ui.AppTheme("technical", "", sections);
}

