function c_buildRound(state: AppState): C_Word[] {
  let bank: C_Word[] = c_bank();
  let total: number = bank.length();
  let want: number = state.wordCount;
  if (want > total) { want = total; }
  if (want < 1) { want = 1; }
  let seed: number = state.c_roundSeed;
  let picked: C_Word[] = [];
  let used: boolean[] = [];
  let i: number = 0;
  while (i < total) {
    used.push(false);
    i = i + 1;
  }
  let made: number = 0;
  while (made < want) {
    seed = math.randomStep(seed);
    let pick: number = math.randomBelow(seed, total);
    if (!used[pick]) {
      used[pick] = true;
      picked.push(bank[pick]);
      made = made + 1;
    }
  }
  return picked;
}

