}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_driverName) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {driverName: strings.trim(state.draft_driverName), milesDriven: strings.toNumber(state.draft_milesDriven, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
