  return {monthlyCostText: "20", peopleCount: 4, labels8: labels8, records8: records8, draftWho8: 0, draftAmount8: "", draftNote8: "", currency8: currency8};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}

function port_costPerPerson(state: AppState): number {
  let monthlyCost: number = strings.toNumber(state.monthlyCostText, 0);
  let peopleCount: number = state.peopleCount;
  let costPerPerson: number = share(monthlyCost, peopleCount);
  return costPerPerson;
}



function set_monthlyCost(state: AppState, value: string): AppState {
  return {monthlyCostText: value, peopleCount: state.peopleCount, labels8: state.labels8, records8: state.records8, draftWho8: state.draftWho8, draftAmount8: state.draftAmount8, draftNote8: state.draftNote8, currency8: state.currency8};
}

function set_peopleCount(state: AppState, value: number): AppState {
  return {peopleCount: value, monthlyCostText: state.monthlyCostText, labels8: state.labels8, records8: state.records8, draftWho8: state.draftWho8, draftAmount8: state.draftAmount8, draftNote8: state.draftNote8, currency8: state.currency8};
}









function setWho8(state: AppState, index: number): AppState {
  return {labels8: state.labels8, records8: state.records8, draftWho8: index, draftAmount8: state.draftAmount8, draftNote8: state.draftNote8, currency8: state.currency8, monthlyCostText: state.monthlyCostText, peopleCount: state.peopleCount};
}

function setAmount8(state: AppState, value: string): AppState {
  return {labels8: state.labels8, records8: state.records8, draftWho8: state.draftWho8, draftAmount8: value, draftNote8: state.draftNote8, currency8: state.currency8, monthlyCostText: state.monthlyCostText, peopleCount: state.peopleCount};
}

function setNote8(state: AppState, value: string): AppState {
  return {labels8: state.labels8, records8: state.records8, draftWho8: state.draftWho8, draftAmount8: state.draftAmount8, draftNote8: value, currency8: state.currency8, monthlyCostText: state.monthlyCostText, peopleCount: state.peopleCount};
}

function addRecord8(state: AppState, ignored: number): AppState {
  let amount: number = math.round(strings.toNumber(state.draftAmount8, 0) * 100) / 100;
  if (amount <= 0) { return state; }
  let out: Tally[] = [];
  let i: number = 0;
  while (i < state.records8.length()) {
    out.push(state.records8[i]);
    i = i + 1;
  }
  out.push({who: state.draftWho8, amount: amount, note: state.draftNote8});
  return {labels8: state.labels8, records8: out, draftWho8: state.draftWho8, draftAmount8: "", draftNote8: "", currency8: state.currency8, monthlyCostText: state.monthlyCostText, peopleCount: state.peopleCount};
}

function removeLastRecord8(state: AppState, ignored: number): AppState {
  let out: Tally[] = [];
  let i: number = 0;
  while (i < state.records8.length() - 1) {
    out.push(state.records8[i]);
    i = i + 1;
  }
  return {labels8: state.labels8, records8: out, draftWho8: state.draftWho8, draftAmount8: state.draftAmount8, draftNote8: state.draftNote8, currency8: state.currency8, monthlyCostText: state.monthlyCostText, peopleCount: state.peopleCount};
}

function clearRecords8(state: AppState, ignored: number): AppState {
  let out: Tally[] = [];
  return {labels8: state.labels8, records8: out, draftWho8: 0, draftAmount8: "", draftNote8: "", currency8: state.currency8, monthlyCostText: state.monthlyCostText, peopleCount: state.peopleCount};
}

function totals8(state: AppState): number[] {
  let out: number[] = [];
  let i: number = 0;
  while (i < state.labels8.length()) {
    out.push(0);
    i = i + 1;
  }
  for (let r: Tally of state.records8) {
    if (r.who >= 0 && r.who < out.length()) { out[r.who] = math.round((out[r.who] + r.amount) * 100) / 100; }
  }
  return out;
}

function totalSum8(state: AppState): number {
  let sum: number = 0;
  for (let r: Tally of state.records8) { sum = sum + r.amount; }
  return math.round(sum * 100) / 100;
}

function average8(state: AppState): number {
  let n: number = state.labels8.length();
  if (n === 0) { return 0; }
  return math.round(totalSum8(state) / n * 100) / 100;
}

function balances8(state: AppState): number[] {
  let totals: number[] = totals8(state);
  let n: number = state.labels8.length();
  let totalCents: number = math.round(totalSum8(state) * 100);
  let shareCents: number = 0;
  let extra: number = 0;
  if (n > 0) {
    shareCents = math.floor(totalCents / n);
    extra = totalCents - shareCents * n;
  }
  let out: number[] = [];
  let i: number = 0;
  while (i < totals.length()) {
    let owed: number = shareCents;
    if (i < extra) { owed = owed + 1; }
    out.push((math.round(totals[i] * 100) - owed) / 100);
    i = i + 1;
  }
  return out;
}

function c_totalMinutes(state: AppState): number {
  let sum: number = 0;
  for (let r: Tally of state.records8) {
    sum = sum + r.amount;
  }
  return math.round(sum * 100) / 100;
}

function c_costPerMinute(state: AppState): number {
  let monthlyCost: number = strings.toNumber(state.monthlyCostText, 0);
  let minutes: number = c_totalMinutes(state);
  if (minutes <= 0) { return 0; }
  return monthlyCost / minutes;
}

