@jsonable
class LogEntry {
  unitName: string;
  squareFeet: number;
  minute: number;
}

@jsonable
class AppState {
  totalBillText: string;
  totalAreaText: string;
  entries: LogEntry[];
  draft_unitName: string;
  draft_squareFeet: string;
  removedEntries: LogEntry[];
  removedAt: number;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {totalBillText: "300", totalAreaText: "2000", entries: emptyEntries, draft_unitName: "", draft_squareFeet: "", removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_totalBill(state: AppState, value: string): AppState {
  return {totalBillText: value, totalAreaText: state.totalAreaText, entries: state.entries, draft_unitName: state.draft_unitName, draft_squareFeet: state.draft_squareFeet, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_totalArea(state: AppState, value: string): AppState {
  return {totalAreaText: value, totalBillText: state.totalBillText, entries: state.entries, draft_unitName: state.draft_unitName, draft_squareFeet: state.draft_squareFeet, removedEntries: state.removedEntries, removedAt: state.removedAt};
}



function set_draft_unitName(state: AppState, value: string): AppState {
  return {draft_unitName: value, totalBillText: state.totalBillText, totalAreaText: state.totalAreaText, entries: state.entries, draft_squareFeet: state.draft_squareFeet, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_squareFeet(state: AppState, value: string): AppState {
  return {draft_squareFeet: value, totalBillText: state.totalBillText, totalAreaText: state.totalAreaText, entries: state.entries, draft_unitName: state.draft_unitName, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_unitName) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {unitName: strings.trim(state.draft_unitName), squareFeet: strings.toNumber(state.draft_squareFeet, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_unitName: "", draft_squareFeet: "", totalBillText: state.totalBillText, totalAreaText: state.totalAreaText, removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, totalBillText: state.totalBillText, totalAreaText: state.totalAreaText, draft_unitName: state.draft_unitName, draft_squareFeet: state.draft_squareFeet};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, totalBillText: state.totalBillText, totalAreaText: state.totalAreaText, draft_unitName: state.draft_unitName, draft_squareFeet: state.draft_squareFeet};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, totalBillText: state.totalBillText, totalAreaText: state.totalAreaText, entries: state.entries, draft_unitName: state.draft_unitName, draft_squareFeet: state.draft_squareFeet};
}





function c_shareOf(state: AppState, index: number): number {
