import * as ui from "std/ui"

@jsonable
class LogEntry {
  napStart: number;
  napEnd: number;
  minute: number;
}

@jsonable
class AppState {
  weekStartIndex: number;
  entries: LogEntry[];
  draft_napStart: number;
  draft_napEnd: number;
  removedEntries: LogEntry[];
  removedAt: number;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {weekStartIndex: 1, entries: emptyEntries, draft_napStart: 780, draft_napEnd: 840, removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_weekStart(state: AppState, value: number): AppState {
  return {weekStartIndex: value, entries: state.entries, draft_napStart: state.draft_napStart, draft_napEnd: state.draft_napEnd, removedEntries: state.removedEntries, removedAt: state.removedAt};
}



function set_draft_napStart(state: AppState, value: number): AppState {
  return {draft_napStart: value, weekStartIndex: state.weekStartIndex, entries: state.entries, draft_napEnd: state.draft_napEnd, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_napEnd(state: AppState, value: number): AppState {
  return {draft_napEnd: value, weekStartIndex: state.weekStartIndex, entries: state.entries, draft_napStart: state.draft_napStart, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  let none: LogEntry[] = [];
  let entry: LogEntry = {napStart: state.draft_napStart, napEnd: state.draft_napEnd, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, weekStartIndex: state.weekStartIndex, draft_napStart: state.draft_napStart, draft_napEnd: state.draft_napEnd, removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, weekStartIndex: state.weekStartIndex, draft_napStart: state.draft_napStart, draft_napEnd: state.draft_napEnd};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, weekStartIndex: state.weekStartIndex, draft_napStart: state.draft_napStart, draft_napEnd: state.draft_napEnd};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, weekStartIndex: state.weekStartIndex, entries: state.entries, draft_napStart: state.draft_napStart, draft_napEnd: state.draft_napEnd};
}





