function c_go(state: AppState, value: number): AppState {
  let next: string = "";
  if (state.c_scene === "start") {
    if (value === 0) { next = "map"; }
    if (value === 1) { next = "shore"; }
  } else if (state.c_scene === "map") {
    if (value === 0) { next = "crew"; }
    if (value === 1) { next = "shore"; }
  } else if (state.c_scene === "crew") {
    if (value === 0) { next = "serpent"; }
    if (value === 1) { next = "rival"; }
  } else if (state.c_scene === "serpent") {
    if (value === 0) { next = "chest"; }
    if (value === 1) { next = "rival"; }
  } else if (state.c_scene === "rival") {
    if (value === 0) { next = "chest"; }
    if (value === 1) { next = "mutiny"; }
  } else if (state.c_scene === "chest") {
    if (value === 0) { next = "riches"; }
    if (value === 1) { next = "curse"; }
    if (value === 2) { next = "shore"; }
