@jsonable
class AppState {
  entries: LogEntry[];
  draft_cardName: string;
  draft_balance: string;
  draft_expiry: number;
  removedEntries: LogEntry[];
  removedAt: number;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {entries: emptyEntries, draft_cardName: "", draft_balance: "", draft_expiry: time.daysSinceEpoch(), removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}







function set_draft_cardName(state: AppState, value: string): AppState {
  return {draft_cardName: value, entries: state.entries, draft_balance: state.draft_balance, draft_expiry: state.draft_expiry, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_balance(state: AppState, value: string): AppState {
  return {draft_balance: value, entries: state.entries, draft_cardName: state.draft_cardName, draft_expiry: state.draft_expiry, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_expiry(state: AppState, value: number): AppState {
  return {draft_expiry: value, entries: state.entries, draft_cardName: state.draft_cardName, draft_balance: state.draft_balance, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_cardName) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {cardName: strings.trim(state.draft_cardName), balance: strings.toNumber(state.draft_balance, 0), expiry: state.draft_expiry, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_cardName: "", draft_balance: "", draft_expiry: state.draft_expiry, removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, draft_cardName: state.draft_cardName, draft_balance: state.draft_balance, draft_expiry: state.draft_expiry};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, draft_cardName: state.draft_cardName, draft_balance: state.draft_balance, draft_expiry: state.draft_expiry};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, entries: state.entries, draft_cardName: state.draft_cardName, draft_balance: state.draft_balance, draft_expiry: state.draft_expiry};
}





function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Gift Card Tracker", "GIFT CARDS", "Keep balances and expiry dates in one place", ""));
  {
      let entryCount: number = state.entries.length();
      let entryTotal: number = 0;
      for (let e: LogEntry of state.entries) { entryTotal = entryTotal + e.balance; }
      let totalBalance: number = entryTotal;
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 1, [ui.NumberStat("default", "Total balance", totalBalance, "$", "", 1, "", "chart", 2)])]));
    let rows: ui.View[] = [];
    let i: number = entryCount - 1;
    while (i >= 0 && i > entryCount - 21) {
      let e: LogEntry = state.entries[i];
      let sub: string = ui.dateToString(e.expiry) + " · " + "Added " + ui.clockToString(e.minute);
      rows.push(ui.ListItem("default", e.cardName, sub, "$" + ui.formatNumber(e.balance, 2), "", 0, false, ""));
      rows.push(ui.ActionBar("end", [ui.Button("secondary", "Remove", "removeEntry", i, true)]));
      i = i - 1;
    }
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Card", state.draft_cardName, "set_draft_cardName"), ui.TextField("default", "Balance", state.draft_balance, "set_draft_balance", "number"), ui.DateField("default", "Expires", state.draft_expiry, "set_draft_expiry"), ui.ActionBar("end", [ui.Button("primary", "Add", "addEntry", 0, strings.trim(state.draft_cardName) !== "")])]));
    sections.push(ui.Section("content", "", "", [ui.SectionHeader("default", "Gift cards", "Newest first", ui.numberToString(entryCount)), ui.When(entryCount === 0, ui.EmptyState("default", "Nothing added yet", "Fill in the fields above and tap Add.", "", "", "list")), ui.When(entryCount > 0, ui.ListGroup("default", "", rows)), ui.When(state.removedEntries.length() > 0, ui.Snackbar("default", "Removed", "Undo", "undoRemove")), ui.Ticker("default", "undoClock", 6000 + state.entries.length() % 7, state.removedEntries.length() > 0, "expireUndo")]));
  }
  return ui.AppTheme("technical", "", sections);
}

