function countdownSeconds(state: AppState): number {
  let speechLengthValues: number[] = [180, 240, 300, 360, 480];
  let speechLength: number = speechLengthValues[state.speechLengthIndex];
  return speechLength;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, speechLengthIndex: state.speechLengthIndex}; }
  return {elapsedMs: total, running: false, finished: true, speechLengthIndex: state.speechLengthIndex};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, speechLengthIndex: state.speechLengthIndex};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, speechLengthIndex: state.speechLengthIndex};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, speechLengthIndex: state.speechLengthIndex};
