import * as ui from "std/ui"

@jsonable
class AppState {
  elapsedMs: number;
  running: boolean;
  finished: boolean;
  roundLengthIndex: number;
  startingChipsText: string;
  effectStatus: string;
  settingsOpen: boolean;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, roundLengthIndex: 2, startingChipsText: "1000", effectStatus: "", settingsOpen: false};
}

function countdownSeconds(state: AppState): number {
  let roundLengthValues: number[] = [60, 120, 180, 300];
  let roundLength: number = roundLengthValues[state.roundLengthIndex];
  let startingChips: number = strings.toNumber(state.startingChipsText, 0);
  let smallBlindStart: number = 10;
  let blindMultiplier: number = 2;
  return roundLength;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, roundLengthIndex: state.roundLengthIndex, startingChipsText: state.startingChipsText, effectStatus: state.effectStatus, settingsOpen: state.settingsOpen}; }
  sdk.call("SensorServiceKit.vibrator.vibrate", ["duration", "2000"], "onEffect");
  return {elapsedMs: total, running: false, finished: true, effectStatus: "pending", roundLengthIndex: state.roundLengthIndex, startingChipsText: state.startingChipsText, settingsOpen: state.settingsOpen};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, roundLengthIndex: state.roundLengthIndex, startingChipsText: state.startingChipsText, effectStatus: state.effectStatus, settingsOpen: state.settingsOpen};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, roundLengthIndex: state.roundLengthIndex, startingChipsText: state.startingChipsText, effectStatus: state.effectStatus, settingsOpen: state.settingsOpen};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, roundLengthIndex: state.roundLengthIndex, startingChipsText: state.startingChipsText, effectStatus: state.effectStatus, settingsOpen: state.settingsOpen};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_roundLength(state: AppState, value: number): AppState {
  return {roundLengthIndex: value, elapsedMs: 0, running: false, finished: false, startingChipsText: state.startingChipsText, effectStatus: state.effectStatus, settingsOpen: state.settingsOpen};
}

function set_startingChips(state: AppState, value: string): AppState {
  return {startingChipsText: value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, roundLengthIndex: state.roundLengthIndex, effectStatus: state.effectStatus, settingsOpen: state.settingsOpen};
}



function onEffect(state: AppState, value: string): AppState {
  return {effectStatus: value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, roundLengthIndex: state.roundLengthIndex, startingChipsText: state.startingChipsText, settingsOpen: state.settingsOpen};
}



function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, roundLengthIndex: state.roundLengthIndex, startingChipsText: state.startingChipsText, effectStatus: state.effectStatus};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Poker Round Timer", "TWO PLAYERS", "Blinds up on a fixed round clock", "clock"));
  {
    sections.push(ui.Ticker("default", "clock", 200, state.running, "onTick"));
      let roundLengthValues: number[] = [60, 120, 180, 300];
      let roundLength: number = roundLengthValues[state.roundLengthIndex];
      let startingChips: number = strings.toNumber(state.startingChipsText, 0);
      let smallBlindStart: number = 10;
      let blindMultiplier: number = 2;
      let duration: number = countdownSeconds(state);
      let elapsed: number = math.min(state.elapsedMs / 1000, duration);
      let remaining: number = duration - elapsed;
      let roundsPlayed: number = math.ceil(share(elapsed, roundLength));
      let effectNote: string = "Phone: " + state.effectStatus;
      if (state.effectStatus === "pending") { effectNote = "Asking the phone..."; }
    sections.push(ui.Section("hero", "", "", [ui.Hero("accent", "Current round", ui.durationToString(math.ceil(remaining)), "", [ui.ActionBar("spread", [ui.Button("primary", "Start", "onStart", 0, !state.running), ui.Button("secondary", "Stop", "onStop", 0, state.running), ui.Button("secondary", "Reset", "onReset", 0, true)])])]));
    sections.push(ui.Section("content", "", "", [ui.Select("default", "Round length", ["1 min", "2 min", "3 min", "5 min"], state.roundLengthIndex, "set_roundLength")]));
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 1, [ui.NumberStat("default", "Rounds played", roundsPlayed, "", "", 1, "", "chart", 0)])]));
    sections.push(ui.When(state.effectStatus !== "", ui.InsetBanner("default", "Done", effectNote, "", "", "info")));
  }
  {
    let settingsWord: string = "Show";
    if (state.settingsOpen) { settingsWord = "Hide"; }
    sections.push(ui.Section("supporting", "", "", [
      ui.ListItem("default", "Settings", "1 setting", settingsWord, "toggleSettings", 0, true, ""),
      ui.When(state.settingsOpen, ui.Column("default", [ui.TextField("default", "Starting chips", state.startingChipsText, "set_startingChips", "number")]))
    ]));
  }
  return ui.AppTheme("technical", "", sections);
}

