function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, turnLengthIndex: 1, playerOne: "", playerTwo: "", effectStatus: ""};
}

function countdownSeconds(state: AppState): number {
  let turnLengthValues: number[] = [60, 120, 180, 300];
  let turnLength: number = turnLengthValues[state.turnLengthIndex];
  return turnLength;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, turnLengthIndex: state.turnLengthIndex, playerOne: state.playerOne, playerTwo: state.playerTwo, effectStatus: state.effectStatus}; }
  sdk.call("SensorServiceKit.vibrator.vibrate", ["duration", "2000"], "onEffect");
  return {elapsedMs: total, running: false, finished: true, effectStatus: "pending", turnLengthIndex: state.turnLengthIndex, playerOne: state.playerOne, playerTwo: state.playerTwo};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, turnLengthIndex: state.turnLengthIndex, playerOne: state.playerOne, playerTwo: state.playerTwo, effectStatus: state.effectStatus};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, turnLengthIndex: state.turnLengthIndex, playerOne: state.playerOne, playerTwo: state.playerTwo, effectStatus: state.effectStatus};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, turnLengthIndex: state.turnLengthIndex, playerOne: state.playerOne, playerTwo: state.playerTwo, effectStatus: state.effectStatus};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_turnLength(state: AppState, value: number): AppState {
  return {turnLengthIndex: value, elapsedMs: 0, running: false, finished: false, playerOne: state.playerOne, playerTwo: state.playerTwo, effectStatus: state.effectStatus};
}

function set_playerOne(state: AppState, value: string): AppState {
  return {playerOne: value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, turnLengthIndex: state.turnLengthIndex, playerTwo: state.playerTwo, effectStatus: state.effectStatus};
}

function set_playerTwo(state: AppState, value: string): AppState {
  return {playerTwo: value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, turnLengthIndex: state.turnLengthIndex, playerOne: state.playerOne, effectStatus: state.effectStatus};
}



function onEffect(state: AppState, value: string): AppState {
  return {effectStatus: value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, turnLengthIndex: state.turnLengthIndex, playerOne: state.playerOne, playerTwo: state.playerTwo};
}



