  sections.push(ui.Header("default", "Sibling Turn Timer", "TURN TIMER", "Fair turns for two players, one phone", "clock"));
  {
    sections.push(ui.Ticker("default", "clock", 200, state.running, "onTick"));
      let turnLengthValues: number[] = [60, 120, 180, 300];
      let turnLength: number = turnLengthValues[state.turnLengthIndex];
      let duration: number = countdownSeconds(state);
      let elapsed: number = math.min(state.elapsedMs / 1000, duration);
      let remaining: number = duration - elapsed;
      let effectNote: string = "Phone: " + state.effectStatus;
      if (state.effectStatus === "pending") { effectNote = "Asking the phone..."; }
    sections.push(ui.Section("hero", "", "", [ui.Hero("accent", "Current player's turn", ui.durationToString(math.ceil(remaining)), "", [ui.ActionBar("spread", [ui.Button("primary", "Start", "onStart", 0, !state.running), ui.Button("secondary", "Stop", "onStop", 0, state.running), ui.Button("secondary", "Reset", "onReset", 0, true)])])]));
