import * as ui from "std/ui"

@jsonable
class Item {
  label: string;
  detail: string;
  done: boolean;
}

@jsonable
class AppState {
  goalPerDay: number;
  items7: Item[];
  settingsOpen: boolean;
}

function init(): AppState {
  let items7: Item[] = [
    {label: "Push-ups", detail: "Tap to tick", done: false},
    {label: "Squats", detail: "Tap to tick", done: false},
    {label: "Lunges", detail: "Tap to tick", done: false},
    {label: "Plank", detail: "Tap to tick", done: false},
    {label: "Jumping jacks", detail: "Tap to tick", done: false},
    {label: "Sit-ups", detail: "Tap to tick", done: false},
    {label: "Burpees", detail: "Tap to tick", done: false},
    {label: "Stretching", detail: "Tap to tick", done: false}
  ];
  return {goalPerDay: 5, items7: items7, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_goalPerDay(state: AppState, value: number): AppState {
  return {goalPerDay: value, items7: state.items7, settingsOpen: state.settingsOpen};
}







function toggle7(state: AppState, index: number): AppState {
  let out: Item[] = [];
  let i: number = 0;
  while (i < state.items7.length()) {
    let it: Item = state.items7[i];
    if (i === index) {
      out.push({label: it.label, detail: it.detail, done: !it.done});
    } else {
      out.push(it);
    }
    i = i + 1;
  }
  return {items7: out, goalPerDay: state.goalPerDay, settingsOpen: state.settingsOpen};
}

function doneCount7(state: AppState): number {
  let n: number = 0;
  let i: number = 0;
  while (i < state.items7.length()) {
    let it: Item = state.items7[i];
    if (it.done) { n = n + 1; }
    i = i + 1;
  }
  return n;
}

function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, goalPerDay: state.goalPerDay, items7: state.items7};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Daily Exercise Grid", "DAILY MOVES", "Tick off each exercise you finish today", ""));
  {
      let goalPerDay: number = state.goalPerDay;
  }
  {
      let count: number = state.items7.length();
      let rows: ui.View[] = [];
      let j: number = 0;
      while (j < count) {
        let it: Item = state.items7[j];
        let icon: string = "";
        let subtitle: string = it.detail;
        if (it.done) { icon = "check"; subtitle = "done"; if (it.detail.length() > 0) { subtitle = it.detail + " - done"; } }
        rows.push(ui.ListItem("default", it.label, subtitle, "", "toggle7", j, true, icon));
        j = j + 1;
      }
      sections.push(ui.Section("content", "", "", [
        ui.When(count === 0, ui.EmptyState("default", "Nothing here", "Add an item to get started.", "", "", "pin")),
        ui.When(count > 0, ui.ListGroup("default", ui.numberToString(doneCount7(state)) + " of " + ui.numberToString(count) + " done - tap one to tick it", rows))
      ]));
    }
  {
    let settingsWord: string = "Show";
    if (state.settingsOpen) { settingsWord = "Hide"; }
    sections.push(ui.Section("supporting", "", "", [
