import * as ui from "std/ui"

@jsonable
class LogEntry {
  toolName: string;
  quantity: number;
  minute: number;
}

@jsonable
class AppState {
  lowStockThreshold: number;
  entries: LogEntry[];
  draft_toolName: string;
  draft_quantity: string;
  removedEntries: LogEntry[];
  removedAt: number;
  effectStatus: string;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {lowStockThreshold: 2, entries: emptyEntries, draft_toolName: "", draft_quantity: "", removedEntries: emptyEntries, removedAt: -1, effectStatus: "", settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_lowStockThreshold(state: AppState, value: number): AppState {
  return {lowStockThreshold: value, entries: state.entries, draft_toolName: state.draft_toolName, draft_quantity: state.draft_quantity, removedEntries: state.removedEntries, removedAt: state.removedAt, effectStatus: state.effectStatus, settingsOpen: state.settingsOpen};
}



function set_draft_toolName(state: AppState, value: string): AppState {
  return {draft_toolName: value, lowStockThreshold: state.lowStockThreshold, entries: state.entries, draft_quantity: state.draft_quantity, removedEntries: state.removedEntries, removedAt: state.removedAt, effectStatus: state.effectStatus, settingsOpen: state.settingsOpen};
}

function set_draft_quantity(state: AppState, value: string): AppState {
  return {draft_quantity: value, lowStockThreshold: state.lowStockThreshold, entries: state.entries, draft_toolName: state.draft_toolName, removedEntries: state.removedEntries, removedAt: state.removedAt, effectStatus: state.effectStatus, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_toolName) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {toolName: strings.trim(state.draft_toolName), quantity: strings.toNumber(state.draft_quantity, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  sdk.call("AudioKit.TonePlayer.start", ["type", "DOUBLE_BEEP"], "onEffect");
  return {entries: out, removedEntries: none, draft_toolName: "", draft_quantity: "", effectStatus: "pending", lowStockThreshold: state.lowStockThreshold, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, lowStockThreshold: state.lowStockThreshold, draft_toolName: state.draft_toolName, draft_quantity: state.draft_quantity, effectStatus: state.effectStatus, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, lowStockThreshold: state.lowStockThreshold, draft_toolName: state.draft_toolName, draft_quantity: state.draft_quantity, effectStatus: state.effectStatus, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, lowStockThreshold: state.lowStockThreshold, entries: state.entries, draft_toolName: state.draft_toolName, draft_quantity: state.draft_quantity, effectStatus: state.effectStatus, settingsOpen: state.settingsOpen};
}

function onEffect(state: AppState, value: string): AppState {
  return {effectStatus: value, lowStockThreshold: state.lowStockThreshold, entries: state.entries, draft_toolName: state.draft_toolName, draft_quantity: state.draft_quantity, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}





function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, lowStockThreshold: state.lowStockThreshold, entries: state.entries, draft_toolName: state.draft_toolName, draft_quantity: state.draft_quantity, removedEntries: state.removedEntries, removedAt: state.removedAt, effectStatus: state.effectStatus};
}

