<functions>
function c_roundLength(index: number): number {
  let values: number[] = [10, 20, 50];
  if (index < 0 || index > 2) { return 10; }
  return values[index];
}

function c_shuffle(state: AppState, count: number): number[] {
  let out: number[] = [];
  let i: number = 0;
  while (i < count) {
    out.push(i);
    i = i + 1;
  }
  let seed: number = state.c_seed;
  let j: number = count - 1;
  while (j > 0) {
    seed = math.randomStep(seed);
    let k: number = math.randomBelow(seed, j + 1);
    let tmp: number = out[j];
    out[j] = out[k];
    out[k] = tmp;
    j = j - 1;
  }
  return out;
}

function c_buildChoices(state: AppState, answer: number): number[] {
  let pool: number[] = [];
  let i: number = 0;
  while (i < 46) {
    if (i !== answer) { pool.push(i); }
    i = i + 1;
  }
  let seed: number = state.c_seed;
  let j: number = pool.length() - 1;
  while (j > 0) {
    seed = math.randomStep(seed);
    let k: number = math.randomBelow(seed, j + 1);
    let tmp: number = pool[j];
    pool[j] = pool[k];
    pool[k] = tmp;
    j = j - 1;
  }
  let picks: number[] = [];
  picks.push(pool[0]);
  picks.push(pool[1]);
  picks.push(pool[2]);
  picks.push(answer);
  let s2: number = seed;
  let m: number = 3;
  while (m > 0) {
    s2 = math.randomStep(s2);
    let n: number = math.randomBelow(s2, m + 1);
    let tmp2: number = picks[m];
    picks[m] = picks[n];
    picks[n] = tmp2;
    m = m - 1;
  }
  return picks;
}

function c_start(state: AppState, ignored: number): AppState {
  let length: number = c_roundLength(state.c_roundLengthIndex);
  let deck: number[] = c_shuffle(state, 46);
  let trimmed: number[] = [];
  let i: number = 0;
  while (i < length && i < deck.length()) {
    trimmed.push(deck[i]);
    i = i + 1;
  }
  let first: number = 0;
  if (trimmed.length() > 0) { first = trimmed[0]; }
  let choices: number[] = c_buildChoices(state, first);
  return {c_deck: trimmed, c_position: 0, c_choices: choices, c_correct: 0, c_answered: false, c_picked: -1, c_finished: false, c_seed: state.c_seed + 13__PASSTHROUGH__};
}

function c_pick(state: AppState, value: number): AppState {
  if (state.c_finished || state.c_answered || state.c_deck.length() === 0) {
    return {__PASSTHROUGH__};
  }
  let answer: number = state.c_deck[state.c_position];
  let correct: number = state.c_correct;
  if (value === answer) { correct = correct + 1; }
  return {c_answered: true, c_picked: value, c_correct: correct__PASSTHROUGH__};
}

function c_next(state: AppState, ignored: number): AppState {
  if (!state.c_answered) { return {__PASSTHROUGH__}; }
  let nextPos: number = state.c_position + 1;
  if (nextPos >= state.c_deck.length()) {
    return {c_finished: true, c_answered: false, c_picked: -1__PASSTHROUGH__};
  }
  let answer: number = state.c_deck[nextPos];
  let choices: number[] = c_buildChoices(state, answer);
  return {c_position: nextPos, c_choices: choices, c_answered: false, c_picked: -1, c_seed: state.c_seed + 7__PASSTHROUGH__};
}

function c_setRound(state: AppState, value: number): AppState {
  return {c_roundLengthIndex: value__PASSTHROUGH__};
}

function c_hiragana(index: number): string {
  let list: string[] = ["あ","い","う","え","お","か","き","く","け","こ","さ","し","す","せ","そ","た","ち","つ","て","と","な","に","ぬ","ね","の","は","ひ","ふ","へ","ほ","ま","み","む","め","も","や","ゆ","よ","ら","り","る","れ","ろ","わ","を","ん"];
  if (index < 0 || index >= list.length()) { return ""; }
  return list[index];
}

function c_romaji(index: number): string {
  let list: string[] = ["a","i","u","e","o","ka","ki","ku","ke","ko","sa","shi","su","se","so","ta","chi","tsu","te","to","na","ni","nu","ne","no","ha","hi","fu","he","ho","ma","mi","mu","me","mo","ya","yu","yo","ra","ri","ru","re","ro","wa","wo","n"];
