import * as ui from "std/ui"

@jsonable
class LogEntry {
  purchaseAmount: number;
  minute: number;
}

@jsonable
class AppState {
  roundToIndex: number;
  entries: LogEntry[];
  draft_purchaseAmount: string;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {roundToIndex: 1, entries: emptyEntries, draft_purchaseAmount: "", removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_roundTo(state: AppState, value: number): AppState {
  return {roundToIndex: value, entries: state.entries, draft_purchaseAmount: state.draft_purchaseAmount, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_purchaseAmount(state: AppState, value: string): AppState {
  return {draft_purchaseAmount: value, roundToIndex: state.roundToIndex, entries: state.entries, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_purchaseAmount) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {purchaseAmount: strings.toNumber(state.draft_purchaseAmount, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_purchaseAmount: "", roundToIndex: state.roundToIndex, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, roundToIndex: state.roundToIndex, draft_purchaseAmount: state.draft_purchaseAmount, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, roundToIndex: state.roundToIndex, draft_purchaseAmount: state.draft_purchaseAmount, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, roundToIndex: state.roundToIndex, entries: state.entries, draft_purchaseAmount: state.draft_purchaseAmount, settingsOpen: state.settingsOpen};
}





function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, roundToIndex: state.roundToIndex, entries: state.entries, draft_purchaseAmount: state.draft_purchaseAmount, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Round Up Savings", "SAVINGS", "Save the spare change from every purchase", ""));
  {
      let roundToValues: number[] = [1, 5, 10];
      let roundTo: number = roundToValues[state.roundToIndex];
      let entryCount: number = state.entries.length();
      let entryTotal: number = 0;
      for (let e: LogEntry of state.entries) { entryTotal = entryTotal + e.purchaseAmount; }
      let totalSpent: number = entryTotal;
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 1, [ui.NumberStat("default", "Total spent", totalSpent, "$", "", 1, "", "chart", 2)])]));
    let rows: ui.View[] = [];
    let i: number = entryCount - 1;
    while (i >= 0 && i > entryCount - 21) {
      let e: LogEntry = state.entries[i];
      let sub: string = "Added " + ui.clockToString(e.minute);
      rows.push(ui.ListItem("default", "$" + ui.formatNumber(e.purchaseAmount, 2), sub, "", "", 0, false, ""));
      rows.push(ui.ActionBar("end", [ui.Button("secondary", "Remove", "removeEntry", i, true)]));
      i = i - 1;
    }
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Amount spent", state.draft_purchaseAmount, "set_draft_purchaseAmount", "number"), ui.ActionBar("end", [ui.Button("primary", "Add", "addEntry", 0, strings.trim(state.draft_purchaseAmount) !== "")])]));
    sections.push(ui.Section("content", "", "", [ui.SectionHeader("default", "Purchases", "Newest first", ui.numberToString(entryCount)), ui.When(entryCount === 0, ui.EmptyState("default", "Nothing added yet", "Fill in the fields above and tap Add.", "", "", "list")), ui.When(entryCount > 0, ui.ListGroup("default", "", rows)), ui.When(state.removedEntries.length() > 0, ui.Snackbar("default", "Removed", "Undo", "undoRemove")), ui.Ticker("default", "undoClock", 6000 + state.entries.length() % 7, state.removedEntries.length() > 0, "expireUndo")]));
  }
  {
    let settingsWord: string = "Show";
    if (state.settingsOpen) { settingsWord = "Hide"; }
    sections.push(ui.Section("supporting", "", "", [
      ui.ListItem("default", "Settings", "1 setting", settingsWord, "toggleSettings", 0, true, ""),
      ui.When(state.settingsOpen, ui.Column("default", [ui.Select("default", "Round up to", ["Nearest $1", "Nearest $5", "Nearest $10"], state.roundToIndex, "set_roundTo")]))
    ]));
  }
  return ui.AppTheme("technical", "", sections);
}

