  detail: string;
  done: boolean;
}

@jsonable
class AppState {
  hoursOutsideText: string;
  items7: Item[];
}

function init(): AppState {
  let items7: Item[] = [
    {label: "Sunscreen", detail: "", done: false},
    {label: "Water bottle", detail: "", done: false},
    {label: "Towel", detail: "", done: false},
    {label: "Hat", detail: "", done: false},
    {label: "Sunglasses", detail: "", done: false},
    {label: "Snacks", detail: "", done: false},
    {label: "Swimsuit", detail: "", done: false},
    {label: "Flip-flops", detail: "", done: false}
  ];
  return {hoursOutsideText: "4", items7: items7};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_hoursOutside(state: AppState, value: string): AppState {
  return {hoursOutsideText: value, items7: state.items7};
}







function toggle7(state: AppState, index: number): AppState {
  let out: Item[] = [];
  let i: number = 0;
  while (i < state.items7.length()) {
    let it: Item = state.items7[i];
    if (i === index) {
      out.push({label: it.label, detail: it.detail, done: !it.done});
    } else {
      out.push(it);
    }
    i = i + 1;
  }
  return {items7: out, hoursOutsideText: state.hoursOutsideText};
}

function doneCount7(state: AppState): number {
  let n: number = 0;
  let i: number = 0;
  while (i < state.items7.length()) {
    let it: Item = state.items7[i];
    if (it.done) { n = n + 1; }
    i = i + 1;
  }
  return n;
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Beach Bag by Hours", "PACK BY TIME", "How long you're out decides what goes in the bag.", ""));
  {
      let hoursOutside: number = strings.toNumber(state.hoursOutsideText, 0);
      let itemsPerHour: number = 2;
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Hours outside", state.hoursOutsideText, "set_hoursOutside", "number")]));
  }
  {
      let count: number = state.items7.length();
      let rows: ui.View[] = [];
      let j: number = 0;
      while (j < count) {
        let it: Item = state.items7[j];
        let icon: string = "";
        let subtitle: string = it.detail;
        if (it.done) { icon = "check"; subtitle = "done"; if (it.detail.length() > 0) { subtitle = it.detail + " - done"; } }
        rows.push(ui.ListItem("default", it.label, subtitle, "", "toggle7", j, true, icon));
        j = j + 1;
      }
      sections.push(ui.Section("content", "", "", [
        ui.When(count === 0, ui.EmptyState("default", "Nothing here", "Add an item to get started.", "", "", "pin")),
        ui.When(count > 0, ui.ListGroup("default", ui.numberToString(doneCount7(state)) + " of " + ui.numberToString(count) + " done - tap one to tick it", rows))
      ]));
    }
  return ui.AppTheme("playful", "", sections);
}

