import * as ui from "std/ui"

@jsonable
class LogEntry {
  server: string;
  pointWinner: string;
  serveIn: boolean;
  rallyLength: number;
  minute: number;
}

@jsonable
class AppState {
  matchFormatIndex: number;
  setsToWin: number;
  entries: LogEntry[];
  draft_server: string;
  draft_pointWinner: string;
  draft_serveIn: boolean;
  draft_rallyLength: string;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {matchFormatIndex: 0, setsToWin: 2, entries: emptyEntries, draft_server: "", draft_pointWinner: "", draft_serveIn: false, draft_rallyLength: "", removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_matchFormat(state: AppState, value: number): AppState {
  return {matchFormatIndex: value, setsToWin: state.setsToWin, entries: state.entries, draft_server: state.draft_server, draft_pointWinner: state.draft_pointWinner, draft_serveIn: state.draft_serveIn, draft_rallyLength: state.draft_rallyLength, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_setsToWin(state: AppState, value: number): AppState {
  return {setsToWin: value, matchFormatIndex: state.matchFormatIndex, entries: state.entries, draft_server: state.draft_server, draft_pointWinner: state.draft_pointWinner, draft_serveIn: state.draft_serveIn, draft_rallyLength: state.draft_rallyLength, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_server(state: AppState, value: string): AppState {
  return {draft_server: value, matchFormatIndex: state.matchFormatIndex, setsToWin: state.setsToWin, entries: state.entries, draft_pointWinner: state.draft_pointWinner, draft_serveIn: state.draft_serveIn, draft_rallyLength: state.draft_rallyLength, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_pointWinner(state: AppState, value: string): AppState {
  return {draft_pointWinner: value, matchFormatIndex: state.matchFormatIndex, setsToWin: state.setsToWin, entries: state.entries, draft_server: state.draft_server, draft_serveIn: state.draft_serveIn, draft_rallyLength: state.draft_rallyLength, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_serveIn(state: AppState, value: boolean): AppState {
  return {draft_serveIn: value, matchFormatIndex: state.matchFormatIndex, setsToWin: state.setsToWin, entries: state.entries, draft_server: state.draft_server, draft_pointWinner: state.draft_pointWinner, draft_rallyLength: state.draft_rallyLength, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_rallyLength(state: AppState, value: string): AppState {
  return {draft_rallyLength: value, matchFormatIndex: state.matchFormatIndex, setsToWin: state.setsToWin, entries: state.entries, draft_server: state.draft_server, draft_pointWinner: state.draft_pointWinner, draft_serveIn: state.draft_serveIn, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_server) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {server: strings.trim(state.draft_server), pointWinner: strings.trim(state.draft_pointWinner), serveIn: state.draft_serveIn, rallyLength: strings.toNumber(state.draft_rallyLength, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_server: "", draft_pointWinner: "", draft_rallyLength: "", matchFormatIndex: state.matchFormatIndex, setsToWin: state.setsToWin, draft_serveIn: state.draft_serveIn, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, matchFormatIndex: state.matchFormatIndex, setsToWin: state.setsToWin, draft_server: state.draft_server, draft_pointWinner: state.draft_pointWinner, draft_serveIn: state.draft_serveIn, draft_rallyLength: state.draft_rallyLength, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, matchFormatIndex: state.matchFormatIndex, setsToWin: state.setsToWin, draft_server: state.draft_server, draft_pointWinner: state.draft_pointWinner, draft_serveIn: state.draft_serveIn, draft_rallyLength: state.draft_rallyLength, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, matchFormatIndex: state.matchFormatIndex, setsToWin: state.setsToWin, entries: state.entries, draft_server: state.draft_server, draft_pointWinner: state.draft_pointWinner, draft_serveIn: state.draft_serveIn, draft_rallyLength: state.draft_rallyLength, settingsOpen: state.settingsOpen};
}





function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, matchFormatIndex: state.matchFormatIndex, setsToWin: state.setsToWin, entries: state.entries, draft_server: state.draft_server, draft_pointWinner: state.draft_pointWinner, draft_serveIn: state.draft_serveIn, draft_rallyLength: state.draft_rallyLength, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

