import * as ui from "std/ui"

@jsonable
class AppState {
  currentAge: number;
  retirementAge: number;
  currentBalanceText: string;
  yearlyContributionText: string;
  annualReturnText: string;
  salaryGrowthText: string;
  settingsOpen: boolean;
}

function init(): AppState {
  return {currentAge: 35, retirementAge: 65, currentBalanceText: "50000", yearlyContributionText: "6000", annualReturnText: "7", salaryGrowthText: "2", settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_currentAge(state: AppState, value: number): AppState {
  return {currentAge: value, retirementAge: state.retirementAge, currentBalanceText: state.currentBalanceText, yearlyContributionText: state.yearlyContributionText, annualReturnText: state.annualReturnText, salaryGrowthText: state.salaryGrowthText, settingsOpen: state.settingsOpen};
}

function set_retirementAge(state: AppState, value: number): AppState {
  return {retirementAge: value, currentAge: state.currentAge, currentBalanceText: state.currentBalanceText, yearlyContributionText: state.yearlyContributionText, annualReturnText: state.annualReturnText, salaryGrowthText: state.salaryGrowthText, settingsOpen: state.settingsOpen};
}

function set_currentBalance(state: AppState, value: string): AppState {
  return {currentBalanceText: value, currentAge: state.currentAge, retirementAge: state.retirementAge, yearlyContributionText: state.yearlyContributionText, annualReturnText: state.annualReturnText, salaryGrowthText: state.salaryGrowthText, settingsOpen: state.settingsOpen};
}

function set_yearlyContribution(state: AppState, value: string): AppState {
  return {yearlyContributionText: value, currentAge: state.currentAge, retirementAge: state.retirementAge, currentBalanceText: state.currentBalanceText, annualReturnText: state.annualReturnText, salaryGrowthText: state.salaryGrowthText, settingsOpen: state.settingsOpen};
}

function set_annualReturn(state: AppState, value: string): AppState {
  return {annualReturnText: value, currentAge: state.currentAge, retirementAge: state.retirementAge, currentBalanceText: state.currentBalanceText, yearlyContributionText: state.yearlyContributionText, salaryGrowthText: state.salaryGrowthText, settingsOpen: state.settingsOpen};
}

function set_salaryGrowth(state: AppState, value: string): AppState {
  return {salaryGrowthText: value, currentAge: state.currentAge, retirementAge: state.retirementAge, currentBalanceText: state.currentBalanceText, yearlyContributionText: state.yearlyContributionText, annualReturnText: state.annualReturnText, settingsOpen: state.settingsOpen};
}







function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, currentAge: state.currentAge, retirementAge: state.retirementAge, currentBalanceText: state.currentBalanceText, yearlyContributionText: state.yearlyContributionText, annualReturnText: state.annualReturnText, salaryGrowthText: state.salaryGrowthText};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Retirement Fund Estimate", "RETIREMENT", "See how your savings grow by retirement", ""));
  {
      let currentAge: number = state.currentAge;
      let retirementAge: number = state.retirementAge;
      let currentBalance: number = strings.toNumber(state.currentBalanceText, 0);
      let yearlyContribution: number = strings.toNumber(state.yearlyContributionText, 0);
      let annualReturn: number = strings.toNumber(state.annualReturnText, 0);
      let salaryGrowth: number = strings.toNumber(state.salaryGrowthText, 0);
      let yearsToRetirement: number = (retirementAge - currentAge);
      let balanceGrowth: number = (currentBalance * math.pow((1 + share(annualReturn, 100)), yearsToRetirement));
    sections.push(ui.Section("content", "", "", [ui.NumberField("default", "Current age (years)", state.currentAge, 18, 80, "set_currentAge"), ui.TextField("default", "Current balance ($)", state.currentBalanceText, "set_currentBalance", "number"), ui.TextField("default", "Yearly contribution ($)", state.yearlyContributionText, "set_yearlyContribution", "number"), ui.TextField("default", "Annual return (%)", state.annualReturnText, "set_annualReturn", "number")]));
  }
  {
    let settingsWord: string = "Show";
    if (state.settingsOpen) { settingsWord = "Hide"; }
    sections.push(ui.Section("supporting", "", "", [
      ui.ListItem("default", "Settings", "2 settings", settingsWord, "toggleSettings", 0, true, ""),
      ui.When(state.settingsOpen, ui.Column("default", [ui.NumberField("default", "Retirement age (years)", state.retirementAge, 40, 90, "set_retirementAge"), ui.TextField("default", "Contribution growth (%)", state.salaryGrowthText, "set_salaryGrowth", "number")]))
    ]));
  }
  return ui.AppTheme("technical", "", sections);
}

