import * as ui from "std/ui"

@jsonable
class LogEntry {
  name: string;
  minute: number;
}

@jsonable
class AppState {
  stallCount: number;
  avgMinutes: number;
  entries: LogEntry[];
  draft_name: string;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {stallCount: 2, avgMinutes: 5, entries: emptyEntries, draft_name: "", removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_stallCount(state: AppState, value: number): AppState {
  return {stallCount: value, avgMinutes: state.avgMinutes, entries: state.entries, draft_name: state.draft_name, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_avgMinutes(state: AppState, value: number): AppState {
  return {avgMinutes: value, stallCount: state.stallCount, entries: state.entries, draft_name: state.draft_name, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_name(state: AppState, value: string): AppState {
  return {draft_name: value, stallCount: state.stallCount, avgMinutes: state.avgMinutes, entries: state.entries, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_name) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {name: strings.trim(state.draft_name), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_name: "", stallCount: state.stallCount, avgMinutes: state.avgMinutes, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, stallCount: state.stallCount, avgMinutes: state.avgMinutes, draft_name: state.draft_name, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, stallCount: state.stallCount, avgMinutes: state.avgMinutes, draft_name: state.draft_name, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, stallCount: state.stallCount, avgMinutes: state.avgMinutes, entries: state.entries, draft_name: state.draft_name, settingsOpen: state.settingsOpen};
}





function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, stallCount: state.stallCount, avgMinutes: state.avgMinutes, entries: state.entries, draft_name: state.draft_name, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Bathroom Line", "VIRTUAL QUEUE", "Join the line, see your place, get called when it's your turn", ""));
  {
      let stallCount: number = state.stallCount;
      let avgMinutes: number = state.avgMinutes;
      let entryCount: number = state.entries.length();
      let entryTotal: number = 0;
      let peopleAhead: number = entryCount - stallCount;
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 1, [ui.NumberStat("default", "People ahead", peopleAhead, "", " people", 1, "", "chart", 0)])]));
    let rows: ui.View[] = [];
    let i: number = entryCount - 1;
    while (i >= 0 && i > entryCount - 21) {
      let e: LogEntry = state.entries[i];
      let sub: string = "Added " + ui.clockToString(e.minute);
      rows.push(ui.ListItem("default", e.name, sub, "", "", 0, false, ""));
      rows.push(ui.ActionBar("end", [ui.Button("secondary", "Remove", "removeEntry", i, true)]));
      i = i - 1;
    }
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Name", state.draft_name, "set_draft_name"), ui.ActionBar("end", [ui.Button("primary", "Add", "addEntry", 0, strings.trim(state.draft_name) !== "")])]));
    sections.push(ui.Section("content", "", "", [ui.SectionHeader("default", "People in line", "Newest first", ui.numberToString(entryCount)), ui.When(entryCount === 0, ui.EmptyState("default", "Nothing added yet", "Fill in the fields above and tap Add.", "", "", "list")), ui.When(entryCount > 0, ui.ListGroup("default", "", rows)), ui.When(state.removedEntries.length() > 0, ui.Snackbar("default", "Removed", "Undo", "undoRemove")), ui.Ticker("default", "undoClock", 6000 + state.entries.length() % 7, state.removedEntries.length() > 0, "expireUndo")]));
  }
  {
    let settingsWord: string = "Show";
    if (state.settingsOpen) { settingsWord = "Hide"; }
    sections.push(ui.Section("supporting", "", "", [
      ui.ListItem("default", "Settings", "2 settings", settingsWord, "toggleSettings", 0, true, ""),
      ui.When(state.settingsOpen, ui.Column("default", [ui.NumberField("default", "Stalls", state.stallCount, 1, 10, "set_stallCount"), ui.NumberField("default", "Average visit (minutes)", state.avgMinutes, 1, 30, "set_avgMinutes")]))
    ]));
  }
  return ui.AppTheme("clean", "", sections);
}

