import * as ui from "std/ui"

@jsonable
class LogEntry {
  name: string;
  rank: number;
  minute: number;
}

@jsonable
class AppState {
  seatsPerRow: number;
  seatOrderIndex: number;
  entries: LogEntry[];
  draft_name: string;
  draft_rank: string;
  removedEntries: LogEntry[];
  removedAt: number;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {seatsPerRow: 6, seatOrderIndex: 0, entries: emptyEntries, draft_name: "", draft_rank: "", removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_seatsPerRow(state: AppState, value: number): AppState {
  return {seatsPerRow: value, seatOrderIndex: state.seatOrderIndex, entries: state.entries, draft_name: state.draft_name, draft_rank: state.draft_rank, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_seatOrder(state: AppState, value: number): AppState {
  return {seatOrderIndex: value, seatsPerRow: state.seatsPerRow, entries: state.entries, draft_name: state.draft_name, draft_rank: state.draft_rank, removedEntries: state.removedEntries, removedAt: state.removedAt};
}



function set_draft_name(state: AppState, value: string): AppState {
  return {draft_name: value, seatsPerRow: state.seatsPerRow, seatOrderIndex: state.seatOrderIndex, entries: state.entries, draft_rank: state.draft_rank, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_rank(state: AppState, value: string): AppState {
  return {draft_rank: value, seatsPerRow: state.seatsPerRow, seatOrderIndex: state.seatOrderIndex, entries: state.entries, draft_name: state.draft_name, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_name) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {name: strings.trim(state.draft_name), rank: strings.toNumber(state.draft_rank, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_name: "", draft_rank: "", seatsPerRow: state.seatsPerRow, seatOrderIndex: state.seatOrderIndex, removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, seatsPerRow: state.seatsPerRow, seatOrderIndex: state.seatOrderIndex, draft_name: state.draft_name, draft_rank: state.draft_rank};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, seatsPerRow: state.seatsPerRow, seatOrderIndex: state.seatOrderIndex, draft_name: state.draft_name, draft_rank: state.draft_rank};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, seatsPerRow: state.seatsPerRow, seatOrderIndex: state.seatOrderIndex, entries: state.entries, draft_name: state.draft_name, draft_rank: state.draft_rank};
}





