  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Seating by Seniority", "SEATING PLAN", "Order the room by rank, then seat it row by row.", ""));
  {
      let seatsPerRow: number = state.seatsPerRow;
      let seatOrderValues: number[] = [0, 1];
      let seatOrder: number = seatOrderValues[state.seatOrderIndex];
      let seatGap: number = 1;
      let entryCount: number = state.entries.length();
      let entryTotal: number = 0;
      for (let e: LogEntry of state.entries) { entryTotal = entryTotal + e.rank; }
      let seatCount: number = entryCount;
