    sections.push(ui.Section("content", "", "", [ui.NumberField("default", "Seats per row", state.seatsPerRow, 1, 20, "set_seatsPerRow"), ui.Select("default", "Fill order", ["Front to back", "Back to front"], state.seatOrderIndex, "set_seatOrder")]));
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 2, [ui.NumberStat("default", "Seats needed", seatCount, "", " seats", 1, "", "chart", 0), ui.NumberStat("default", "Rows needed", rowCount, "", " rows", 1, "", "chart", 0)])]));
    let rows: ui.View[] = [];
