function c_matchRow(m: C_Match, index: number, scores: number[]): ui.View {
  let title: string = c_name(m.a) + " vs " + c_name(m.b);
  let trailing: string = "";
  let enabled: boolean = false;
  let subtitle: string = m.label;
  if (m.done) {
    let sc: number = 0;
    if (index < scores.length()) { sc = scores[index]; }
    trailing = c_name(m.winner) + " advances";
    subtitle = m.label + " · " + c_name(m.winner) + " " + ui.numberToString(sc) + "–" + ui.numberToString(0);
  } else if (m.a > 0 && m.b > 0) {
    trailing = "tap to record";
    enabled = true;
  } else {
    trailing = "waiting";
  }
  let icon: string = "clock";
  if (m.done) { icon = "check"; }
  return ui.ListItem("default", title, subtitle, trailing, "c_pick", index, enabled, icon);
}

function c_roundRows(matches: C_Match[], scores: number[], bracket: string, round: number): ui.View[] {
  let rows: ui.View[] = [];
  let i: number = 0;
  while (i < matches.length()) {
    let m: C_Match = matches[i];
    if (m.bracket === bracket && m.round === round) {
      rows.push(c_matchRow(m, i, scores));
    }
    i = i + 1;
  }
  return rows;
}
