import * as ui from "std/ui"

@jsonable
class LogEntry {
  voterName: string;
  songChoice: number;
  minute: number;
}

@jsonable
class AppState {
  entries: LogEntry[];
  draft_voterName: string;
  draft_songChoice: string;
  removedEntries: LogEntry[];
  removedAt: number;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {entries: emptyEntries, draft_voterName: "", draft_songChoice: "", removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}







function set_draft_voterName(state: AppState, value: string): AppState {
  return {draft_voterName: value, entries: state.entries, draft_songChoice: state.draft_songChoice, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_songChoice(state: AppState, value: string): AppState {
  return {draft_songChoice: value, entries: state.entries, draft_voterName: state.draft_voterName, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_voterName) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {voterName: strings.trim(state.draft_voterName), songChoice: strings.toNumber(state.draft_songChoice, 0), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_voterName: "", draft_songChoice: "", removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, draft_voterName: state.draft_voterName, draft_songChoice: state.draft_songChoice};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, draft_voterName: state.draft_voterName, draft_songChoice: state.draft_songChoice};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, entries: state.entries, draft_voterName: state.draft_voterName, draft_songChoice: state.draft_songChoice};
}





function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Playlist Vote", "OFFICE VOTE", "Vote for the office playlist winner", ""));
  {
      let entryCount: number = state.entries.length();
      let entryTotal: number = 0;
      for (let e: LogEntry of state.entries) { entryTotal = entryTotal + e.songChoice; }
      let totalVotes: number = entryCount;
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 1, [ui.NumberStat("default", "Votes cast", totalVotes, "", "", 1, "", "chart", 0)])]));
    let rows: ui.View[] = [];
    let i: number = entryCount - 1;
    while (i >= 0 && i > entryCount - 21) {
      let e: LogEntry = state.entries[i];
      let sub: string = "Added " + ui.clockToString(e.minute);
      rows.push(ui.ListItem("default", e.voterName, sub, ui.formatNumber(e.songChoice, 0), "", 0, false, ""));
      rows.push(ui.ActionBar("end", [ui.Button("secondary", "Remove", "removeEntry", i, true)]));
      i = i - 1;
    }
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Voter", state.draft_voterName, "set_draft_voterName"), ui.TextField("default", "Pick", state.draft_songChoice, "set_draft_songChoice", "number"), ui.ActionBar("end", [ui.Button("primary", "Add", "addEntry", 0, strings.trim(state.draft_voterName) !== "")])]));
    sections.push(ui.Section("content", "", "", [ui.SectionHeader("default", "Votes", "Newest first", ui.numberToString(entryCount)), ui.When(entryCount === 0, ui.EmptyState("default", "Nothing added yet", "Fill in the fields above and tap Add.", "", "", "list")), ui.When(entryCount > 0, ui.ListGroup("default", "", rows)), ui.When(state.removedEntries.length() > 0, ui.Snackbar("default", "Removed", "Undo", "undoRemove")), ui.Ticker("default", "undoClock", 6000 + state.entries.length() % 7, state.removedEntries.length() > 0, "expireUndo")]));
  }
  return ui.AppTheme("playful", "", sections);
}

