import * as ui from "std/ui"

@jsonable
class LogEntry {
  voterName: string;
  topping: string;
  minute: number;
}

@jsonable
class AppState {
  voterName: string;
  entries: LogEntry[];
  draft_voterName: string;
  draft_topping: string;
  removedEntries: LogEntry[];
  removedAt: number;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {voterName: "", entries: emptyEntries, draft_voterName: "", draft_topping: "", removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_voterName(state: AppState, value: string): AppState {
  return {voterName: value, entries: state.entries, draft_voterName: state.draft_voterName, draft_topping: state.draft_topping, removedEntries: state.removedEntries, removedAt: state.removedAt};
}



function set_draft_voterName(state: AppState, value: string): AppState {
  return {draft_voterName: value, voterName: state.voterName, entries: state.entries, draft_topping: state.draft_topping, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_topping(state: AppState, value: string): AppState {
  return {draft_topping: value, voterName: state.voterName, entries: state.entries, draft_voterName: state.draft_voterName, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_voterName) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {voterName: strings.trim(state.draft_voterName), topping: strings.trim(state.draft_topping), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_voterName: "", draft_topping: "", voterName: state.voterName, removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, voterName: state.voterName, draft_voterName: state.draft_voterName, draft_topping: state.draft_topping};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, voterName: state.voterName, draft_voterName: state.draft_voterName, draft_topping: state.draft_topping};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, voterName: state.voterName, entries: state.entries, draft_voterName: state.draft_voterName, draft_topping: state.draft_topping};
}





function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Pizza Topping Poll", "TOPPING POLL", "Vote for the best pizza topping", ""));
  {
      let entryCount: number = state.entries.length();
      let entryTotal: number = 0;
      let totalVotes: number = entryCount;
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Your name", state.voterName, "set_voterName")]));
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 1, [ui.NumberStat("default", "Votes cast", totalVotes, "", "", 1, "", "chart", 0)])]));
    let rows: ui.View[] = [];
    let i: number = entryCount - 1;
    while (i >= 0 && i > entryCount - 21) {
      let e: LogEntry = state.entries[i];
      let sub: string = e.topping + " · " + "Added " + ui.clockToString(e.minute);
      rows.push(ui.ListItem("default", e.voterName, sub, "", "", 0, false, ""));
      rows.push(ui.ActionBar("end", [ui.Button("secondary", "Remove", "removeEntry", i, true)]));
      i = i - 1;
    }
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Voter", state.draft_voterName, "set_draft_voterName"), ui.TextField("default", "Topping", state.draft_topping, "set_draft_topping"), ui.ActionBar("end", [ui.Button("primary", "Add", "addEntry", 0, strings.trim(state.draft_voterName) !== "")])]));
    sections.push(ui.Section("content", "", "", [ui.SectionHeader("default", "Votes", "Newest first", ui.numberToString(entryCount)), ui.When(entryCount === 0, ui.EmptyState("default", "Nothing added yet", "Fill in the fields above and tap Add.", "", "", "list")), ui.When(entryCount > 0, ui.ListGroup("default", "", rows)), ui.When(state.removedEntries.length() > 0, ui.Snackbar("default", "Removed", "Undo", "undoRemove")), ui.Ticker("default", "undoClock", 6000 + state.entries.length() % 7, state.removedEntries.length() > 0, "expireUndo")]));
  }
  return ui.AppTheme("playful", "", sections);
}

