import * as ui from "std/ui"

@jsonable
class AppState {
  elapsedMs: number;
  running: boolean;
  finished: boolean;
  totalTimeIndex: number;
  workTimeText: string;
  restTimeText: string;
  effectStatus: string;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, totalTimeIndex: 2, workTimeText: "40", restTimeText: "20", effectStatus: ""};
}

function countdownSeconds(state: AppState): number {
  let totalTimeValues: number[] = [300, 600, 900, 1200, 1800];
  let totalTime: number = totalTimeValues[state.totalTimeIndex];
  let workTime: number = strings.toNumber(state.workTimeText, 0);
  let restTime: number = strings.toNumber(state.restTimeText, 0);
  let roundSeconds: number = 60;
  return totalTime;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, totalTimeIndex: state.totalTimeIndex, workTimeText: state.workTimeText, restTimeText: state.restTimeText, effectStatus: state.effectStatus}; }
  sdk.call("AudioKit.TonePlayer.start", ["type", "DOUBLE_BEEP"], "onEffect");
  return {elapsedMs: total, running: false, finished: true, effectStatus: "pending", totalTimeIndex: state.totalTimeIndex, workTimeText: state.workTimeText, restTimeText: state.restTimeText};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, totalTimeIndex: state.totalTimeIndex, workTimeText: state.workTimeText, restTimeText: state.restTimeText, effectStatus: state.effectStatus};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, totalTimeIndex: state.totalTimeIndex, workTimeText: state.workTimeText, restTimeText: state.restTimeText, effectStatus: state.effectStatus};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, totalTimeIndex: state.totalTimeIndex, workTimeText: state.workTimeText, restTimeText: state.restTimeText, effectStatus: state.effectStatus};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_totalTime(state: AppState, value: number): AppState {
  return {totalTimeIndex: value, elapsedMs: 0, running: false, finished: false, workTimeText: state.workTimeText, restTimeText: state.restTimeText, effectStatus: state.effectStatus};
}

function set_workTime(state: AppState, value: string): AppState {
  return {workTimeText: value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, totalTimeIndex: state.totalTimeIndex, restTimeText: state.restTimeText, effectStatus: state.effectStatus};
}

function set_restTime(state: AppState, value: string): AppState {
  return {restTimeText: value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, totalTimeIndex: state.totalTimeIndex, workTimeText: state.workTimeText, effectStatus: state.effectStatus};
}



function onEffect(state: AppState, value: string): AppState {
  return {effectStatus: value, elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, totalTimeIndex: state.totalTimeIndex, workTimeText: state.workTimeText, restTimeText: state.restTimeText};
}



function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "HIIT Timer", "QUICK HIIT", "Work and rest intervals until your time limit runs out.", "clock"));
  {
    sections.push(ui.Ticker("default", "clock", 200, state.running, "onTick"));
      let totalTimeValues: number[] = [300, 600, 900, 1200, 1800];
      let totalTime: number = totalTimeValues[state.totalTimeIndex];
      let workTime: number = strings.toNumber(state.workTimeText, 0);
      let restTime: number = strings.toNumber(state.restTimeText, 0);
      let roundSeconds: number = 60;
      let duration: number = countdownSeconds(state);
      let elapsed: number = math.min(state.elapsedMs / 1000, duration);
      let remaining: number = duration - elapsed;
      let roundLength: number = workTime + restTime;
      let rounds: number = math.floor(share(totalTime, roundLength));
      let effectNote: string = "Phone: " + state.effectStatus;
      if (state.effectStatus === "pending") { effectNote = "Asking the phone..."; }
    sections.push(ui.Section("hero", "", "", [ui.Hero("accent", "HIIT session", ui.durationToString(math.ceil(remaining)), "", [ui.ActionBar("spread", [ui.Button("primary", "Start", "onStart", 0, !state.running), ui.Button("secondary", "Stop", "onStop", 0, state.running), ui.Button("secondary", "Reset", "onReset", 0, true)])])]));
    sections.push(ui.Section("content", "", "", [ui.Select("default", "Time limit", ["5 min", "10 min", "15 min", "20 min", "30 min"], state.totalTimeIndex, "set_totalTime"), ui.TextField("default", "Work interval (seconds)", state.workTimeText, "set_workTime", "number"), ui.TextField("default", "Rest interval (seconds)", state.restTimeText, "set_restTime", "number")]));
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 1, [ui.NumberStat("default", "Rounds", rounds, "", " rounds", 1, "", "chart", 0)])]));
    sections.push(ui.When(state.effectStatus !== "", ui.InsetBanner("default", "Done", effectNote, "", "", "info")));
  }
  return ui.AppTheme("technical", "", sections);
}
